  <rect width="512" height="512" fill="#0f172a" rx="80"/>
  <text x="256" y="340" font-family="Arial, sans-serif" font-size="280" font-weight="bold"
        text-anchor="middle" fill="white">R</text>
</svg>`;
fs.writeFileSync('public/logo_v2.svg', svgContent);
console.log('✓ Gerado: public/logo_v2.svg (SVG real)');

console.log('\n✅ Todos os ícones PWA gerados com sucesso!');

const { createClient } = require('@supabase/supabase-js');
const dotenv = require('dotenv');
dotenv.config();

const supabaseUrl = process.env.VITE_SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.VITE_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseKey) {
  console.error("Supabase config not found");
  process.exit(1);
}

const supabase = createClient(supabaseUrl, supabaseKey);

async function check() {
  console.log("Checking 'Cliente' table...");
  const { data: clientes, error: errClient } = await supabase.from('Cliente').select('*');
  if (errClient) {
    console.error("Error fetching Cliente:", errClient);
  } else {
    console.log(`Found ${clientes.length} clients.`);
    const suspicious = clientes.filter(c => c.sequencia_decrescente);
    console.log("Clients with sequencia_decrescente=true:", suspicious.map(c => ({ id: c.id, nome: c.nome, label: c.sequencia_label })));
  }

  console.log("\nChecking 'Setor' table...");
  const { data: setores, error: errSetor } = await supabase.from('Setores').select('*');
  if (errSetor) {
     const { data: setores2, error: errSetor2 } = await supabase.from('Setor').select('*');
     if (errSetor2) console.error("Error fetching Setor/Setores:", errSetor2);
     else console.log(`Found ${setores2.length} sectors.`, setores2.map(s => s.nome));
  } else {
    console.log(`Found ${setores.length} sectors.`, setores.map(s => s.nome));
  }
}
check();

import { app, BrowserWindow } from 'electron';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

function createWindow() {
    const win = new BrowserWindow({
        width: 1200,
        height: 800,
        title: "PCP Matrix - Industrial Intelligence Hub",
        icon: path.join(__dirname, process.defaultApp || process.argv.includes('--dev') ? 'public/pcp-matrix-icon.png' : 'dist/electron-icon.png'),
        webPreferences: {
            nodeIntegration: true,
            contextIsolation: false,
            webSecurity: false,
            devTools: false
        }
    });

    // Desativado: win.webContents.on('dom-ready', () => { ... });

    // Load Vite's dev server if running in development
    if (process.defaultApp || process.argv.includes('--dev')) {
        win.loadURL('http://localhost:5173');
    } else {
        // In production, load the built index.html with absolute path
        const indexPath = path.join(__dirname, 'dist', 'index.html');
        console.log('Loading production HTML from:', indexPath);
        win.loadFile(indexPath).catch(e => {
            console.error('Failed to load local HTML:', e);
        });
    }
}

app.whenReady().then(async () => {
    const { session } = await import('electron');
    // RIGOROUS SESSION CLEARING ON STARTUP
    try {
        await session.defaultSession.clearStorageData({
            storages: ['localstorage', 'cookies', 'sessionstorage', 'indexdb', 'cachestorage'],
        });
        console.log('App storage cleared successfully on startup');
    } catch (err) {
        console.error('Failed to clear storage:', err);
    }

    createWindow();

    app.on('activate', () => {
        if (BrowserWindow.getAllWindows().length === 0) createWindow();
    });
});

app.on('window-all-closed', () => {
    if (process.platform !== 'darwin') app.quit();
});

