    ...pluginReact.configs.flat.recommended,
    languageOptions: {
      globals: globals.browser,
      parserOptions: {
        ecmaVersion: 2022,
        sourceType: "module",
        ecmaFeatures: {
          jsx: true,
        },
      },
    },
    settings: {
      react: {
        version: "detect",
      },
    },
    plugins: {
      react: pluginReact,
      "react-hooks": pluginReactHooks,
      "unused-imports": pluginUnusedImports,
    },
    rules: {
      "no-unused-vars": "off",
      "react/jsx-uses-vars": "error",
      "react/jsx-uses-react": "error",
      "unused-imports/no-unused-imports": "error",
      "unused-imports/no-unused-vars": [
        "warn",
        {
          vars: "all",
          varsIgnorePattern: "^_",
          args: "after-used",
          argsIgnorePattern: "^_",
        },
      ],
      "react/prop-types": "off",
      "react/react-in-jsx-scope": "off",
      "react/no-unknown-property": [
        "error",
        { ignore: ["cmdk-input-wrapper", "toast-close"] },
      ],
      "react-hooks/rules-of-hooks": "error",
    },
  },
];

const fs = require('fs');
const path = require('path');

const extractEntities = (dir, entities = new Set()) => {
    const files = fs.readdirSync(dir);
    for (const file of files) {
        const fullPath = path.join(dir, file);
        if (fs.statSync(fullPath).isDirectory()) {
            extractEntities(fullPath, entities);
        } else if (file.endsWith('.js') || file.endsWith('.jsx') || file.endsWith('.ts') || file.endsWith('.tsx')) {
            const content = fs.readFileSync(fullPath, 'utf8');
            const matches = content.matchAll(/rdsn\.(asServiceRole\.)?entities\.([A-Za-z0-9_]+)\./g);
            for (const match of matches) {
                entities.add(match[2]);
            }
        }
    }
    return entities;
};

const entities = extractEntities(path.join(__dirname, 'src'));
extractEntities(path.join(__dirname, 'functions'), entities);

let sql = `-- Supabase Automated Migration generated by Antigravity\n\n`;

for (const entity of entities) {
    sql += `CREATE TABLE IF NOT EXISTS public."${entity}" (\n`;
    sql += `  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n`;
    sql += `  created_at TIMESTAMPTZ DEFAULT now(),\n`;
    sql += `  j_data JSONB DEFAULT '{}'::jsonb -- Stores dynamic columns until strongly typed\n`;
    sql += `);\n\n`;

    // Enable RLS but allow everything for now since it's an internal admin tool
    sql += `ALTER TABLE public."${entity}" ENABLE ROW LEVEL SECURITY;\n`;
    sql += `DROP POLICY IF EXISTS "Allow All" ON public."${entity}";\n`;
    sql += `CREATE POLICY "Allow All" ON public."${entity}" FOR ALL USING (true) WITH CHECK (true);\n\n`;
}

fs.writeFileSync(path.join(__dirname, 'supabase_migration.sql'), sql);
console.log('Migration generated at supabase_migration.sql');

const { createClient } = require('@supabase/supabase-js');
const dotenv = require('dotenv');
dotenv.config();

const supabaseUrl = process.env.VITE_SUPABASE_URL;
const supabaseKey = process.env.VITE_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseKey) {
  console.error("Supabase config não encontrada");
  process.exit(1);
}

const supabase = createClient(supabaseUrl, supabaseKey);

async function check() {
  const { data: clientes, error: err1 } = await supabase.from('clientes').select('*');
  if (err1) console.error(err1);
  else console.log("Clientes:", clientes.length, clientes.filter(c => c.sequencia_decrescente).map(c => c.id + " - " + c.nome));
}
check();

