                    }))}
                    className="dark:bg-slate-900"
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>
          </div>

          {/* Resumo de Filtros Ativos */}
          {hasActiveFilters && (
            <div className="pt-3 border-t border-slate-200 dark:border-slate-800">
