// @ts-nocheck
import React, { useState, useMemo } from 'react';
import { useQuery, useMutation, useQueryClient, keepPreviousData } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { useSetor } from '@/components/context/SetorContext';
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Plus, Clock } from "lucide-react";
import { toast } from "sonner";
import { calcularQuantidade } from '@/core/numeracaoService';

import ProducaoDiaCard from './ProducaoDiaCard';
import NovaProducaoDiaDialog from './NovaProducaoDiaDialog';

export default function ModoProducaoDia({ reservas, produtos, setorInfo }) {
  const queryClient = useQueryClient();
  const { setorAtivo, isAdmin, currentUser } = useSetor();
  const [showNova, setShowNova] = useState(false);

  const isSupervisor = currentUser?.role_custom === 'Admin' || currentUser?.role_custom === 'Supervisor';

  // Buscar setores
  const { data: setores = [] } = useQuery({
    queryKey: ['setores'],
    queryFn: () => rdsn.entities.Setor.list()
  });

  const setorNome = useMemo(() => {
    const setor = setores.find(s => s.id === setorAtivo);
    return setor?.nome || '';
  }, [setores, setorAtivo]);

  // Buscar sessões de produção abertas
  const { data: sessoesAbertas = [], isLoading: loadingSessoes } = useQuery({
    queryKey: ['producao-dia', setorAtivo],
    queryFn: async () => {
      if (!setorAtivo) return [];
      const filtro = isAdmin && setorAtivo === 'ALL'
        ? { status: { $in: ['ABERTA', 'EM_PRODUCAO', 'AGUARDANDO_BAIXA'] } }
        : { status: { $in: ['ABERTA', 'EM_PRODUCAO', 'AGUARDANDO_BAIXA'] }, setor_id: setorAtivo };
      return await rdsn.entities.ProducaoDia.filter(filtro, '-created_at', 20);
    },
    placeholderData: keepPreviousData,
    enabled: !!setorAtivo
  });

  // Buscar lotes das sessões abertas
  const sessaoIds = useMemo(() => sessoesAbertas.map(s => s.id), [sessoesAbertas]);
  const { data: lotesAbertos = [], isLoading: loadingLotes } = useQuery({
    queryKey: ['producao-dia-lotes', sessaoIds],
    queryFn: async () => {
      if (sessaoIds.length === 0) return [];
      const todosLotes = await Promise.all(
        sessaoIds.map(id => rdsn.entities.ProducaoDiaLote.filter({ producao_dia_id: id }))
      );
      return todosLotes.flat();
    },
    enabled: sessaoIds.length > 0,
    placeholderData: keepPreviousData
  });

  // Buscar baixas para sugestão de numeração
  const { data: baixas = [] } = useQuery({
    queryKey: ['baixas-producao-dia'],
    queryFn: () => rdsn.entities.BaixaLote.list('-created_at', 500),
  });

  const baixasPorReserva = useMemo(() => {
    const map = {};
    baixas.forEach(b => {
      if (!map[b.reserva_id]) map[b.reserva_id] = [];
      map[b.reserva_id].push(b);
    });
    return map;
  }, [baixas]);

  // IDs de lotes já em sessões abertas
  const lotesJaAbertosIds = useMemo(() => {
    return lotesAbertos.filter(l => l.status === 'ABERTO').map(l => l.reserva_id);
  }, [lotesAbertos]);

  const lotesAtivos = lotesAbertos.filter(l => l.status === 'ABERTO');

  // Reservas indexadas por ID
  const reservasMap = useMemo(() => {
    const m = {};
    reservas.forEach(r => m[r.id] = r);
    return m;
  }, [reservas]);

  // Mutation: Criar nova sessão + lotes
  const iniciarProducaoMutation = useMutation({
    mutationFn: async (lotes) => {
      const hoje = new Date().toISOString().split('T')[0];

      // Criar sessão
      const sessao = await rdsn.entities.ProducaoDia.create({
        data_producao: hoje,
        usuario_id: currentUser?.id || '',
        usuario_nome: currentUser?.full_name || '',
        setor_id: setorAtivo === 'ALL' ? lotes[0].reserva.setor_id : setorAtivo,
        status: 'ABERTA'
      });

      // Criar lotes na sessão
      await Promise.all(lotes.map(l => {
        // l.sequencia_decrescente é definido no handleToggle do NovaProducaoDiaDialog
        // Fallback para reserva e produto caso não esteja presente
        const reservaObj = l.reserva || l.reserva_original;
        const isDecrescente = l.sequencia_decrescente === true || reservaObj?.sequencia_decrescente === true;
        return rdsn.entities.ProducaoDiaLote.create({
          producao_dia_id: sessao.id,
          reserva_id: l.reserva_id,
          letra_produto: reservaObj?.letra_produto,
          codigo_completo: reservaObj?.codigo_completo,
          cliente: reservaObj?.cliente,
          codigo_produto: reservaObj?.codigo_produto,
          modelo: reservaObj?.modelo,
          numeracao_inicial: l.numeracao_inicial,
          sequencia_decrescente: isDecrescente,
          status: 'ABERTO',
          setor_id: reservaObj?.setor_id
        });
      }));

      // Log de auditoria
      await rdsn.entities.Auditoria.create({
        entidade: 'ProducaoDia',
        entidade_id: sessao.id,
        acao: 'RESERVA_CRIADA',
        detalhes: JSON.stringify({
          tipo_evento: 'ABERTURA_PRODUCAO_DIA',
          lotes: lotes.map(l => ({
            reserva_id: l.reserva_id,
            codigo: l.reserva.codigo_completo,
            numeracao_inicial: l.numeracao_inicial
          })),
          operador: currentUser?.full_name
        })
      });

      return sessao;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['producao-dia'] });
      queryClient.invalidateQueries({ queryKey: ['producao-dia-lotes'] });
      setShowNova(false);
      toast.success('Produção do dia iniciada!');
    },
    onError: (err) => {
      toast.error('Erro ao iniciar produção: ' + err.message);
    }
  });

  // Mutation: Fechar lote (gerar baixa automática)
  const fecharLoteMutation = useMutation({
    mutationFn: async ({ lote, numInicial, numFinal, ordemDecrescente, qtty }) => {
      const reserva = reservasMap[lote.reserva_id];
      if (!reserva) throw new Error('Reserva não encontrada');

      const ini = Number(numInicial ?? lote.numeracao_inicial) || 0;
      const fim = Number(numFinal) || 0;
      const isDec = ordemDecrescente ?? (lote.sequencia_decrescente === true);
      const quantidade = Number(qtty) || calcularQuantidade(ini, fim, isDec);

      // Na BaixaLote, numero_inicial sempre <= numero_final (representação do intervalo físico)
      const numInicialBaixa = Math.min(ini, fim);
      const numFinalBaixa = Math.max(ini, fim);

      // Buscar descrição do produto
      const produtoInfo = produtos.find(p => p.letra_produto === reserva.letra_produto);
      const descricaoItem = produtoInfo?.descricao || '';

      // Criar baixa (mesmo fluxo do sistema atual, com todos os campos)
      const baixa = await rdsn.entities.BaixaLote.create({
        reserva_id: reserva.id,
        numero_inicial: numInicialBaixa,
        numero_final: numFinalBaixa,
        quantidade,
        tipo: 'MANUAL',
        de_setor: '151',
        para_setor: '842',
        local: 'S11',
        local_destino: 'S31',
        setor_producao: setorNome,
        descricao_item: descricaoItem,
        operador: currentUser?.full_name || ''
      });

      // Atualizar reserva
      const novaBaixada = (reserva.quantidade_baixada || 0) + quantidade;
      const novoStatus = novaBaixada >= reserva.quantidade ? 'PRODUZIDO' : 'EM_PRODUCAO';
      await rdsn.entities.ReservaLote.update(reserva.id, {
        quantidade_baixada: novaBaixada,
        status: novoStatus
      });

      // Atualizar estoque
      const produto = produtos.find(p => p.letra_produto === reserva.letra_produto);
      if (produto) {
        const estoqueAnterior = produto.estoque_atual || 0;
        const estoqueNovo = estoqueAnterior + quantidade;
        await rdsn.entities.Produto.update(produto.id, { estoque_atual: estoqueNovo });
        await rdsn.entities.MovimentacaoEstoque.create({
          produto_id: produto.id,
          tipo: 'PRODUCAO',
          quantidade,
          quantidade_anterior: estoqueAnterior,
          quantidade_nova: estoqueNovo,
          referencia_id: baixa.id,
          referencia_tipo: 'BaixaLote',
          observacao: `Produção do dia - Lote ${reserva.codigo_completo}`,
          operador: currentUser?.full_name || ''
        });
      }

      // Atualizar lote da sessão
      await rdsn.entities.ProducaoDiaLote.update(lote.id, {
        numeracao_final: numFinal,
        quantidade_calculada: quantidade,
        status: 'FECHADO',
        baixa_id: baixa.id
      });

      // Auditoria
      await rdsn.entities.Auditoria.create({
        entidade: 'BaixaLote',
        entidade_id: baixa.id,
        acao: 'BAIXA_REGISTRADA',
        letra_produto: reserva.letra_produto,
        ano: reserva.ano,
        numero_inicial: numInicialBaixa,
        numero_final: numFinalBaixa,
        detalhes: JSON.stringify({
          tipo_evento: 'BAIXA_AUTOMATICA_DIA',
          quantidade,
          producao_dia_lote_id: lote.id,
          operador: currentUser?.full_name
        })
      });

      // Verificar se todos os lotes da sessão foram fechados
      const todosLotesSessao = await rdsn.entities.ProducaoDiaLote.filter({ producao_dia_id: lote.producao_dia_id });
      const todosAbertos = todosLotesSessao.filter(l => l.status === 'ABERTO');
      if (todosAbertos.length === 0) {
        await rdsn.entities.ProducaoDia.update(lote.producao_dia_id, {
          status: 'FECHADA',
          closed_at: new Date().toISOString()
        });
        // Auditoria de fechamento
        await rdsn.entities.Auditoria.create({
          entidade: 'ProducaoDia',
          entidade_id: lote.producao_dia_id,
          acao: 'RESERVA_CRIADA',
          detalhes: JSON.stringify({
            tipo_evento: 'FECHAMENTO_PRODUCAO_DIA',
            operador: currentUser?.full_name
          })
        });
      }

      return baixa;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['producao-dia'] });
      queryClient.invalidateQueries({ queryKey: ['producao-dia-lotes'] });
      queryClient.invalidateQueries({ queryKey: ['reservas-producao'] });
      queryClient.invalidateQueries({ queryKey: ['baixas-producao-dia'] });
      toast.success('Baixa registrada com sucesso!');
    },
    onError: (err) => {
      toast.error('Erro ao fechar: ' + err.message);
    }
  });

  // Fechar lote sem baixa (clicando no X) (apenas supervisor)
  const cancelarLoteMutation = useMutation({
    mutationFn: async (lote) => {
      await rdsn.entities.ProducaoDiaLote.update(lote.id, { status: 'FECHADO' });
      // Verificar se sessão deve fechar
      const todosLotesSessao = await rdsn.entities.ProducaoDiaLote.filter({ producao_dia_id: lote.producao_dia_id });
      const abertos = todosLotesSessao.filter(l => l.status === 'ABERTO' && l.id !== lote.id);
      if (abertos.length === 0) {
        await rdsn.entities.ProducaoDia.update(lote.producao_dia_id, {
          status: 'FECHADA',
          closed_at: new Date().toISOString()
        });
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['producao-dia'] });
      queryClient.invalidateQueries({ queryKey: ['producao-dia-lotes'] });
      toast.success('Lote fechado');
    }
  });

  const handleFechar = (lote, numInicial, numFinal, ordemDecrescente, qtty) => {
    fecharLoteMutation.mutate({ lote, numInicial, numFinal, ordemDecrescente, qtty });
  };

  const handleCancelar = (lote) => {
    if (confirm('Tem certeza que deseja cancelar este lote? Esta ação não pode ser desfeita.')) {
      cancelarLoteMutation.mutate(lote);
    }
  };

  const isLoading = loadingSessoes || (sessaoIds.length > 0 && loadingLotes);

  return (
    <div className="space-y-8">
      {/* Header do modo Premium */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-6 bg-blue-500/5 dark:bg-blue-600/5 p-6 rounded-[2rem] border border-blue-200/50 dark:border-blue-500/10 shadow-sm backdrop-blur-sm">
        <div className="flex items-center gap-4">
          <div className="relative">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shadow-[0_0_20px_rgba(37,99,235,0.4)]">
              <Clock className="w-6 h-6 text-white animate-[pulse_2s_infinite]" />
            </div>
            <div className="absolute -top-1 -right-1 w-4 h-4 bg-emerald-500 border-2 border-white dark:border-slate-900 rounded-full" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter">Modo Produção do Dia</h2>
              <Badge className="bg-blue-600 text-white border-0 font-black text-[10px] rounded-full px-2.5">
                {lotesAtivos.length} ATIVOS
              </Badge>
            </div>
            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest italic opacity-70">Operação Simplificada • {setorNome || 'Todos Setores'}</p>
          </div>
        </div>
        <Button
          onClick={() => setShowNova(true)}
          className="w-full sm:w-auto h-14 px-8 rounded-2xl bg-slate-900 dark:bg-blue-600 hover:bg-slate-800 dark:hover:bg-blue-500 text-white font-black uppercase text-[10px] tracking-[0.2em] gap-3 shadow-xl transition-all active:scale-95"
        >
          <Plus className="w-5 h-5" />
          Nova Produção
        </Button>
      </div>

      {/* Cards de produção ativa */}
      {isLoading ? (
        <div className="text-center py-20">
          <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-slate-500 dark:text-slate-400 font-black uppercase text-xs tracking-widest italic animate-pulse">Sincronizando Coleta...</p>
        </div>
      ) : lotesAbertos.length === 0 ? (
        <div className="relative group overflow-hidden rounded-[2.5rem] bg-white dark:bg-slate-900/40 backdrop-blur-xl border-2 border-dashed border-slate-200 dark:border-white/5 p-16 text-center transition-all hover:border-blue-500/30">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,rgba(37,99,235,0.03),transparent)] pointer-events-none" />
          <div className="relative space-y-6">
            <div className="w-24 h-24 bg-slate-50 dark:bg-slate-950/60 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner group-hover:scale-110 transition-transform">
              <Clock className="w-12 h-12 text-slate-300 dark:text-slate-700" />
            </div>
            <div className="space-y-2">
              <p className="text-xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter">Nenhuma produção ativa</p>
              <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest italic opacity-60">Aguardando abertura de nova sessão operacional</p>
            </div>
            <Button
              onClick={() => setShowNova(true)}
              variant="outline"
              className="rounded-2xl px-8 h-12 border-slate-200 dark:border-white/10 dark:hover:bg-white/5 font-black uppercase text-[10px] tracking-widest"
            >
              Iniciar agora
            </Button>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {lotesAbertos
            .sort((a, b) => {
              // Abertos primeiro, depois fechados
              if (a.status === 'ABERTO' && b.status !== 'ABERTO') return -1;
              if (a.status !== 'ABERTO' && b.status === 'ABERTO') return 1;
              return 0;
            })
            .map(lote => (
              <ProducaoDiaCard
                key={lote.id}
                lote={lote}
                reserva={reservasMap[lote.reserva_id]}
                setorNome={setorNome}
                onFechar={handleFechar}
                onCancelar={handleCancelar}
                isClosing={fecharLoteMutation.isPending}
                isSupervisor={isSupervisor}
                produtos={produtos}
                setorInfo={setorInfo}
              />
            ))
          }
        </div>
      )}

      {/* Dialog para nova produção */}
      <NovaProducaoDiaDialog
        open={showNova}
        onOpenChange={setShowNova}
        reservas={reservas}
        lotesJaAbertos={lotesJaAbertosIds}
        lotesSessaoAbertos={lotesAbertos}
        baixasPorReserva={baixasPorReserva}
        setorNome={setorNome}
        onIniciar={(lotes) => iniciarProducaoMutation.mutate(lotes)}
        isLoading={iniciarProducaoMutation.isPending}
        produtos={produtos}
        setorInfo={setorInfo}
      />
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Input } from "@/components/ui/input";
import { Search, X } from "lucide-react";

export default function BuscaLoteProducao({ reservas = [], onSelect, lotesJaAbertos = [] }) {
  const [busca, setBusca] = useState('');
  const [open, setOpen] = useState(false);

  const resultados = useMemo(() => {
    if (!busca || busca.length < 2) return [];
    const termo = busca.toLowerCase();

    return reservas
      .filter(r => {
        // Apenas lotes reservados ou em produção, não totalmente baixados
        if (!['RESERVADO', 'EM_PRODUCAO'].includes(r.status)) return false;
        const restante = (r.quantidade || 0) - (r.quantidade_baixada || 0);
        if (restante <= 0) return false;
        // Não mostrar lotes já abertos em sessões ativas
        if (lotesJaAbertos.includes(r.id)) return false;

        // Buscar por cliente, código, letra, numeração
        return (
          r.cliente?.toLowerCase().includes(termo) ||
          r.codigo_produto?.toLowerCase().includes(termo) ||
          r.codigo_completo?.toLowerCase().includes(termo) ||
          r.letra_produto?.toLowerCase().includes(termo) ||
          r.modelo?.toLowerCase().includes(termo) ||
          String(r.numero_inicial).includes(termo) ||
          String(r.numero_final).includes(termo)
        );
      })
      .slice(0, 10);
  }, [busca, reservas, lotesJaAbertos]);

  return (
    <div className="relative">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
        <Input
          placeholder="Buscar por cliente, código, letra, numeração..."
          value={busca}
          onChange={(e) => {
            setBusca(e.target.value);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          onBlur={() => setTimeout(() => setOpen(false), 200)}
          className="pl-10 pr-8"
        />
        {busca && (
          <button
            onClick={() => { setBusca(''); setOpen(false); }}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
          >
            <X className="w-4 h-4" />
          </button>
        )}
      </div>

      {open && resultados.length > 0 && (
        <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 rounded-lg shadow-xl z-50 max-h-80 overflow-y-auto mt-1">
          {resultados.map(r => {
            const restante = (r.quantidade || 0) - (r.quantidade_baixada || 0);
            return (
              <button
                key={r.id}
                onMouseDown={(e) => {
                  e.preventDefault();
                  onSelect(r);
                  setBusca('');
                  setOpen(false);
                }}
                className="w-full text-left px-4 py-3 hover:bg-blue-50 border-b border-slate-100 last:border-0 transition-colors"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-slate-900 text-white rounded-lg flex items-center justify-center font-bold text-lg flex-shrink-0">
                      {r.letra_produto}
                    </div>
                    <div>
                      <p className="font-semibold text-slate-900 text-sm">{r.cliente || 'Sem cliente'}</p>
                      <p className="text-xs text-slate-500">
                        {r.codigo_completo} · {r.codigo_produto} · {r.modelo}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-slate-500">Restante</p>
                    <p className="font-bold text-slate-900">{restante.toLocaleString()}</p>
                  </div>
                </div>
                <p className="text-xs text-slate-400 mt-1 font-mono">
                  {r.numero_inicial?.toLocaleString()} — {r.numero_final?.toLocaleString()}
                </p>
              </button>
            );
          })}
        </div>
      )}

      {open && busca.length >= 2 && resultados.length === 0 && (
        <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 rounded-lg shadow-xl z-50 mt-1 p-4 text-center text-sm text-slate-500">
          Nenhum lote encontrado
        </div>
      )}
    </div>
  );
}

// @ts-nocheck
import React, { useState, useMemo, useEffect } from 'react';
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { CheckCircle, XCircle, Clock, Loader2, Settings2, CheckCircle2, ArrowUpDown } from "lucide-react";
import { formatarNumeracao, extrairPrefixo } from '../formatacao/FormatacaoNumeracao';
import { estaContido, calcularQuantidade } from '../../core/numeracaoService';
import { cn } from "@/lib/utils";

const statusColors = {
  ABERTO: 'bg-blue-500/10 text-blue-500 border-blue-500/20 shadow-[0_0_15px_rgba(56,189,248,0.1)]',
  FECHADO: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.1)]',
  CANCELADO: 'bg-rose-500/10 text-rose-500 border-rose-500/20 shadow-[0_0_15px_rgba(244,63,94,0.1)]',
};

const statusLabels = {
  ABERTO: 'EM OPERAÇÃO',
  FECHADO: 'FINALIZADO',
  CANCELADO: 'CANCELADO',
};

export default function ProducaoDiaCard({
  lote,
  reserva,
  setorNome,
  onFechar,
  onCancelar,
  isClosing,
  isSupervisor,
  produtos = [],
  setorInfo
}) {
  const [numInicial, setNumInicial] = useState(lote.numeracao_inicial?.toString() || '');
  const [numFinal, setNumFinal] = useState('');
  const [erro, setErro] = useState('');
  const [showFechar, setShowFechar] = useState(false);
  const [isEditingPartida, setIsEditingPartida] = useState(false);
  const [numPartidaEdit, setNumPartidaEdit] = useState('');

  // Detectar ordem do produto removido - mantendo lógica simplificada

  const ordemPadrao = useMemo(() => {
    return lote?.sequencia_decrescente ?? lote?.reserva_original?.sequencia_decrescente ?? reserva?.sequencia_decrescente ?? false;
  }, [lote?.sequencia_decrescente, lote?.reserva_original?.sequencia_decrescente, reserva?.sequencia_decrescente]);

  const [ordemDecrescente, setOrdemDecrescente] = useState(ordemPadrao);

  useEffect(() => {
    setOrdemDecrescente(ordemPadrao);
  }, [ordemPadrao]);

  const prefixo = extrairPrefixo(reserva?.codigo_completo || '');
  const restanteLote = (reserva?.quantidade || 0) - (reserva?.quantidade_baixada || 0);

  // Progresso geral do lote
  const totalBaixado = reserva?.quantidade_baixada || 0;
  const progressoGeral = (reserva?.quantidade || 0) > 0
    ? Math.round((totalBaixado / reserva.quantidade) * 100)
    : 0;

  const extrairNumeroPuro = (valor) => {
    if (!valor) return { num: NaN, prefixoErrado: false };
    const codigoLote = (reserva?.codigo_completo || '').toUpperCase().trim();
    const valorUpper = valor.toString().toUpperCase().trim();

    if (codigoLote && valorUpper.startsWith(codigoLote)) {
      const parteNumerica = valorUpper.slice(codigoLote.length);
      const num = Number(parteNumerica);
      if (!isNaN(num) && parteNumerica.length > 0) return { num, prefixoErrado: false };
      return { num: NaN, prefixoErrado: false };
    }

    if (/[a-zA-Z]/.test(valorUpper)) {
      return { num: NaN, prefixoErrado: true };
    }

    const num = Number(valorUpper);
    return { num, prefixoErrado: false };
  };

  const validarCampos = (iniVal, fimVal) => {
    if (!iniVal || !fimVal) return { valid: false, qty: 0 };

    const { num: ini, prefixoErrado: prefIni } = extrairNumeroPuro(iniVal);
    const { num: fim, prefixoErrado: prefFim } = extrairNumeroPuro(fimVal);

    if (prefIni || prefFim) {
      setErro(`Prefixo inválido. Use ${reserva?.codigo_completo} ou apenas o número`);
      return { valid: false, qty: 0 };
    }

    if (isNaN(ini) || isNaN(fim)) {
      return { valid: false, qty: 0 };
    }

    if (!estaContido(ini, reserva.numero_inicial, reserva.numero_final)) {
      setErro(`Partida fora do intervalo original (${reserva.numero_inicial} - ${reserva.numero_final})`);
      return { valid: false, qty: 0 };
    }
    if (!estaContido(fim, reserva?.numero_inicial, reserva?.numero_final)) {
      setErro(`Término fora do intervalo original (${reserva.numero_inicial} - ${reserva.numero_final})`);
      return { valid: false, qty: 0 };
    }

    const qty = calcularQuantidade(ini, fim, ordemDecrescente);
    if (qty <= 0) {
      setErro(ordemDecrescente ? "Término deve ser menor que Partida" : "Término deve ser maior que Partida");
      return { valid: false, qty: 0 };
    }

    if (qty > restanteLote) {
      setErro(`Quantidade (${qty}) excede o restante (${restanteLote})`);
      return { valid: false, qty: 0 };
    }

    setErro('');
    return { valid: true, qty };
  };

  const { qty: quantidadeCalculada } = useMemo(() => {
    return validarCampos(numInicial, numFinal);
  }, [numInicial, numFinal, ordemDecrescente]);

  const numInicialPuro = useMemo(() => extrairNumeroPuro(numInicial).num, [numInicial]);
  const numFinalPuro = useMemo(() => extrairNumeroPuro(numFinal).num, [numFinal]);

  const numInicialFormatado = formatarNumeracao(numInicialPuro || 0, prefixo, setorNome);

  const isFechado = lote.status === 'FECHADO';
  const isCancelado = lote.status === 'CANCELADO';
  const isAberto = lote.status === 'ABERTO';

  const handleToggleOrdemInCard = (novaOrdem) => {
    setOrdemDecrescente(novaOrdem);
    setErro('');

    // Inteligência: Se a partida estiver em um extremo, move para o outro
    const rangeMin = Math.min(reserva?.numero_inicial || 0, reserva?.numero_final || 0);
    const rangeMax = Math.max(reserva?.numero_inicial || 0, reserva?.numero_final || 0);
    const iniPuro = extrairNumeroPuro(numInicial).num;

    if (novaOrdem && iniPuro === rangeMin) {
      setNumInicial(rangeMax.toString());
    } else if (!novaOrdem && iniPuro === rangeMax) {
      setNumInicial(rangeMin.toString());
    }
  };

  const handleSalvarPartida = () => {
    const { num, prefixoErrado } = extrairNumeroPuro(numPartidaEdit);
    if (prefixoErrado || isNaN(num)) {
      toast.error('Número de partida inválido');
      return;
    }
    if (!estaContido(num, reserva.numero_inicial, reserva.numero_final)) {
      toast.error('Número fora do intervalo da reserva');
      return;
    }
    setNumInicial(num.toString());
    setIsEditingPartida(false);
  };

  if (!reserva) return null;

  return (
    <Card className={`relative overflow-hidden transition-all duration-500 border-0 rounded-[2rem] group ${isFechado ? 'bg-emerald-500/5 dark:bg-emerald-500/5 shadow-inner' :
      isCancelado ? 'bg-rose-500/5 dark:bg-rose-500/5 opacity-60 grayscale-[0.5]' :
        'bg-white dark:bg-slate-900/40 backdrop-blur-xl shadow-2xl hover:shadow-blue-500/10'
      }`}>
      {/* Indicador Lateral Premium */}
      <div className={`absolute left-0 top-0 bottom-0 w-1.5 transition-all duration-500 ${isFechado ? 'bg-emerald-500' :
        isCancelado ? 'bg-rose-500' :
          'bg-blue-600 group-hover:w-2'
        }`} />

      <CardContent className="p-6 sm:p-8 space-y-6">
        {/* Header: Cliente + Status Premium */}
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-5">
            <div className="w-14 h-14 bg-slate-950 dark:bg-white text-white dark:text-slate-900 rounded-2xl flex items-center justify-center font-black text-2xl shadow-xl transition-transform group-hover:scale-110 group-hover:rotate-3">
              {reserva.letra_produto}
            </div>
            <div>
              <p className="text-lg font-black text-slate-900 dark:text-white uppercase italic tracking-tighter leading-none">
                {reserva.cliente || 'OCASIONAL'}
              </p>
              <p className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest italic mt-1 opacity-70">
                {reserva.codigo_produto} • {reserva.modelo}
              </p>
            </div>
          </div>
          <div className="flex flex-col items-end gap-2">
            <Badge variant="outline" className={`font-black text-[9px] tracking-[0.2em] rounded-full px-3 py-1 uppercase italic ${statusColors[lote.status]}`}>
              {statusLabels[lote.status]}
            </Badge>
            {ordemDecrescente && isAberto && (
              <Badge className="bg-indigo-500 text-white border-0 font-black text-[8px] uppercase tracking-widest px-2 py-0.5 rounded-md italic">
                ↓ INVERTIDA
              </Badge>
            )}
          </div>
        </div>

        {/* Info Grid Futurista */}
        <div className="grid grid-cols-2 gap-px bg-slate-200 dark:bg-white/5 rounded-2xl overflow-hidden border border-slate-200 dark:border-white/5 shadow-inner">
          <div className="bg-white/40 dark:bg-slate-950/40 p-4 space-y-1">
            <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest italic leading-none">ID do Lote</span>
            <p className="text-sm font-black text-slate-900 dark:text-white tracking-tight">{reserva.codigo_completo}</p>
          </div>
          <div className="bg-white/40 dark:bg-slate-950/40 p-4 space-y-1">
            <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest italic leading-none">
              {ordemDecrescente ? 'Partida Atual (↓)' : 'Partida Atual (↑)'}
            </span>
            <div className="flex items-center justify-between">
              <div className="text-sm font-black text-blue-500 dark:text-blue-400 tracking-tight flex items-center gap-2">
                {isEditingPartida ? (
                  <div className="flex items-center gap-2 animate-in slide-in-from-left-2">
                    <Input
                      type="text"
                      value={numPartidaEdit}
                      onChange={e => setNumPartidaEdit(e.target.value)}
                      className="h-7 w-28 text-[10px] font-black p-1 text-center bg-white dark:bg-slate-900 border-blue-500/50"
                      autoFocus
                    />
                    <Button size="icon" variant="ghost" className="h-6 w-6 text-emerald-500" onClick={handleSalvarPartida}><CheckCircle2 className="w-4 h-4" /></Button>
                    <Button size="icon" variant="ghost" className="h-6 w-6 text-rose-500" onClick={() => setIsEditingPartida(false)}><XCircle className="w-4 h-4" /></Button>
                  </div>
                ) : (
                  <>
                    {reserva.codigo_completo}{numInicialFormatado}
                    {isAberto && (
                      <Button 
                        variant="ghost" 
                        size="icon" 
                        className="h-5 w-5 opacity-0 group-hover:opacity-100 transition-opacity text-slate-400 hover:text-blue-500"
                        onClick={() => { setNumPartidaEdit(numInicial); setIsEditingPartida(true); }}
                      >
                        <Settings2 className="w-3 h-3" />
                      </Button>
                    )}
                  </>
                )}
              </div>
            </div>
          </div>
          <div className="bg-white/40 dark:bg-slate-950/40 p-4 space-y-1">
            <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest italic leading-none">Último Término</span>
            {isFechado ? (
              <p className="text-sm font-black text-emerald-500 tracking-tight">
                {reserva.codigo_completo}{formatarNumeracao(lote.numeracao_final, prefixo, setorNome)}
              </p>
            ) : (
              <div className="flex items-center gap-1.5 text-amber-500 opacity-60">
                <Clock className="w-3.5 h-3.5 animate-[spin_4s_linear_infinite]" />
                <p className="text-[10px] font-black uppercase tracking-widest italic">Aguardando...</p>
              </div>
            )}
          </div>
          <div className="bg-white/40 dark:bg-slate-950/40 p-4 space-y-1">
            <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest italic leading-none">Unidades Previstas</span>
            {isFechado ? (
              <p className="text-sm font-black text-emerald-500 tracking-tight">{lote.quantidade_calculada?.toLocaleString()} UN</p>
            ) : (
              <p className={cn("text-xl font-black tracking-tight", quantidadeCalculada > 0 ? "text-blue-500" : "text-slate-300 dark:text-slate-800")}>
                {quantidadeCalculada > 0 ? `${quantidadeCalculada.toLocaleString()} UN` : '——'}
              </p>
            )}
          </div>
        </div>

        {/* Barra de Progresso */}
        <div className="space-y-3">
          <div className="flex justify-between items-end">
            <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest italic leading-none">Fluxo de Integridade do Lote</span>
            <span className="text-lg font-black text-slate-900 dark:text-white italic tracking-tighter leading-none">{progressoGeral}%</span>
          </div>
          <div className="h-2.5 bg-slate-100 dark:bg-slate-950 rounded-full overflow-hidden border border-slate-200 dark:border-white/5 relative">
            <div
              className={`h-full rounded-full transition-all duration-1000 ${isFechado ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.4)]' :
                progressoGeral >= 75 ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.4)]' :
                  progressoGeral >= 40 ? 'bg-blue-600 shadow-[0_0_15px_rgba(37,99,235,0.4)]' :
                    progressoGeral > 0 ? 'bg-amber-500 shadow-[0_0_15px_rgba(245,158,11,0.4)]' :
                      'bg-slate-300 dark:bg-slate-800'
                } ${isAberto && progressoGeral < 100 ? 'animate-pulse' : ''}`}
              style={{ width: `${Math.max(progressoGeral, isAberto ? 3 : 0)}%` }}
            />
          </div>
          <div className="flex justify-between items-center text-[9px] font-bold uppercase tracking-widest italic">
            <span className="text-slate-400">{totalBaixado.toLocaleString()} PROCESSADOS</span>
            <span className="text-slate-400">{reserva.quantidade?.toLocaleString()} REQUERIDOS</span>
          </div>
        </div>

        {/* Painel de Ações Industriais */}
        {isAberto && (
          <div className="pt-6 border-t border-slate-200 dark:border-white/5">
            {!showFechar ? (
              <div className="flex gap-4">
                <Button
                  onClick={() => setShowFechar(true)}
                  className="flex-1 h-14 bg-slate-900 dark:bg-blue-600 hover:bg-slate-800 dark:hover:bg-blue-500 text-white font-black uppercase text-[10px] tracking-[0.2em] rounded-2xl shadow-xl transition-all active:scale-95 group"
                >
                  <CheckCircle className="w-5 h-5 mr-3 group-hover:rotate-12 transition-transform" />
                  Concluir Operação
                </Button>
                {isSupervisor && (
                  <Button
                    variant="outline"
                    onClick={() => onCancelar(lote)}
                    className="w-14 h-14 flex items-center justify-center p-0 rounded-2xl border-rose-200 dark:border-rose-500/20 text-rose-500 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-500/10 transition-all active:scale-95"
                  >
                    <XCircle className="w-5 h-5" />
                  </Button>
                )}
              </div>
            ) : (
              <div className="space-y-6 bg-blue-500/5 dark:bg-blue-600/5 p-6 rounded-3xl border border-blue-200/50 dark:border-blue-500/10 animate-in fade-in zoom-in slide-in-from-top-4 duration-300">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <Settings2 className="w-4 h-4 text-blue-500" />
                    <Label className="text-[10px] font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest italic">Configuração do Intervalo</Label>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleToggleOrdemInCard(!ordemDecrescente)}
                    className="h-8 px-3 text-[10px] font-black rounded-xl bg-white dark:bg-slate-900 shadow-sm border border-blue-100 dark:border-white/5 text-blue-600 dark:text-blue-400 flex items-center gap-2 hover:bg-blue-50 dark:hover:bg-slate-800"
                  >
                    <ArrowUpDown className="w-3 h-3" />
                    {ordemDecrescente ? 'DECRESCENTE (↓)' : 'CRESCENTE (↑)'}
                  </Button>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-[9px] font-black text-slate-500 uppercase ml-2">Ponto de Partida</Label>
                    <Input
                      value={numInicial}
                      onChange={(e) => { setNumInicial(e.target.value); setErro(''); }}
                      placeholder="Início"
                      className="h-14 bg-white dark:bg-slate-950/80 border-slate-200 dark:border-white/10 rounded-2xl text-lg font-black text-center text-slate-900 dark:text-white tracking-widest"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label className="text-[9px] font-black text-slate-500 uppercase ml-2">Ponto de Término</Label>
                    <Input
                      value={numFinal}
                      onChange={(e) => { setNumFinal(e.target.value); setErro(''); }}
                      placeholder="Fim"
                      className={cn(
                        "h-14 bg-white dark:bg-slate-950/80 border-slate-200 dark:border-white/10 rounded-2xl text-lg font-black text-center text-slate-900 dark:text-white tracking-widest",
                        erro ? "border-rose-500 text-rose-500 ring-rose-500/10" : (quantidadeCalculada > 0 ? "border-emerald-500 ring-emerald-500/10" : "")
                      )}
                      autoFocus
                    />
                  </div>
                </div>

                {quantidadeCalculada > 0 && !erro && (
                  <div className="bg-emerald-500/10 rounded-2xl p-4 text-center border border-emerald-500/20 animate-in zoom-in-95">
                    <span className="text-[9px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest italic block mb-1">Cotejamento Industrial</span>
                    <p className="text-2xl font-black text-emerald-600 dark:text-emerald-500 italic tracking-tighter">
                      {quantidadeCalculada.toLocaleString()} <span className="text-xs uppercase">Unidades</span>
                    </p>
                  </div>
                )}

                {erro && (
                  <div className="flex items-center justify-center gap-2 text-rose-500 animate-in slide-in-from-bottom-2">
                    <XCircle className="w-4 h-4" />
                    <p className="text-[10px] font-black uppercase tracking-widest">{erro}</p>
                  </div>
                )}

                <div className="flex gap-4 pt-2">
                  <Button
                    variant="ghost"
                    onClick={() => { setShowFechar(false); setNumFinal(''); setErro(''); }}
                    className="flex-1 h-12 rounded-xl text-slate-500 font-black uppercase text-[10px] tracking-widest"
                  >
                    Voltar
                  </Button>
                  <Button
                    onClick={() => onFechar(lote, numInicialPuro, numFinalPuro, ordemDecrescente, quantidadeCalculada)}
                    disabled={!numFinal || !!erro || isClosing}
                    className="flex-1 h-12 bg-emerald-600 hover:bg-emerald-500 text-white font-black uppercase text-[10px] tracking-[0.2em] rounded-xl shadow-lg shadow-emerald-500/20 disabled:grayscale"
                  >
                    {isClosing ? (
                      <Loader2 className="w-5 h-5 animate-spin" />
                    ) : (
                      <>
                        <CheckCircle className="w-4 h-4 mr-2" />
                        Validar Baixa
                      </>
                    )}
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useState, useMemo } from 'react';
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { Search, X, Calendar as CalendarIcon, Filter } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";

export default function FiltroProducaoAvancado({ 
  filters, 
  setFilters, 
  reservas = [],
  onClear 
}) {
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [openDropdown, setOpenDropdown] = useState(null);

  // Extrair sugestões únicas dos dados
  const sugestoes = useMemo(() => ({
    clientes: [...new Set(reservas.map(r => r.cliente).filter(Boolean))].sort(),
    codigos: [...new Set(reservas.map(r => r.codigo_produto).filter(Boolean))].sort(),
    modelos: [...new Set(reservas.map(r => r.modelo).filter(Boolean))].sort(),
  }), [reservas]);

  // Filtrar sugestões conforme digita
  const clientesFiltrados = filters.cliente 
    ? sugestoes.clientes.filter(c => c.toLowerCase().includes(filters.cliente.toLowerCase()))
    : sugestoes.clientes;

  const codigosFiltrados = filters.codigoProduto
    ? sugestoes.codigos.filter(c => c.toLowerCase().includes(filters.codigoProduto.toLowerCase()))
    : sugestoes.codigos;

  const modelosFiltrados = filters.modelo
    ? sugestoes.modelos.filter(m => m.toLowerCase().includes(filters.modelo.toLowerCase()))
    : sugestoes.modelos;

  const AutocompleteField = ({ value, onChange, suggestions, placeholder, fieldKey }) => (
    <div className="relative flex-1 min-w-[200px]">
      <input
        type="text"
        placeholder={placeholder}
        value={value || ''}
        onChange={(e) => {
          onChange(e.target.value);
          setOpenDropdown(e.target.value ? fieldKey : null);
        }}
        onFocus={() => setOpenDropdown(fieldKey)}
        onBlur={() => setTimeout(() => setOpenDropdown(null), 150)}
        className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-base shadow-sm transition-colors placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:text-sm pr-8"
      />
      {value && (
        <button
          onClick={() => onChange('')}
          className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
        >
          <X className="w-4 h-4" />
        </button>
      )}
      {openDropdown === fieldKey && suggestions.length > 0 && (
        <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 rounded-md shadow-lg z-50 max-h-60 overflow-y-auto mt-1">
          {suggestions.slice(0, 50).map((item, idx) => (
            <button
              key={idx}
              onClick={() => {
                onChange(item);
                setOpenDropdown(null);
              }}
              className="w-full text-left px-3 py-2 hover:bg-slate-100 text-sm text-slate-700 border-b border-slate-100 last:border-b-0"
            >
              {item}
            </button>
          ))}
        </div>
      )}
    </div>
  );

  const hasActiveFilters = filters.cliente || filters.codigoProduto || filters.modelo || 
    filters.status || filters.dataInicio || filters.dataFim;

  return (
    <div className="space-y-3">
      {/* Barra Principal */}
      <div className="flex flex-col lg:flex-row gap-3">
        <div className="flex items-center gap-2 flex-1">
          <Search className="w-4 h-4 text-slate-400 flex-shrink-0" />
          <AutocompleteField
            value={filters.cliente}
            onChange={(v) => setFilters(prev => ({ ...prev, cliente: v }))}
            suggestions={clientesFiltrados}
            placeholder="Buscar por cliente..."
            fieldKey="cliente"
          />
        </div>

        <div className="flex gap-2">
          <Button
            variant={showAdvanced ? "default" : "outline"}
            size="sm"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="flex-shrink-0"
          >
            <Filter className="w-4 h-4 mr-2" />
            Filtros Avançados
          </Button>

          {hasActiveFilters && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onClear}
              className="text-slate-500 flex-shrink-0"
            >
              <X className="w-4 h-4 mr-1" />
              Limpar
            </Button>
          )}
        </div>
      </div>

      {/* Filtros Avançados */}
      {showAdvanced && (
        <div className="p-4 bg-slate-50 rounded-lg border border-slate-200 space-y-4">
          {/* Linha 1: Código e Modelo */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-medium text-slate-600 mb-1 block">Código do Produto</label>
              <AutocompleteField
                value={filters.codigoProduto}
                onChange={(v) => setFilters(prev => ({ ...prev, codigoProduto: v }))}
                suggestions={codigosFiltrados}
                placeholder="Ex: A26LM, A26L..."
                fieldKey="codigo"
              />
            </div>

            <div>
              <label className="text-xs font-medium text-slate-600 mb-1 block">Modelo</label>
              <AutocompleteField
                value={filters.modelo}
                onChange={(v) => setFilters(prev => ({ ...prev, modelo: v }))}
                suggestions={modelosFiltrados}
                placeholder="Filtrar por modelo..."
                fieldKey="modelo"
              />
            </div>
          </div>

          {/* Linha 2: Status e Datas */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            <div>
              <label className="text-xs font-medium text-slate-600 mb-1 block">Status</label>
              <Select 
                value={filters.status || 'all'} 
                onValueChange={(v) => setFilters(prev => ({ ...prev, status: v === 'all' ? '' : v }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Todos" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="RESERVADO">Reservado</SelectItem>
                  <SelectItem value="EM_PRODUCAO">Em Produção</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="text-xs font-medium text-slate-600 mb-1 block">Data Criação (Início)</label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !filters.dataInicio && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {filters.dataInicio ? format(new Date(filters.dataInicio), "dd/MM/yyyy", { locale: ptBR }) : "Selecione..."}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar
                    mode="single"
                    selected={filters.dataInicio ? new Date(filters.dataInicio) : undefined}
                    onSelect={(date) => setFilters(prev => ({ 
                      ...prev, 
                      dataInicio: date ? date.toISOString().split('T')[0] : '' 
                    }))}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div>
              <label className="text-xs font-medium text-slate-600 mb-1 block">Data Criação (Fim)</label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !filters.dataFim && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {filters.dataFim ? format(new Date(filters.dataFim), "dd/MM/yyyy", { locale: ptBR }) : "Selecione..."}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar
                    mode="single"
                    selected={filters.dataFim ? new Date(filters.dataFim) : undefined}
                    onSelect={(date) => setFilters(prev => ({ 
                      ...prev, 
                      dataFim: date ? date.toISOString().split('T')[0] : '' 
                    }))}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>
          </div>

          {/* Resumo de Filtros Ativos */}
          {hasActiveFilters && (
            <div className="pt-3 border-t border-slate-200">
              <div className="flex flex-wrap gap-2">
                <span className="text-xs font-medium text-slate-600">Filtros ativos:</span>
                {filters.cliente && (
                  <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-100 text-emerald-700 text-xs rounded-md">
                    Cliente: {filters.cliente}
                    <button onClick={() => setFilters(prev => ({ ...prev, cliente: '' }))} className="hover:text-emerald-900">
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                )}
                {filters.codigoProduto && (
                  <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-100 text-emerald-700 text-xs rounded-md">
                    Código: {filters.codigoProduto}
                    <button onClick={() => setFilters(prev => ({ ...prev, codigoProduto: '' }))} className="hover:text-emerald-900">
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                )}
                {filters.modelo && (
                  <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-100 text-emerald-700 text-xs rounded-md">
                    Modelo: {filters.modelo}
                    <button onClick={() => setFilters(prev => ({ ...prev, modelo: '' }))} className="hover:text-emerald-900">
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                )}
                {filters.status && (
                  <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-100 text-emerald-700 text-xs rounded-md">
                    Status: {filters.status}
                    <button onClick={() => setFilters(prev => ({ ...prev, status: '' }))} className="hover:text-emerald-900">
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                )}
                {(filters.dataInicio || filters.dataFim) && (
                  <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-100 text-emerald-700 text-xs rounded-md">
                    Data: {filters.dataInicio ? format(new Date(filters.dataInicio), "dd/MM/yy") : '...'} - {filters.dataFim ? format(new Date(filters.dataFim), "dd/MM/yy") : '...'}
                    <button onClick={() => setFilters(prev => ({ ...prev, dataInicio: '', dataFim: '' }))} className="hover:text-emerald-900">
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Button } from "@/components/ui/button";
import { Filter, X } from 'lucide-react';

export default function FiltroLotes({ reservas = [], onFiltrar, onLimpar, filtroAtivo }) {
  const [modelo, setModelo] = useState('');
  const [codigo, setCodigo] = useState('');
  const [cliente, setCliente] = useState('');
  const [openDropdown, setOpenDropdown] = useState(null);

  // Extrair opções únicas do histórico
  const sugestoes = useMemo(() => {
    return {
      modelos: [...new Set(reservas.map(r => r.modelo).filter(Boolean))].sort(),
      codigos: [...new Set(reservas.map(r => r.codigo_produto).filter(Boolean))].sort(),
      clientes: [...new Set(reservas.map(r => r.cliente).filter(Boolean))].sort(),
    };
  }, [reservas]);

  // Filtrar sugestões conforme digita
  const modelosFiltrados = modelo ? sugestoes.modelos.filter(m => m.toLowerCase().includes(modelo.toLowerCase())) : sugestoes.modelos;
  const codigosFiltrados = codigo ? sugestoes.codigos.filter(c => c.toLowerCase().includes(codigo.toLowerCase())) : sugestoes.codigos;
  const clientesFiltrados = cliente ? sugestoes.clientes.filter(c => c.toLowerCase().includes(cliente.toLowerCase())) : sugestoes.clientes;

  const handleFiltrar = () => {
    onFiltrar({ modelo, codigo, cliente });
  };

  const handleLimpar = () => {
    setModelo('');
    setCodigo('');
    setCliente('');
    setOpenDropdown(null);
    onLimpar();
  };

  const CampoComSugestoes = ({ value, onChange, sugestoes, placeholder, dropdownId }) => (
    <div className="relative">
      <input
        type="text"
        placeholder={placeholder}
        value={value}
        onChange={(e) => {
          onChange(e.target.value);
          setOpenDropdown(value ? dropdownId : null);
        }}
        onFocus={() => setOpenDropdown(dropdownId)}
        onBlur={() => setTimeout(() => setOpenDropdown(null), 150)}
        onKeyPress={(e) => {
          if (e.key === 'Enter') handleFiltrar();
        }}
        className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-base shadow-sm transition-colors placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:text-sm"
      />
      {openDropdown === dropdownId && sugestoes.length > 0 && (
        <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 rounded-md shadow-lg z-10 max-h-40 overflow-y-auto mt-1">
          {sugestoes.map((item, idx) => (
            <button
              key={idx}
              onClick={() => {
                onChange(item);
                setOpenDropdown(null);
              }}
              className="w-full text-left px-3 py-2 hover:bg-slate-100 text-sm text-slate-700 border-b border-slate-100 last:border-b-0"
            >
