import React, { useState, useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Plus, Zap, TrendingUp, TrendingDown, Calculator, Target, Activity, ShieldAlert, CheckCircle2, SlidersHorizontal } from 'lucide-react';
import { cn } from "@/lib/utils";

export default function PCPSimulacaoPanel({ _mes, _ano, ops, producaoMap, dias, onClose, onResult }) {
  const [params, setParams] = useState({
    percAumento: 0,
    opsExtra: 0,
    percReducao: 0,
    percCapacidade: 0,
    custoUnitario: 10,
    vendaUnitario: 25
  });
  const [resultado, setResultado] = useState(null);

  const set = (k, v) => setParams(p => ({ ...p, [k]: Number(v) || 0 }));

  const [filtrosBase, setFiltrosBase] = useState({
    diaInicio: dias[0] || 1,
    diaFim: dias[dias.length - 1] || 31,
    mesesMultiplicador: 1
  });

  const [opsSelecionadas, setOpsSelecionadas] = useState(ops.map(o => o.id));

  const toggleOp = (id) => {
    setOpsSelecionadas(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const baseStats = useMemo(() => {
    let totalPrev = 0, totalReal = 0;
    const diasFiltrados = dias.filter(d => d >= filtrosBase.diaInicio && d <= filtrosBase.diaFim);
    const opsFiltradas = ops.filter(op => opsSelecionadas.includes(op.id));

    for (const op of opsFiltradas) {
      for (const d of diasFiltrados) {
        totalPrev += producaoMap[`${op.id}-${d}`]?.previsto || 0;
        totalReal += producaoMap[`${op.id}-${d}`]?.realizado || 0;
      }
    }

    return { 
      totalPrev: totalPrev * filtrosBase.mesesMultiplicador, 
      totalReal: totalReal * filtrosBase.mesesMultiplicador,
      diasCorridos: diasFiltrados.length * filtrosBase.mesesMultiplicador
    };
  }, [ops, producaoMap, dias, filtrosBase, opsSelecionadas]);

  const calcular = () => {
    const { percAumento, opsExtra, percReducao, percCapacidade, custoUnitario, vendaUnitario } = params;
    const fatorDemanda = 1 + percAumento / 100;
    const fatorEficiencia = 1 - percReducao / 100;
    const fatorCapacidade = 1 + percCapacidade / 100;

    const novoPrevisto = Math.round(baseStats.totalPrev * fatorDemanda + opsExtra * 1000);
    const novoRealizado = Math.round(baseStats.totalReal * fatorEficiencia * fatorCapacidade);
    const novoSaldo = novoRealizado - novoPrevisto;
    const percAtendimento = novoPrevisto > 0 ? ((novoRealizado / novoPrevisto) * 100).toFixed(1) : '0.0';
    const mediaDiaria = baseStats.diasCorridos > 0 ? Math.round(novoRealizado / baseStats.diasCorridos) : 0;

    // Impacto Financeiro
    const lucroPrevisto = novoRealizado * (vendaUnitario - custoUnitario);
    const perdaOportunidade = novoSaldo < 0 ? Math.abs(novoSaldo) * (vendaUnitario - custoUnitario) : 0;

    const gargalo = novoSaldo < 0 
      ? `CRÍTICO: ${Math.abs(novoSaldo).toLocaleString()} un em falta` 
      : novoSaldo < (novoPrevisto * 0.1) 
        ? 'ATENÇÃO: Cap. no limite' 
        : 'SITUAÇÃO: Estável';

    const res = { 
      novoPrevisto, 
      novoRealizado, 
      novoSaldo, 
      percAtendimento, 
      mediaDiaria, 
      gargalo, 
      lucroEst: lucroPrevisto,
      perdaEst: perdaOportunidade,
      params 
    };
    setResultado(res);
    return res;
  };

  const handleAplicar = () => {
    const res = calcular();
    if (onResult) onResult(res);
  };

  return (
    <Dialog open={true} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-xl dark:bg-slate-900/90 dark:border-white/10 rounded-[2.5rem] p-0 overflow-hidden backdrop-blur-3xl shadow-2xl border-0">
        <div className="bg-gradient-to-br from-amber-600 to-orange-700 p-8 text-white relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32 blur-3xl" />
          <DialogHeader className="relative z-10">
            <DialogTitle className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3">
              <span className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center">
                <Zap className="w-6 h-6 text-amber-200" />
              </span>
              Motor de <span className="text-amber-200">Simulação</span>
            </DialogTitle>
            <p className="text-xs font-bold text-amber-100/60 uppercase tracking-widest mt-1 italic">
              Projeção de Cenários • PCP Analítico
            </p>
          </DialogHeader>
        </div>

        <div className="p-8 space-y-6 max-h-[75vh] overflow-y-auto custom-scrollbar">
          {/* Escopo da Base (Filtros de Simulação) */}
          <div className="bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/5 rounded-2xl p-5 shadow-sm space-y-4">
            <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 italic flex items-center gap-2 mb-2">
              <SlidersHorizontal className="w-3.5 h-3.5 text-blue-500" /> Escopo da Base (Setup)
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="md:col-span-3 space-y-2">
                <div className="flex justify-between items-center ml-1">
                  <Label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Ordens de Produção (Alvo)</Label>
                  <span className="text-[10px] font-bold text-slate-400">{opsSelecionadas.length} / {ops.length} ativas</span>
                </div>
                <div className="flex flex-wrap gap-2 max-h-24 overflow-y-auto custom-scrollbar p-2 bg-white dark:bg-slate-900/50 rounded-xl border border-slate-200 dark:border-white/5">
                  {ops.map(op => (
                    <Badge 
                      key={op.id} 
                      onClick={() => toggleOp(op.id)}
                      variant={opsSelecionadas.includes(op.id) ? "default" : "outline"}
                      className={cn("cursor-pointer font-bold transition-all text-[9.5px] uppercase", 
                        opsSelecionadas.includes(op.id) ? "bg-blue-600 hover:bg-blue-700 text-white border-0" : "opacity-40 grayscale hover:opacity-100"
                      )}
                    >
                      {op.codigo_op}
                    </Badge>
                  ))}
                  {ops.length === 0 && <span className="text-[10px] text-slate-400 italic">Nenhuma OP livre encontrada</span>}
                </div>
              </div>

               <div className="space-y-2">
                <Label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Partida (Dia Mín)</Label>
                <Input 
                   type="number" 
                   min={1} 
                   max={31} 
                   value={filtrosBase.diaInicio} 
                   onChange={e => setFiltrosBase(p => ({ ...p, diaInicio: Number(e.target.value) }))}
                   className="h-10 bg-white dark:bg-slate-900 border-slate-200 dark:border-white/10 rounded-xl font-black text-center"
                 />
              </div>

               <div className="space-y-2">
                <Label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Término (Dia Máx)</Label>
                <Input 
                   type="number" 
                   min={1} 
                   max={31} 
                   value={filtrosBase.diaFim} 
                   onChange={e => setFiltrosBase(p => ({ ...p, diaFim: Number(e.target.value) }))}
                   className="h-10 bg-white dark:bg-slate-900 border-slate-200 dark:border-white/10 rounded-xl font-black text-center"
                 />
              </div>

               <div className="space-y-2">
                <Label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Projeção (Meses)</Label>
                <Input 
                   type="number" 
                   min={1} 
                   max={24} 
                   value={filtrosBase.mesesMultiplicador} 
                   onChange={e => setFiltrosBase(p => ({ ...p, mesesMultiplicador: Number(e.target.value) }))}
                   className="h-10 bg-white dark:bg-slate-900 border-slate-200 dark:border-white/10 rounded-xl font-black text-center text-amber-500"
                 />
              </div>
            </div>
          </div>

          {/* Cenário Base Resultante */}
          <div className="bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/5 rounded-2xl p-5 shadow-sm">
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-4 flex items-center gap-2">
              <Activity className="w-3.5 h-3.5" /> Situação Atual (Extrapolada)
            </p>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-1">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Demanda Prevista Original</p>
                <p className="text-2xl font-black text-blue-600 dark:text-blue-400 tracking-tighter">{baseStats.totalPrev.toLocaleString()}</p>
              </div>
              <div className="space-y-1">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Coleta Realizada Original</p>
                <p className="text-2xl font-black text-emerald-600 dark:text-emerald-400 tracking-tighter">{baseStats.totalReal.toLocaleString()}</p>
              </div>
            </div>
          </div>

          {/* Parâmetros */}
          <div className="space-y-4">
            <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 italic flex items-center gap-2">
              <SlidersHorizontal className="w-3.5 h-3.5" /> Vetores de Simulação
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[
                { key: 'percAumento', label: 'Crescimento Demanda', icon: Target, hint: 'Ajuste percentual da carga (%)' },
                { key: 'opsExtra', label: 'Ordens Adicionais', icon: Plus, hint: 'Unidades extras (milhar)' },
                { key: 'percReducao', label: 'Perda de Eficiência', icon: TrendingDown, hint: 'Impacto negativo no fluxo (%)' },
                { key: 'percCapacidade', label: 'Ganho Capacidade', icon: TrendingUp, hint: 'Aumento produtivo (%)' },
                { key: 'custoUnitario', label: 'Custo Unitário (R$)', icon: Calculator, hint: 'Custo médio por unidade' },
                { key: 'vendaUnitario', label: 'Preço Venda (R$)', icon: Target, hint: 'Preço médio de venda' },
              ].map(({ key, label, icon: Icon, hint }) => (
                <div key={key} className="space-y-2">
                  <Label className="text-[10px] font-black uppercase tracking-widest text-slate-500 flex items-center gap-1.5 ml-1">
                    <Icon className="w-3 h-3" /> {label}
                  </Label>
                  <div className="relative group">
                    <Input
                      type="number"
                      value={params[key]}
                      onChange={e => set(key, e.target.value)}
                      className="h-12 bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 rounded-xl font-black text-right pr-10"
                      min={0}
                    />
                    <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-black text-slate-400 opacity-40 group-focus-within:opacity-100 transition-opacity">
                      {key.startsWith('perc') ? '%' : key.includes('Unitario') ? 'R$' : 'un'}
                    </span>
                  </div>
                  <p className="text-[9px] text-slate-400 italic px-1">{hint}</p>
                </div>
              ))}
            </div>
          </div>

          <Button
            onClick={calcular}
            className="w-full h-14 bg-gradient-to-r from-amber-600 to-orange-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest gap-2 shadow-xl shadow-orange-600/20 hover:scale-[1.01] active:scale-95 transition-all border-0"
          >
            <Calculator className="w-5 h-5 group-hover:rotate-12 transition-transform" />
            Processar Projeção
          </Button>

          {/* Resultado */}
          {resultado && (
            <div className="bg-slate-900 border border-white/5 rounded-3xl p-6 shadow-2xl relative overflow-hidden animate-in zoom-in-95 duration-500">
              <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/10 rounded-full blur-3xl -mr-16 -mt-16" />

              <div className="flex items-center justify-between mb-6 relative z-10 text-white">
                <h4 className="text-xs font-black uppercase tracking-[0.3em] flex items-center gap-2 italic">
                  <Activity className="w-4 h-4 text-amber-500" /> Outcome de Engenharia
                </h4>
                <Badge className="bg-amber-600 border-0 text-white font-black italic rounded-lg">SIMULADO</Badge>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 relative z-10 pt-4">
                {[
                  { label: 'Projeção Demanda', value: resultado.novoPrevisto, icon: Target, color: 'text-blue-400' },
                  { label: 'Capacidade Real', value: resultado.novoRealizado, icon: CheckCircle2, color: 'text-emerald-400' },
                  { label: 'Lucro Est. (Margem)', value: `R$ ${resultado.lucroEst.toLocaleString()}`, icon: TrendingUp, color: 'text-emerald-400' },
                  { label: 'Perda Oportunidade', value: `R$ ${resultado.perdaEst.toLocaleString()}`, icon: TrendingDown, color: 'text-rose-400' },
                ].map((stat, i) => (
                  <div key={i} className="bg-white/5 p-3 rounded-2xl border border-white/5">
                    <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-1">
                      <stat.icon className="w-2.5 h-2.5" /> {stat.label}
                    </p>
                    <p className={cn("text-sm font-black italic tracking-tight truncate", stat.color)}>
                      {stat.value}
                    </p>
                  </div>
                ))}
              </div>

              {/* Barra de Aproveitamento */}
              <div className="mt-6 space-y-2">
                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-500">
                  <span>Eficiência de Atendimento</span>
                  <span className={Number(resultado.percAtendimento) >= 90 ? 'text-emerald-400' : 'text-rose-400'}>
                    {resultado.percAtendimento}%
                  </span>
                </div>
                <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                  <div 
                    className={cn(
                      "h-full transition-all duration-1000 ease-out",
                      Number(resultado.percAtendimento) >= 90 ? "bg-emerald-500" : "bg-rose-500 shadow-[0_0_15px_rgba(244,63,94,0.5)]"
                    )}
                    style={{ width: `${Math.min(resultado.percAtendimento, 100)}%` }}
                  />
                </div>
                <div className="flex justify-between items-center bg-slate-800/50 p-3 rounded-xl border border-white/5">
                  <div className="flex items-center gap-3">
                     <ShieldAlert className={cn("w-5 h-5", resultado.novoSaldo < 0 ? "text-rose-500 animate-pulse" : "text-emerald-500")} />
                     <div>
                       <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest">Status do Sistema</p>
                       <p className="text-xs font-black text-white italic">{resultado.gargalo}</p>
                     </div>
                  </div>
                  <div className="text-right">
                    <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest">Vazão Média</p>
                    <p className="text-xs font-black text-slate-300 italic">{resultado.mediaDiaria} un/dia</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="p-6 bg-slate-50/80 dark:bg-slate-900/80 backdrop-blur-md border-t dark:border-white/5 flex gap-4">
          <Button
            variant="outline"
            onClick={onClose}
            className="flex-1 h-12 rounded-xl border-slate-200 dark:border-white/10 font-black uppercase text-[10px] tracking-widest transition-all"
          >
            Fechar
          </Button>
          <Button
            onClick={handleAplicar}
            className="flex-[1.5] h-12 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-emerald-600/20 transition-all border-0"
          >
            Confirmar e Injetar Dados
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { useMutation, useQueryClient, useQuery } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { AlertTriangle, ChevronDown, ChevronUp, X, Package } from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';

/**
 * Componente que detecta OPs do mês anterior ainda não concluídas
 * e oferece importá-las como "Atraso" no mês atual.
 */
export default function PCPAtrasosAlert({ mesAtual, anoAtual, opsAtual, opsAnterior, producoesMesAnterior }) {
  const qc = useQueryClient();
  const [expanded, setExpanded] = useState(true);
  const [dismissed, setDismissed] = useState(false);

  // Buscar baixas do mês anterior agrupadas por codigo_produto das OPs
  const mesAnt = mesAtual === 1 ? 12 : mesAtual - 1;
  const anoAnt = mesAtual === 1 ? anoAtual - 1 : anoAtual;
  const anoCompletoAnt = 2000 + anoAnt;
  const inicioMesAnt = new Date(anoCompletoAnt, mesAnt - 1, 1).toISOString();
  const fimMesAnt = new Date(anoCompletoAnt, mesAnt, 0, 23, 59, 59).toISOString();

  const codigosProdutoAnt = React.useMemo(() =>
    [...new Set((opsAnterior || []).map(o => o.codigo_produto).filter(Boolean))],
    [opsAnterior]
  );

  // Buscar reservas dos produtos anteriores para achar baixas reais
  const { data: reservasAnt = [] } = useQuery({
    queryKey: ['reservas-pcp-atraso', codigosProdutoAnt.join(',')],
    queryFn: async () => {
      if (!codigosProdutoAnt.length) return [];
      const all = await Promise.all(codigosProdutoAnt.map(cod =>
        rdsn.entities.ReservaLote.filter({ codigo_produto: cod }, null, 500)
      ));
      return all.flat();
    },
    enabled: codigosProdutoAnt.length > 0
  });

  // Baixas do mês anterior agrupadas por reserva_id
  const reservaIdsAnt = reservasAnt.map(r => r.id);
  const { data: baixasAnt = [] } = useQuery({
    queryKey: ['baixas-pcp-atraso', reservaIdsAnt.join(',')],
    queryFn: async () => {
      if (!reservaIdsAnt.length) return [];
      const all = await Promise.all(reservaIdsAnt.map(id =>
        rdsn.entities.BaixaLote.filter({ reserva_id: id }, null, 500)
      ));
      return all.flat().filter(b =>
        !b.created_at || (b.created_at >= inicioMesAnt && b.created_at <= fimMesAnt)
      );
    },
    enabled: reservaIdsAnt.length > 0
  });

  // Calcular total baixado por codigo_produto no mês anterior
  const baixadoPorCodigo = React.useMemo(() => {
    const m = {};
    for (const baixa of baixasAnt) {
      const reserva = reservasAnt.find(r => r.id === baixa.reserva_id);
      if (!reserva?.codigo_produto) continue;
      m[reserva.codigo_produto] = (m[reserva.codigo_produto] || 0) + (baixa.quantidade || 0);
    }
    return m;
  }, [baixasAnt, reservasAnt]);

  // Calcular realizado por op_id (PCPProducaoDiaria)
  const realizadoPorOp = React.useMemo(() => {
    const m = {};
    for (const p of (producoesMesAnterior || [])) {
      m[p.op_id] = (m[p.op_id] || 0) + (p.realizado || 0);
    }
    return m;
  }, [producoesMesAnterior]);

  // Detectar OPs do mês anterior que não foram concluídas
  const opsAtrasadas = React.useMemo(() => {
    if (!opsAnterior || !opsAnterior.length) return [];
    return opsAnterior.filter(op => {
      if (op.status !== 'Ativo') return false;
      if (op.tipo === 'Atraso') return false;
      const jaExiste = (opsAtual || []).some(o => o.codigo_op === op.codigo_op && o.tipo === 'Atraso');
      if (jaExiste) return false;
      const qtdTotal = op.quantidade_total || 0;
      if (qtdTotal === 0) return false;
      const realizadoReal = op.codigo_produto
        ? (baixadoPorCodigo[op.codigo_produto] || 0)
        : (realizadoPorOp[op.id] || 0);
      return realizadoReal < qtdTotal;
    });
  }, [opsAnterior, opsAtual, baixadoPorCodigo, realizadoPorOp]);

  // Estado de edição local
  const [editValues, setEditValues] = useState({});

  React.useEffect(() => {
    if (!opsAtrasadas.length) return;
    setEditValues(prev => {
      const m = { ...prev };
      opsAtrasadas.forEach(op => {
        if (m[op.id]) return;
        const realizadoReal = op.codigo_produto
          ? (baixadoPorCodigo[op.codigo_produto] || 0)
          : (realizadoPorOp[op.id] || 0);
        const saldo = (op.quantidade_total || 0) - realizadoReal;
        m[op.id] = {
          codigo_op: op.codigo_op,
          descricao: op.descricao || '',
          cliente_nome: op.cliente_nome || '',
          codigo_produto: op.codigo_produto || '',
          quantidade_total: saldo > 0 ? saldo : op.quantidade_total || 0,
          item_num: op.item_num || '',
          selected: true,
        };
      });
      return m;
    });
  }, [opsAtrasadas.length, baixadoPorCodigo, realizadoPorOp]);

  const importMutation = useMutation({
    mutationFn: async () => {
      const toImport = opsAtrasadas.filter(op => editValues[op.id]?.selected);
      await Promise.all(toImport.map(op => {
        const ev = editValues[op.id];
        return rdsn.entities.PCPOrdemProducao.create({
          codigo_op: ev.codigo_op,
          descricao: ev.descricao,
          cliente_id: op.cliente_id,
          cliente_nome: ev.cliente_nome,
          codigo_produto: ev.codigo_produto || op.codigo_produto || '',
          quantidade_total: Number(ev.quantidade_total) || 0,
          item_num: Number(ev.item_num) || undefined,
          tipo: 'Atraso',
          status: 'Ativo',
          mes: mesAtual,
          ano: anoAtual,
          mes_origem: mesAnt,
          ano_origem: anoAnt,
        });
      }));
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['pcp-ops', mesAtual, anoAtual] });
      toast.success('OPs em atraso importadas com sucesso!');
      setDismissed(true);
    },
    onError: e => toast.error('Erro ao importar: ' + e.message),
  });

  if (dismissed || opsAtrasadas.length === 0) return null;

  const selectedCount = Object.values(editValues).filter(v => v.selected).length;

  return (
    <div className="mb-6 rounded-[2rem] border border-amber-200/50 dark:border-amber-500/20 bg-amber-50/50 dark:bg-amber-950/20 backdrop-blur-xl shadow-xl overflow-hidden transition-all duration-500 animate-in fade-in slide-in-from-top-4">
      {/* Header */}
      <div
        className="flex items-center gap-4 px-6 py-4 bg-gradient-to-r from-amber-100/80 to-transparent dark:from-amber-900/30 dark:to-transparent cursor-pointer select-none"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="w-10 h-10 rounded-xl bg-amber-500/20 flex items-center justify-center border border-amber-500/20 shadow-inner">
          <AlertTriangle className="w-5 h-5 text-amber-600 dark:text-amber-400 animate-pulse" />
        </div>
        <div className="flex-1">
          <p className="text-sm font-black text-amber-900 dark:text-amber-200 uppercase tracking-tight italic">
            {opsAtrasadas.length} OP{opsAtrasadas.length > 1 ? 's' : ''} em Atraso Identificada{opsAtrasadas.length > 1 ? 's' : ''}
          </p>
          <p className="text-[10px] font-bold text-amber-700/70 dark:text-amber-400/60 uppercase tracking-widest">Procedência: Mês {mesAnt}/{anoAnt} • Solicitação de Regularização</p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={e => { e.stopPropagation(); setDismissed(true); }}
            className="p-2 rounded-lg hover:bg-amber-200/50 dark:hover:bg-amber-500/10 text-amber-500 transition-colors"
            title="Ignorar"
          >
            <X className="w-4 h-4" />
          </button>
          <div className="p-2 rounded-lg bg-amber-200/30 dark:bg-amber-500/10">
            {expanded ? <ChevronUp className="w-4 h-4 text-amber-600" /> : <ChevronDown className="w-4 h-4 text-amber-600" />}
          </div>
        </div>
      </div>

      {/* Lista editável */}
      {expanded && (
        <div className="p-6 pt-2 space-y-4">
          <div className="overflow-x-auto rounded-2xl border border-amber-200/30 dark:border-amber-500/10 bg-white/50 dark:bg-black/20">
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="bg-amber-100/50 dark:bg-amber-900/20 text-amber-900 dark:text-amber-300">
                  <th className="px-4 py-3 text-center w-10">
                    <input
                      type="checkbox"
                      className="w-4 h-4 rounded accent-amber-600 cursor-pointer"
                      checked={selectedCount === opsAtrasadas.length && opsAtrasadas.length > 0}
                      onChange={e => {
                        setEditValues(prev => {
                          const n = { ...prev };
                          Object.keys(n).forEach(k => { n[k] = { ...n[k], selected: e.target.checked }; });
                          return n;
                        });
                      }}
                    />
                  </th>
                  <th className="px-4 py-3 text-left font-black uppercase tracking-widest text-[9px]">Identificador</th>
                  <th className="px-4 py-3 text-left font-black uppercase tracking-widest text-[9px]">Especificação Técnica</th>
                  <th className="px-4 py-3 text-left font-black uppercase tracking-widest text-[9px]">Entidade / Cliente</th>
                  <th className="px-4 py-3 text-center font-black uppercase tracking-widest text-[9px]">Saldo Residual</th>
                  <th className="px-4 py-3 text-center font-black uppercase tracking-widest text-[9px]">Item #</th>
                </tr>
              </thead>
              <tbody>
                {opsAtrasadas.map(op => {
                  const ev = editValues[op.id] || {};
                  const realizadoReal = op.codigo_produto
                    ? (baixadoPorCodigo[op.codigo_produto] || 0)
                    : (realizadoPorOp[op.id] || 0);
                  const qtdOrig = op.quantidade_total || 0;

                  return (
                    <tr key={op.id} className={cn(
                      "border-t border-amber-200/30 dark:border-amber-500/10 transition-colors",
                      ev.selected ? "bg-amber-500/5 dark:bg-amber-500/5" : "opacity-40 grayscale"
                    )}>
                      <td className="px-4 py-3 text-center">
                        <input
                          type="checkbox"
                          className="w-4 h-4 rounded accent-amber-600 cursor-pointer"
                          checked={!!ev.selected}
                          onChange={e => setEditValues(prev => ({ ...prev, [op.id]: { ...prev[op.id], selected: e.target.checked } }))}
                        />
                      </td>
                      <td className="px-4 py-2">
                        <Input
                          value={ev.codigo_op || ''}
                          onChange={e => setEditValues(prev => ({ ...prev, [op.id]: { ...prev[op.id], codigo_op: e.target.value } }))}
                          className="h-8 text-xs font-mono font-bold bg-white dark:bg-slate-900 border-amber-200/50 dark:border-amber-500/20"
                        />
                      </td>
                      <td className="px-4 py-2">
                        <Input
                          value={ev.descricao || ''}
                          onChange={e => setEditValues(prev => ({ ...prev, [op.id]: { ...prev[op.id], descricao: e.target.value } }))}
                          className="h-8 text-xs bg-white dark:bg-slate-900 border-amber-200/50 dark:border-amber-500/20"
                        />
                      </td>
                      <td className="px-4 py-2">
                        <Input
                          value={ev.cliente_nome || ''}
                          onChange={e => setEditValues(prev => ({ ...prev, [op.id]: { ...prev[op.id], cliente_nome: e.target.value } }))}
                          className="h-8 text-xs bg-white dark:bg-slate-900 border-amber-200/50 dark:border-amber-500/20"
                        />
                      </td>
                      <td className="px-4 py-2 text-center">
                        <div className="flex flex-col items-center gap-1">
                          <Input
                            type="number"
                            value={ev.quantidade_total || ''}
                            onChange={e => setEditValues(prev => ({ ...prev, [op.id]: { ...prev[op.id], quantidade_total: e.target.value } }))}
                            className="h-8 text-xs text-center w-24 font-black bg-white dark:bg-slate-900 border-amber-200/50 dark:border-amber-500/20"
                          />
                          <Badge variant="outline" className="text-[8px] font-black border-amber-500/20 text-amber-600 dark:text-amber-400">
                            {realizadoReal}/{qtdOrig} REALIZADO
                          </Badge>
                        </div>
                      </td>
                      <td className="px-4 py-2 text-center">
                        <Input
                          type="number"
                          value={ev.item_num || ''}
                          onChange={e => setEditValues(prev => ({ ...prev, [op.id]: { ...prev[op.id], item_num: e.target.value } }))}
                          className="h-8 text-xs text-center w-16 bg-white dark:bg-slate-900 border-amber-200/50 dark:border-amber-500/20"
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <div className="flex items-center justify-between mt-4">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" />
              <p className="text-[10px] font-black uppercase tracking-[0.15em] text-amber-700 dark:text-amber-400 italic">
                {selectedCount} de {opsAtrasadas.length} Registro{opsAtrasadas.length > 1 ? 's' : ''} Selecionado{opsAtrasadas.length > 1 ? 's' : ''}
              </p>
            </div>
            <div className="flex gap-3">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setDismissed(true)}
                className="h-10 rounded-xl border-amber-200 dark:border-amber-500/20 bg-transparent text-amber-700 dark:text-amber-400 font-black uppercase text-[10px] tracking-widest"
              >
                Descartar Alerta
              </Button>
              <Button
                size="sm"
                onClick={() => importMutation.mutate()}
                disabled={selectedCount === 0 || importMutation.isPending}
                className="h-10 px-6 rounded-xl bg-amber-600 hover:bg-amber-700 text-white font-black uppercase text-[10px] tracking-widest gap-2 shadow-lg shadow-amber-600/20 border-0"
              >
                {importMutation.isPending ? (
                  <>Sincronizando...</>
                ) : (
                  <>
                    <Package className="w-3.5 h-3.5" />
                    Regularizar {selectedCount} OP{selectedCount > 1 ? 's' : ''}
                  </>
                )}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// @ts-nocheck
import React, { useState, useMemo } from 'react';
import { useMutation, useQueryClient, useQuery } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Zap, SlidersHorizontal, RefreshCw, Check, Calendar } from 'lucide-react';
import { Label } from "@/components/ui/label";
import { toast } from 'sonner';
import { usePCPSetor } from '@/components/pcp/PCPSetorGuard';
import { cn } from '@/lib/utils';

const DIAS_SEMANA = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

function getDiasNoMes(mes, ano) {
  return new Date(ano + 2000, mes, 0).getDate();
}

function getDiaSemana(ano, mes, dia) {
  return new Date(ano + 2000, mes - 1, dia).getDay();
}

function isWeekend(ano, mes, dia) {
  const d = getDiaSemana(ano, mes, dia);
  return d === 0 || d === 6;
}

export default function PCPDistribuirOPDialog({ op, mes, ano, producoes, onClose }) {
  const queryClient = useQueryClient();
  const { setorAtivo } = usePCPSetor();
  const totalDias = getDiasNoMes(mes, ano);
  const dias = Array.from({ length: totalDias }, (_, i) => i + 1);

  const diasUteis = useMemo(() => dias.filter(d => !isWeekend(ano, mes, d)), [dias, mes, ano]);

  const [valores, setValores] = useState(() => {
    const m = {};
    for (const d of dias) {
      const existing = producoes.find(p => p.op_id === op.id && p.dia === d);
      m[d] = existing?.previsto || 0;
    }
    return m;
  });

  const [modo, setModo] = useState('uniforme');
  const [diasSelecionados, setDiasSelecionados] = useState(() =>
    new Set(diasUteis)
  );

  const qtdTotal = op.quantidade_total || 0;
  const totalDistribuido = Object.values(valores).reduce((s, v) => s + (Number(v) || 0), 0);
  const diferenca = qtdTotal - totalDistribuido;

  const toggleDia = (dia) => {
    setDiasSelecionados(prev => {
      const novo = new Set(prev);
      if (novo.has(dia)) novo.delete(dia);
      else novo.add(dia);
      return novo;
    });
  };

  const distribuirAutomatico = () => {
    const selecionados = [...diasSelecionados].sort((a, b) => a - b);
    if (selecionados.length === 0) {
      toast.error('Selecione pelo menos um dia para distribuir');
      return;
    }

    const novos = { ...valores };
    for (const d of dias) novos[d] = 0;

    if (modo === 'uniforme') {
      const base = Math.floor(qtdTotal / selecionados.length);
      const resto = qtdTotal % selecionados.length;
      selecionados.forEach((d, i) => {
        novos[d] = base + (i < resto ? 1 : 0);
      });
    } else if (modo === 'crescente') {
      const n = selecionados.length;
      const pesos = selecionados.map((_, i) => i + 1);
      const somaPesos = pesos.reduce((s, p) => s + p, 0);
      let restante = qtdTotal;
      selecionados.forEach((d, i) => {
        const val = i === n - 1 ? restante : Math.round((pesos[i] / somaPesos) * qtdTotal);
        novos[d] = val;
        restante -= val;
      });
    }

    setValores(novos);
  };

  const { data: reservasOP = [] } = useQuery({
    queryKey: ['reservas-op-distribuir', op.codigo_produto, op.cliente_nome],
    queryFn: async () => {
      if (!op.codigo_produto) return [];
      const todas = await rdsn.entities.ReservaLote.filter({ codigo_produto: op.codigo_produto });
      return todas.filter(r => ['RESERVADO', 'EM_PRODUCAO'].includes(r.status));
    },
    enabled: !!op.codigo_produto
  });

  const saveMutation = useMutation({
    mutationFn: async () => {
      const anoCompleto = 2000 + ano;
      const promises = [];
      for (const dia of dias) {
        const val = Number(valores[dia]) || 0;
        const existing = producoes.find(p => p.op_id === op.id && p.dia === dia);
        if (existing) {
          if (existing.previsto !== val) {
            promises.push(rdsn.entities.PCPProducaoDiaria.update(existing.id, { previsto: val }));
          }
        } else if (val > 0) {
          promises.push(rdsn.entities.PCPProducaoDiaria.create({
            op_id: op.id, mes, ano, dia, previsto: val, setor_id: setorAtivo || ''
          }));
        }
      }
      await Promise.all(promises);

      if (reservasOP.length > 0) {
        let diaMax = null;
        let valMax = 0;
        for (const d of dias) {
          const v = Number(valores[d]) || 0;
          if (v > valMax) { valMax = v; diaMax = d; }
        }

        if (diaMax) {
          const diasComValor = dias.filter(d => (Number(valores[d]) || 0) > 0);
          const reservasAgendamento = [...reservasOP];
          const agendPromises = [];

          if (reservasAgendamento.length === 1) {
            const dataAgendada = `${anoCompleto}-${String(mes).padStart(2, '0')}-${String(diaMax).padStart(2, '0')}`;
            agendPromises.push(
              rdsn.entities.ReservaLote.update(reservasAgendamento[0].id, { data_prevista: dataAgendada })
            );
          } else {
            const diasOrdenados = [...diasComValor].sort((a, b) => (Number(valores[b]) || 0) - (Number(valores[a]) || 0));
            reservasAgendamento.forEach((reserva, idx) => {
              const diaEscolhido = diasOrdenados[idx % diasOrdenados.length];
              const dataAgendada = `${anoCompleto}-${String(mes).padStart(2, '0')}-${String(diaEscolhido).padStart(2, '0')}`;
              agendPromises.push(
                rdsn.entities.ReservaLote.update(reserva.id, { data_prevista: dataAgendada })
              );
            });
          }
          await Promise.all(agendPromises);
        }
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['pcp-producoes'] });
      queryClient.invalidateQueries({ queryKey: ['reservas'] });
      queryClient.invalidateQueries({ queryKey: ['todasReservas'] });
      const qtdReservas = reservasOP.length;
      toast.success(`Distribuição salva! ${qtdReservas > 0 ? `${qtdReservas} reserva(s) agendada(s) automaticamente.` : ''}`);
      onClose();
    },
    onError: (e) => toast.error('Erro ao salvar: ' + e.message)
  });

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-4xl dark:bg-slate-900/90 dark:border-white/10 rounded-[2.5rem] p-0 overflow-hidden backdrop-blur-3xl shadow-2xl border-0 flex flex-col h-[90vh]">
        <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-8 text-white relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32 blur-3xl animate-pulse" />
          <DialogHeader className="relative z-10">
            <DialogTitle className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3">
              <span className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center">
                <SlidersHorizontal className="w-6 h-6 text-indigo-200" />
              </span>
              Distribuir <span className="text-indigo-200">Volume</span>
            </DialogTitle>
            <p className="text-[10px] font-black text-indigo-100/60 uppercase tracking-[0.2em] mt-2 italic">
              Balanceamento de Carga • {op.codigo_op}
            </p>
          </DialogHeader>
        </div>

        <div className="p-8 space-y-6 flex-1 overflow-y-auto custom-scrollbar">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-slate-50 dark:bg-white/5 p-6 rounded-3xl border border-slate-200 dark:border-white/10 flex flex-col justify-center relative overflow-hidden group">
              <div className="absolute top-0 left-0 w-1 h-full bg-slate-300 dark:bg-slate-700" />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2 leading-none">Meta Contratada</span>
              <p className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter">
                {qtdTotal.toLocaleString()} <span className="text-xs font-bold text-slate-400 italic">UN</span>
              </p>
            </div>

            <div className={cn(
              "p-6 rounded-3xl border-2 transition-all flex flex-col justify-center relative overflow-hidden",
              Math.abs(diferenca) < 1
                ? 'bg-emerald-500/5 border-emerald-500/20'
                : 'bg-amber-500/5 border-amber-500/20'
            )}>
              <div className={cn("absolute top-0 left-0 w-1 h-full", Math.abs(diferenca) < 1 ? "bg-emerald-500" : "bg-amber-500")} />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2 leading-none">Status da Alocação</span>
              <div className="flex items-center gap-3">
                <p className={cn(
                  "text-3xl font-black tracking-tighter",
                  Math.abs(diferenca) < 1 ? 'text-emerald-600 dark:text-emerald-400' : 'text-amber-600 dark:text-amber-400'
                )}>
                  {totalDistribuido.toLocaleString()}
                </p>
                {diferenca !== 0 ? (
                  <Badge variant="outline" className="bg-white dark:bg-slate-950 text-[10px] font-black border-amber-200 dark:border-amber-500/20 text-amber-600 px-3 py-1">
                    {diferenca > 0 ? `-${diferenca}` : `+${Math.abs(diferenca)}`} FALTA
                  </Badge>
                ) : (
                  <div className="w-8 h-8 rounded-full bg-emerald-500 flex items-center justify-center text-white shadow-lg shadow-emerald-500/20 animate-in zoom-in duration-300">
                    <Check className="w-5 h-5" />
                  </div>
                )}
              </div>
            </div>
          </div>

          {reservasOP.length > 0 && (
            <div className="flex items-center gap-4 p-5 bg-blue-500/5 dark:bg-blue-500/10 border border-blue-500/20 rounded-3xl animate-in slide-in-from-top-2 duration-300">
              <div className="w-10 h-10 rounded-2xl bg-blue-600 text-white flex items-center justify-center shrink-0 shadow-lg shadow-blue-600/20">
                <Calendar className="w-5 h-5" />
              </div>
              <div className="space-y-0.5">
                <p className="text-[10px] font-black text-blue-900 dark:text-blue-400 uppercase tracking-widest leading-none">Sincronismo Automático</p>
                <p className="text-xs text-slate-600 dark:text-slate-400 font-medium italic">
                  <span className="font-black text-blue-600 dark:text-blue-300">{reservasOP.length} reserva(s)</span> do PCP serão re-agendadas conforme esta cobertura.
                </p>
              </div>
            </div>
          )}

          <div className="bg-slate-900/[0.03] dark:bg-white/[0.03] rounded-[2.5rem] border border-slate-200 dark:border-white/5 p-8 backdrop-blur-sm relative overflow-hidden group/intel">
            <div className="absolute top-0 right-0 w-48 h-48 bg-indigo-500/10 rounded-full blur-3xl -mr-24 -mt-24 group-hover/intel:bg-indigo-500/20 transition-all duration-700" />

            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-xl bg-amber-500/20 flex items-center justify-center">
                  <Zap className="w-4 h-4 text-amber-500" />
                </div>
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 dark:text-slate-200">Assistente de Distribuição</span>
              </div>
              <div className="flex gap-1.5 p-1.5 bg-white/50 dark:bg-black/20 rounded-xl border border-white dark:border-white/5 shadow-sm">
                <button className="text-[9px] font-black text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 uppercase tracking-widest transition-all px-3 py-1 rounded-md" onClick={() => setDiasSelecionados(new Set(diasUteis))}>Úteis</button>
                <div className="w-px h-4 bg-slate-200 dark:bg-white/10 self-center" />
                <button className="text-[9px] font-black text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 uppercase tracking-widest transition-all px-3 py-1 rounded-md" onClick={() => setDiasSelecionados(new Set(dias))}>Todos</button>
                <div className="w-px h-4 bg-slate-200 dark:bg-white/10 self-center" />
                <button className="text-[9px] font-black text-slate-500 dark:text-slate-400 hover:text-red-500 uppercase tracking-widest transition-all px-3 py-1 rounded-md" onClick={() => setDiasSelecionados(new Set())}>Reset</button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
              <div className="lg:col-span-4 space-y-3">
                <Label className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em] ml-1">Modelo Matemático</Label>
                <Select value={modo} onValueChange={setModo}>
                  <SelectTrigger className="h-14 bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 rounded-2xl font-black uppercase text-[10px] tracking-widest px-6 shadow-sm">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="dark:bg-slate-900 dark:border-white/10 rounded-2xl">
                    <SelectItem value="uniforme" className="font-black uppercase text-[10px] tracking-widest focus:bg-indigo-500/10">Equitativa (Flat)</SelectItem>
                    <SelectItem value="crescente" className="font-black uppercase text-[10px] tracking-widest focus:bg-indigo-500/10">Progressiva (Ramp)</SelectItem>
                  </SelectContent>
                </Select>
                <p className="text-[9px] text-slate-400 italic px-1">
                  * {modo === 'uniforme' ? 'Distribui unidades de forma igualitária entre os dias.' : 'Aumenta a carga progressivamente até o fim do período.'}
                </p>
              </div>

              <div className="lg:col-span-8 space-y-6">
                <div className="flex flex-wrap gap-2 justify-center">
                  {dias.map(dia => {
                    const wknd = isWeekend(ano, mes, dia);
                    const sel = diasSelecionados.has(dia);
                    return (
                      <button
                        key={dia}
                        onClick={() => toggleDia(dia)}
                        className={cn(
                          "w-10 h-10 rounded-xl text-xs font-black border transition-all transform hover:scale-110 active:scale-90 flex items-center justify-center relative overflow-hidden",
                          sel
                            ? wknd
                              ? 'bg-amber-500 text-white border-amber-600 shadow-lg shadow-amber-500/30'
                              : 'bg-indigo-600 text-white border-indigo-700 shadow-lg shadow-indigo-500/30'
                            : 'bg-white dark:bg-white/5 text-slate-300 dark:text-slate-700 border-slate-100 dark:border-white/5 opacity-50 grayscale'
                        )}
                      >
                        {dia}
                        {wknd && !sel && <div className="absolute top-0 right-0 w-2 h-2 bg-slate-200 dark:bg-slate-800 rounded-bl-sm" />}
                      </button>
                    );
                  })}
                </div>
                <Button
                  onClick={distribuirAutomatico}
                  className="w-full gap-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] h-14 shadow-xl shadow-indigo-600/20 border-0 transition-all active:scale-95"
                >
                  <RefreshCw className="w-4 h-4" />
                  Efetuar Cálculo de Malha
                </Button>
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex items-center gap-3 px-2">
              <div className="w-1.5 h-1.5 rounded-full bg-slate-400" />
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 dark:text-slate-400">Micro-ajustes da Agenda</span>
            </div>
            <div className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-7 gap-3 max-h-[40vh] overflow-y-auto p-2 custom-scrollbar">
              {dias.map(dia => {
                const wknd = isWeekend(ano, mes, dia);
                const diaSem = DIAS_SEMANA[getDiaSemana(ano, mes, dia)];
                const hasValue = (valores[dia] || 0) > 0;
                return (
                  <div
                    key={dia}
                    className={cn(
                      "flex flex-col items-center p-3 rounded-2xl border-2 transition-all relative group/cell",
                      hasValue
                        ? 'bg-white dark:bg-white/5 border-indigo-500/30 dark:border-indigo-500/40 shadow-sm'
                        : wknd
                          ? 'bg-slate-50/50 dark:bg-black/20 border-slate-100 dark:border-white/5 opacity-60'
                          : 'bg-white dark:bg-transparent border-slate-100 dark:border-white/5'
                    )}
                  >
                    <span className="text-[8px] text-slate-400 dark:text-slate-500 font-black uppercase mb-1 tracking-tighter">{diaSem}</span>
                    <span className={cn(
                      "text-sm font-black mb-2 transition-colors",
                      hasValue ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-400 dark:text-slate-700'
                    )}>{dia}</span>
                    <Input
                      type="number"
                      min="0"
                      value={valores[dia] || ''}
                      onChange={e => setValores(prev => ({ ...prev, [dia]: Number(e.target.value) || 0 }))}
                      className="h-10 text-center text-sm font-black bg-slate-50 dark:bg-white/5 border-0 focus-visible:ring-2 focus-visible:ring-indigo-500/20 rounded-xl p-0 dark:text-white"
                      placeholder="0"
                    />
                    {hasValue && (
                      <div className="absolute -top-1.5 -right-1.5 w-4 h-4 bg-indigo-500 rounded-full flex items-center justify-center text-[8px] text-white font-black shadow-sm shadow-indigo-500/20">
                        !
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        <div className="p-8 pt-6 border-t dark:border-white/5 flex gap-4 mt-auto">
          <Button
            variant="outline"
            onClick={onClose}
            className="flex-1 h-16 border-slate-200 dark:border-white/10 dark:hover:bg-white/5 rounded-3xl font-black uppercase text-[10px] tracking-[0.2em] transition-all"
          >
            Descartar
          </Button>
          <Button
            onClick={() => saveMutation.mutate()}
            disabled={saveMutation.isPending || Math.abs(diferenca) > 0}
            className={cn(
              "flex-[1.8] gap-3 rounded-3xl font-black uppercase text-[10px] tracking-[0.2em] h-16 shadow-2xl transition-all border-0",
              diferenca === 0
                ? 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-emerald-500/30'
                : 'bg-slate-200 dark:bg-slate-800 text-slate-400 cursor-not-allowed opacity-50'
            )}
          >
            {saveMutation.isPending ? (
              <RefreshCw className="w-5 h-5 animate-spin" />
            ) : (
              <Check className="w-5 h-5" />
            )}
            Consolidar Grade
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

