export default function AlertasPrazos({ reservas, userId }) {
  const queryClient = useQueryClient();

  const criarNotificacaoMutation = useMutation({
    mutationFn: async ({ titulo, mensagem, tipo, prioridade, reservaId }) => {
      await rdsn.entities.Notificacao.create({
        usuario_id: userId,
        titulo,
        mensagem,
        tipo,
        prioridade,
        entidade_tipo: 'ReservaLote',
        entidade_id: reservaId,
        lida: false,
        arquivada: false
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notificacoes-reserva'] });
    }
  });

  // Identificar reservas com prazos críticos
  const reservasComPrazo = (reservas || []).filter(r =>
    r.data_prevista &&
    r.status !== 'CANCELADO' &&
    r.status !== 'LIBERADO' &&
    r.status !== 'PRODUZIDO'
  );

  const alertas = reservasComPrazo.map(reserva => {
    const dataPrevista = new Date(reserva.data_prevista);
    const hoje = new Date();
    const dataPrevistaInicio = startOfDay(dataPrevista);
    const hojeInicio = startOfDay(hoje);

    // Calcula diferença real de dias ignorando horas
    const diasRestantes = differenceInDays(dataPrevistaInicio, hojeInicio);

    // Só está atrasado se for ANTES de hoje
    const atrasado = diasRestantes < 0 && reserva.status !== 'PRODUZIDO';

    const progresso = reserva.quantidade > 0 ? ((reserva.quantidade_baixada || 0) / reserva.quantidade) * 100 : 0;

    let severidade = 'BAIXA';
    let tipo = 'INFO';

    if (atrasado) {
      severidade = 'ALTA';
      tipo = 'ALERTA';
    } else if (diasRestantes <= 3 && diasRestantes >= 0) {
      severidade = 'ALTA';
      tipo = 'ALERTA';
    } else if (diasRestantes <= 7 && diasRestantes >= 0) {
      severidade = 'MEDIA';
      tipo = 'ALERTA';
    }

    return {
      reserva,
      diasRestantes,
      atrasado,
      progresso,
      severidade,
      tipo
    };
  }).filter(a => a.atrasado || (a.diasRestantes >= 0 && a.diasRestantes <= 7));

  // Criar notificações automáticas para prazos críticos
  useEffect(() => {
    if (!userId || !alertas.length) return;

    alertas.forEach(alerta => {
      const key = `notif_prazo_${alerta.reserva.id}_${alerta.diasRestantes}`;
      const jaNotificado = localStorage.getItem(key);

      if (!jaNotificado) {
        if (alerta.atrasado) {
          criarNotificacaoMutation.mutate({
            titulo: `⏰ Reserva ${alerta.reserva.codigo_completo} ATRASADA`,
            mensagem: `A reserva ${alerta.reserva.codigo_completo} do cliente ${alerta.reserva.cliente || 'N/A'} está ${Math.abs(alerta.diasRestantes)} dia(s) atrasada. Progresso: ${Math.round(alerta.progresso)}%`,
            tipo: 'ERRO',
            prioridade: 'ALTA',
            reservaId: alerta.reserva.id
          });
          localStorage.setItem(key, 'true');
        } else if (alerta.diasRestantes >= 0 && alerta.diasRestantes <= 3) {
          criarNotificacaoMutation.mutate({
            titulo: `🔔 Prazo urgente - ${alerta.reserva.codigo_completo}`,
            mensagem: `Faltam apenas ${alerta.diasRestantes} dia(s) para a data prevista da reserva ${alerta.reserva.codigo_completo}. Progresso atual: ${Math.round(alerta.progresso)}%`,
            tipo: 'ALERTA',
            prioridade: 'ALTA',
            reservaId: alerta.reserva.id
          });
          localStorage.setItem(key, 'true');
        }
      }
    });
  }, [alertas.length, userId]);

  if (alertas.length === 0) {
    return (
      <PremiumCard
        title="Prazos sob controle"
        icon={CheckCircle}
        iconColor="#10b981"
        headerClassName="bg-emerald-50 dark:bg-emerald-950/20 border-emerald-200 dark:border-emerald-800"
      >
        <motion.div 
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="flex flex-col items-center justify-center py-8 text-emerald-600/60 dark:text-emerald-400/60 space-y-4"
        >
          <div className="p-4 rounded-full bg-emerald-50 dark:bg-emerald-900/20 ring-1 ring-emerald-500/10">
            <CheckCircle size={32} className="opacity-50" />
          </div>
          <div className="text-center">
            <p className="text-sm font-bold uppercase tracking-widest text-emerald-700 dark:text-emerald-400">Nenhum prazo crítico</p>
            <p className="text-[10px] font-semibold uppercase tracking-widest mt-1 opacity-70">Todas as reservas estão no cronograma</p>
          </div>
        </motion.div>
      </PremiumCard>
    );
  }

  return (
    <PremiumCard
      title="Alertas de Prazos"
      icon={AlertTriangle}
      iconColor="#f59e0b"
      action={<Badge className="bg-yellow-600 text-white shadow-lg shadow-yellow-600/20">{alertas.length}</Badge>}
      headerClassName="bg-yellow-50 dark:bg-yellow-950/20 border-yellow-200 dark:border-yellow-800"
    >
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {alertas.map((alerta) => (
          <motion.div
            key={alerta.reserva.id}
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className={cn(
              "group relative flex flex-col p-5 bg-white/40 dark:bg-slate-900/40 backdrop-blur-xl border rounded-3xl shadow-lg hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden",
              alerta.atrasado 
                ? "border-red-200/50 dark:border-red-500/20 hover:border-red-300 dark:hover:border-red-500/40 hover:shadow-red-500/10" 
                : alerta.diasRestantes <= 3 
                  ? "border-orange-200/50 dark:border-orange-500/20 hover:border-orange-300 dark:hover:border-orange-500/40 hover:shadow-orange-500/10" 
                  : "border-yellow-200/50 dark:border-yellow-500/20 hover:border-yellow-300 dark:hover:border-yellow-500/40 hover:shadow-yellow-500/10"
            )}
          >
            {/* Premium glass hover effect */}
            <div className="absolute inset-0 bg-gradient-to-br from-white/40 to-white/0 dark:from-white/5 dark:to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
            <div className={cn(
              "absolute inset-y-0 left-0 w-1.5 translate-y-full group-hover:translate-y-0 transition-transform duration-500 ease-out",
              alerta.atrasado ? "bg-gradient-to-b from-red-400 to-red-600" :
              alerta.diasRestantes <= 3 ? "bg-gradient-to-b from-orange-400 to-orange-600" :
              "bg-gradient-to-b from-yellow-400 to-yellow-600"
            )} />

            <div className="flex justify-between items-start mb-4">
              <div className="space-y-1.5">
                <div className="flex items-center gap-2">
                  <span className="px-2 py-0.5 bg-slate-100 dark:bg-white/5 rounded-md font-mono text-[10px] font-black text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-white/5">
                    {alerta.reserva.codigo_completo}
                  </span>
                  {alerta.atrasado && (
                    <Badge className="font-black uppercase tracking-widest text-[9px] px-2 py-0 border-0 bg-red-100 text-red-800 dark:bg-red-500/20 dark:text-red-400">
                      Atrasado
                    </Badge>
                  )}
                </div>
                <h3 className="text-sm font-semibold text-slate-900 dark:text-white line-clamp-1">
                  {alerta.reserva.cliente || 'Sem cliente'}
                </h3>
              </div>
              <div className="flex flex-col items-end">
                <span className={cn(
                  "text-2xl font-black leading-none tracking-tighter",
                  alerta.atrasado ? "text-red-600 dark:text-red-400" :
                  alerta.diasRestantes <= 3 ? "text-orange-600 dark:text-orange-400" :
                  "text-yellow-600 dark:text-yellow-400"
                )}>
                  {alerta.atrasado ? `-${Math.abs(alerta.diasRestantes)}` : alerta.diasRestantes}
                </span>
                <span className="text-[9px] font-black uppercase tracking-widest text-slate-400 mt-1">
                  {alerta.atrasado ? "Dias Atraso" : "Dias Rest."}
                </span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-2 mb-4">
              <div className="flex items-center gap-1.5 text-xs text-slate-600 dark:text-slate-400">
                <Calendar className="w-3.5 h-3.5 opacity-50" />
                <span>{format(new Date(alerta.reserva.data_prevista), 'dd/MM/yy', { locale: ptBR })}</span>
              </div>
              <div className="flex items-center gap-1.5 text-xs text-slate-600 dark:text-slate-400 justify-end">
                <Package className="w-3.5 h-3.5 opacity-50" />
                <span>{alerta.reserva.quantidade_baixada || 0} / {alerta.reserva.quantidade}</span>
              </div>
            </div>

            <div className="mt-auto pt-3 border-t border-slate-200/50 dark:border-white/5">
              <div className="flex justify-between items-end mb-1.5">
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Progresso</span>
                <span className="text-[10px] font-bold text-slate-700 dark:text-slate-300">{Math.round(alerta.progresso)}%</span>
              </div>
              <div className="h-2 bg-slate-100 dark:bg-slate-800/50 rounded-full overflow-hidden shadow-inner border border-slate-200/50 dark:border-white/5">
                <div
                  className={cn(
                    "h-full rounded-full transition-all duration-1000 ease-out",
                    alerta.progresso >= 100 ? "bg-emerald-500" :
                    alerta.progresso >= 50 ? "bg-blue-500" :
                    "bg-slate-400 dark:bg-slate-500"
                  )}
                  style={{ width: `${Math.min(alerta.progresso, 100)}%` }}
                />
              </div>
            </div>
          </motion.div>
        ))}
      </div>
    </PremiumCard>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { useSetor } from '../context/SetorContext';
import { Plus, Edit2, Trash2, Package } from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { toast } from "sonner";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { PremiumCard } from '@/components/ui/PremiumCard';

export default function ProdutosTab() {
  const queryClient = useQueryClient();
  const { setorAtivo, isAdmin } = useSetor();
  const [showForm, setShowForm] = useState(false);
  const [showClienteForm, setShowClienteForm] = useState(false);
  const [editingProduto, setEditingProduto] = useState(null);
  const [produtoRecemCriado, setProdutoRecemCriado] = useState(null);
  const [clienteData, setClienteData] = useState({
    nome: '',
    letra_produto: '',
    modelo: '',
    codigo_produto: '',
    setor_id: '',
    ativo: true
  });
  const [formData, setFormData] = useState({
    letra_produto: '',
    sufixo: '',
    codigo_produto: '',
    modelo: '',
    descricao: '',
    categoria: 'Outro',
    celulas_permitidas: [],
    prefixo_padrao: '',
    estoque_minimo: 0,
    setor_id: '',
    ordem_numeracao: 'CRESCENTE',
    ativo: true,
    nome_cliente: ''
  });

  const { data: produtos = [], isLoading } = useQuery({
    queryKey: ['produtos', setorAtivo],
    queryFn: async () => {
      const todos = await rdsn.entities.Produto.list();
      if (isAdmin && setorAtivo === 'TODOS') return todos;
      return todos.filter(p => p.setor_id === setorAtivo);
    },
    enabled: !!setorAtivo
  });

  const { data: setores = [] } = useQuery({
    queryKey: ['setores'],
    queryFn: () => rdsn.entities.Setor.list()
  });

  const { data: clientesPCP = [] } = useQuery({
    queryKey: ['clientes-pcp', setorAtivo],
    queryFn: () => {
      if (!setorAtivo || setorAtivo === 'ALL') {
        return rdsn.entities.PCPCliente.list();
      }
      return rdsn.entities.PCPCliente.filter({ setor_id: setorAtivo });
    },
    enabled: !!setorAtivo
  });

  const handleCodigoProdutoChange = (codigo) => {
    const codigoUpper = codigo.toUpperCase().trim();

    const match = clientesPCP.find(c =>
      c.codigo?.toUpperCase().trim() === codigoUpper
    );

    setFormData(prev => ({
      ...prev,
      codigo_produto: codigo,
      ...(match && {
        nome_cliente: match.nome || prev.nome_cliente,
        descricao: match.descricao_produto || prev.descricao
      })
    }));
  };

  const createMutation = useMutation({
    mutationFn: (data) => rdsn.entities.Produto.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos', setorAtivo] });
      handleCloseForm();
      toast.success('Produto cadastrado com sucesso!');
    }
  });

  const createClienteMutation = useMutation({
    mutationFn: (data) => rdsn.entities.Cliente.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['clientes'] });
      setShowClienteForm(false);
      setProdutoRecemCriado(null);
      handleCloseForm();
      toast.success('Cliente criado automaticamente!');
    }
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => rdsn.entities.Produto.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos', setorAtivo] });
      handleCloseForm();
      toast.success('Produto atualizado!');
    }
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => rdsn.entities.Produto.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos', setorAtivo] });
      toast.success('Produto removido!');
    }
  });

  const handleOpenForm = (produto = null) => {
    if (produto) {
      setEditingProduto(produto);
      setFormData({
        letra_produto: produto.letra_produto,
        sufixo: produto.sufixo,
        codigo_produto: produto.codigo_produto || '',
        modelo: produto.modelo || '',
        descricao: produto.descricao || '',
        categoria: produto.categoria || 'Outro',
        celulas_permitidas: produto.celulas_permitidas || [],
        prefixo_padrao: produto.prefixo_padrao || '',
        estoque_minimo: produto.estoque_minimo || 0,
        setor_id: produto.setor_id || '',
        ordem_numeracao: produto.ordem_numeracao || (produto.ordem_baixa === 'decrescente' ? 'DECRESCENTE' : 'CRESCENTE'),
        ativo: produto.ativo ?? true,
        nome_cliente: produto.nome_cliente || ''
      });
    } else {
      setEditingProduto(null);
      setFormData({
        letra_produto: '',
        sufixo: '',
        codigo_produto: '',
        modelo: '',
        descricao: '',
        categoria: 'Outro',
        celulas_permitidas: [],
        prefixo_padrao: '',
        estoque_minimo: 0,
        setor_id: setorAtivo,
        ordem_numeracao: 'CRESCENTE',
        ativo: true,
        nome_cliente: ''
      });
    }
    setShowForm(true);
  };

  const handleCloseForm = () => {
    setShowForm(false);
    setEditingProduto(null);
    setFormData({
      letra_produto: '',
      sufixo: '',
      codigo_produto: '',
      modelo: '',
      descricao: '',
      categoria: 'Outro',
      celulas_permitidas: [],
      prefixo_padrao: '',
      estoque_minimo: 0,
      setor_id: setorAtivo,
      ordem_baixa: 'normal',
      ativo: true,
      nome_cliente: ''
    });
  };

  const generatePrefixo = (letra, sufixo) => {
    if (!letra || !sufixo) return '';
    const ano = new Date().getFullYear().toString().slice(-2);
    return `${letra}${ano}${sufixo}`;
  };

  const handleLetraOrSufixoChange = (letra, sufixo) => {
    const novoLetra = letra !== undefined ? letra : formData.letra_produto;
    const novoSufixo = sufixo !== undefined ? sufixo : formData.sufixo;
    const prefixoGerado = generatePrefixo(novoLetra, novoSufixo);

    setFormData(prev => ({
      ...prev,
      ...(letra !== undefined && { letra_produto: letra }),
      ...(sufixo !== undefined && { sufixo: sufixo }),
      ...(prefixoGerado && !editingProduto && { prefixo_padrao: prefixoGerado })
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (editingProduto) {
      updateMutation.mutate({ id: editingProduto.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  return (
    <>
      <PremiumCard
        title="Gestão de Produtos e Letras"
        icon={Package}
        iconColor="#3b82f6"
        badge={
          <div className="flex gap-2 text-[10px] font-black uppercase tracking-widest text-slate-500">
            <span>{produtos.length} Ativos</span>
          </div>
        }
        action={
          <Button
            onClick={() => handleOpenForm()}
            className="bg-slate-900 hover:bg-slate-800 dark:bg-blue-600 dark:hover:bg-blue-500 text-white font-bold gap-2 rounded-xl h-10 px-6 uppercase text-[10px] tracking-widest transition-all hover:scale-[1.02] active:scale-95"
          >
            <Plus className="w-4 h-4" />
            Novo Produto
          </Button>
        }
        className="border-slate-200 dark:border-white/5 dark:bg-slate-900/60 shadow-xl"
        noPadding
      >
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow className="bg-slate-50/80 dark:bg-slate-800/50 border-slate-200 dark:border-slate-800">
                <TableHead className="py-4 px-6 text-[10px] font-black uppercase tracking-widest text-slate-400">Letra / Prefixo</TableHead>
                <TableHead className="py-4 px-3 text-[10px] font-black uppercase tracking-widest text-slate-400">Cod. PCP</TableHead>
                <TableHead className="py-4 px-3 text-[10px] font-black uppercase tracking-widest text-slate-400">Cliente</TableHead>
                <TableHead className="py-4 px-3 text-[10px] font-black uppercase tracking-widest text-slate-400">Descrição</TableHead>
                <TableHead className="py-4 px-3 text-[10px] font-black uppercase tracking-widest text-slate-400">Baixa</TableHead>
                <TableHead className="py-4 px-3 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center">Status</TableHead>
                <TableHead className="py-4 px-3 text-[10px] font-black uppercase tracking-widest text-right pr-6 text-slate-400">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell colSpan={8} className="text-center py-8 text-slate-500">
                    Carregando...
                  </TableCell>
                </TableRow>
              ) : produtos.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} className="text-center py-8 text-slate-500">
                    Nenhum produto cadastrado
                  </TableCell>
                </TableRow>
              ) : (
                produtos.map((produto) => (
                  <TableRow key={produto.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/50 dark:border-slate-800 transition-colors">
                    <TableCell>
                      <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-lg bg-blue-500/5 dark:bg-blue-500/10 border border-blue-500/10 dark:border-blue-400/20 group">
                        <span className="font-mono font-black text-slate-900 dark:text-white text-base tracking-tight leading-none">
                          {produto.letra_produto}
                        </span>
                        <span className="text-blue-500 dark:text-blue-400 font-mono font-black text-[15px] italic border-l border-blue-500/20 pl-1.5 group-hover:pl-2 transition-all">
                          {produto.sufixo}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className="font-mono text-xs font-bold text-slate-500 dark:text-slate-400 bg-slate-100/50 dark:bg-white/5 rounded-lg px-2 py-0.5">
                      {produto.codigo_produto || '-'}
                    </TableCell>
                    <TableCell className="text-slate-900 dark:text-slate-200 font-bold text-sm tracking-tight">{produto.nome_cliente || '-'}</TableCell>
                    <TableCell className="text-slate-500 dark:text-slate-400 text-xs italic max-w-[200px] truncate">{produto.descricao || '-'}</TableCell>
                    <TableCell>
                      <div className="flex items-center">
                        <p className="text-[9px] font-black uppercase tracking-widest leading-none mt-1">
                        {produto.ordem_numeracao === 'DECRESCENTE' ? (
                          <span className="text-purple-600 dark:text-purple-400">↓ Ordem Reversa</span>
                        ) : (
                          <span className="text-blue-600 dark:text-blue-400">↑ Ordem Sequencial</span>
                        )}
                      </p>
                      </div>
                    </TableCell>
                    <TableCell className="text-center">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest transition-colors ${
                        produto.ativo 
                          ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 shadow-[0_0_12px_rgba(16,185,129,0.1)]' 
                          : 'bg-slate-500/10 text-slate-500 border border-slate-500/20'
                      }`}>
                        {produto.ativo ? 'Ativo' : 'Off'}
                      </span>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleOpenForm(produto)}
                          className="hover:bg-slate-100 dark:hover:bg-slate-800 dark:text-slate-400"
                        >
                          <Edit2 className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => deleteMutation.mutate(produto.id)}
                          className="hover:bg-red-50 dark:hover:bg-red-900/10 text-red-500"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
      </PremiumCard>

      {/* Dialog - Criar Cliente Automático */}
      <Dialog open={showClienteForm} onOpenChange={setShowClienteForm}>
        <DialogContent className="max-w-md sm:max-w-[90vw] md:max-w-md border-slate-200/50 dark:border-slate-800/50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl shadow-2xl">
          <DialogHeader className="space-y-3 pb-4 border-b border-slate-100 dark:border-slate-800/50">
            <div className="w-12 h-12 rounded-2xl bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center mb-2">
              <Plus className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
            </div>
            <div>
              <DialogTitle className="text-2xl font-bold tracking-tight bg-gradient-to-br from-slate-900 to-slate-600 dark:from-white dark:to-slate-400 bg-clip-text text-transparent">
                Criar Cliente
              </DialogTitle>
              <p className="text-sm text-slate-500 dark:text-slate-400">
                Dados pré-preenchidos do produto recém criado.
              </p>
            </div>
          </DialogHeader>
          <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg border border-blue-200 dark:border-blue-800 mb-4">
            <p className="text-sm text-blue-900 dark:text-blue-200">
              <strong>Produto:</strong> {produtoRecemCriado?.letra_produto}{produtoRecemCriado?.sufixo}
            </p>
          </div>
          <form onSubmit={(e) => {
            e.preventDefault();
            createClienteMutation.mutate(clienteData);
          }} className="space-y-4">
