// @ts-nocheck
import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Split, AlertTriangle, Package, Loader2 } from 'lucide-react';
import { calcularFim, proximoNumero } from '@/core/numeracaoService';

export default function QuebrarLoteDialog({ reserva, open, onOpenChange, onConfirm, isLoading }) {
  const [quantidadePorLote, setQuantidadePorLote] = useState('');
  const [observacoes, setObservacoes] = useState('');
  const [error, setError] = useState('');

  const calcularLotes = () => {
    const qtdNum = Number(quantidadePorLote);
    if (!quantidadePorLote || qtdNum <= 0) return [];

    const decrescente = reserva.sequencia_decrescente;
    const totalQuantidade = reserva.quantidade;
    const resultLotes = [];
    let numeroAtual = reserva.numero_inicial;
    let quantidadeRestante = totalQuantidade;

    while (quantidadeRestante > 0) {
      const quantidadeLote = Math.min(qtdNum, quantidadeRestante);
      const numeroFinal = calcularFim(numeroAtual, quantidadeLote, decrescente);

      resultLotes.push({
        numero_inicial: numeroAtual,
        numero_final: numeroFinal,
        quantidade: quantidadeLote
      });

      numeroAtual = proximoNumero(numeroFinal, decrescente);
      quantidadeRestante -= quantidadeLote;
    }

    return resultLotes;
  };

  const lotes = calcularLotes();

  const handleSubmit = () => {
    setError('');
    const qtdNum = Number(quantidadePorLote);

    if (!quantidadePorLote || qtdNum <= 0) {
      setError('Digite uma quantidade válida');
      return;
    }

    if (qtdNum >= reserva.quantidade) {
      setError('A quantidade por lote deve ser menor que o total');
      return;
    }

    if (lotes.length < 2) {
      setError('Deve gerar pelo menos 2 lotes');
      return;
    }

    onConfirm({
      quantidadePorLote: qtdNum,
      observacoes,
      lotes
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="md:max-w-2xl dark:bg-slate-900/90 dark:border-white/10 rounded-[2.5rem] p-0 overflow-hidden backdrop-blur-3xl shadow-2xl border-0">
        <div className="bg-gradient-to-br from-purple-900 to-indigo-900 p-8 text-white relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-purple-500/20 rounded-full -mr-32 -mt-32 blur-3xl animate-pulse" />
          <DialogHeader className="relative z-10">
            <DialogTitle className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3">
              <span className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center">
                <Split className="w-6 h-6 text-purple-300" />
              </span>
              Quebrar <span className="text-purple-300">Lote</span>
            </DialogTitle>
            <p className="text-xs font-bold text-purple-200/60 uppercase tracking-widest mt-1">
              Divisão Segmentada • {reserva?.codigo_completo}
            </p>
          </DialogHeader>
        </div>

        <div className="p-0 overflow-y-auto max-h-[70vh]">
          <div className="p-8 space-y-6">
            {/* Informações da Reserva Original */}
            <div className="bg-slate-50 dark:bg-slate-950/40 p-6 rounded-[1.5rem] border border-slate-200 dark:border-white/5 grid grid-cols-2 gap-y-4">
              <div className="space-y-1">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 italic opacity-70">Identificação Base</span>
                <p className="font-mono font-black text-slate-900 dark:text-white leading-none tracking-tighter text-lg">{reserva?.codigo_completo}</p>
              </div>
              <div className="space-y-1 text-right">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 italic opacity-70">Volume Original</span>
                <p className="font-black text-slate-900 dark:text-white text-lg leading-none tracking-tighter">{reserva?.quantidade} Unid.</p>
              </div>
            </div>

            {/* Input de Quantidade */}
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-black uppercase tracking-widest text-slate-600 dark:text-slate-400 italic">Dividir a cada X etiquetas:</Label>
                <Badge variant="outline" className="rounded-full border-purple-500/30 text-purple-600 dark:text-purple-400 font-bold bg-purple-500/5">
                  Recomendado: 50
                </Badge>
              </div>
              <div className="relative group">
                <Input
                  type="number"
                  value={quantidadePorLote}
                  onChange={(e) => setQuantidadePorLote(e.target.value)}
                  placeholder="Ex: 50"
                  className="h-20 text-3xl font-black tracking-tighter bg-white dark:bg-slate-950 border-2 border-slate-200 dark:border-white/10 rounded-[1.5rem] px-8 focus:ring-4 focus:ring-purple-500/20 transition-all group-hover:border-purple-500/40"
                />
                <Package className="absolute right-6 top-1/2 -translate-y-1/2 w-8 h-8 text-slate-300 dark:text-slate-700 pointer-events-none group-focus-within:text-purple-500 transition-colors" />
              </div>
            </div>

            {/* Preview dos Novos Lotes */}
            {lotes.length > 0 && (
              <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
                <div className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 bg-purple-500 rounded-full shadow-[0_0_8px_rgba(168,85,247,0.5)]" />
                  <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-500 italic">Estrutura Resultante ({lotes.length} lotes)</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {lotes.slice(0, 4).map((lote, index) => (
                    <div key={index} className="flex items-center justify-between p-4 rounded-2xl bg-slate-50 dark:bg-slate-950/40 border border-slate-200 dark:border-white/5 group hover:border-purple-500/30 transition-colors">
                      <div className="flex flex-col">
                        <span className="text-[9px] font-bold text-slate-400 uppercase">Lote {String(index + 1).padStart(2, '0')}</span>
                        <span className="font-mono text-xs font-black dark:text-purple-300 tabular-nums">{String(lote.numero_inicial).padStart(3, '0')} a {String(lote.numero_final).padStart(3, '0')}</span>
                      </div>
                      <Badge variant="secondary" className="bg-slate-200 dark:bg-white/5 text-[9px] font-black tracking-tighter">{lote.quantidade} UN</Badge>
                    </div>
                  ))}
                  {lotes.length > 4 && (
                    <div className="col-span-1 sm:col-span-2 text-center p-2 rounded-xl border border-dashed border-slate-200 dark:border-white/10">
                      <span className="text-[10px] font-bold text-slate-400 uppercase italic">+ {lotes.length - 4} outros lotes com a mesma estrutura</span>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Observações */}
            <div className="space-y-3">
              <Label className="text-[10px] font-black uppercase tracking-widest text-slate-400 italic px-1">Justificativa da Divisão</Label>
              <Textarea
                value={observacoes}
                onChange={(e) => setObservacoes(e.target.value)}
                placeholder="Ex: Lote muito grande para os gabinetes atuais..."
                className="min-h-[100px] resize-none rounded-[1.5rem] bg-white dark:bg-slate-950 border-2 border-slate-100 dark:border-white/5 focus:ring-4 focus:ring-purple-500/20 italic font-medium p-4"
              />
            </div>

            {error && (
              <Alert variant="destructive" className="rounded-2xl border-red-500/30 bg-red-500/10 py-4 animate-in fade-in slide-in-from-top-1">
                <AlertTriangle className="h-4 w-4" />
                <AlertDescription className="font-black italic uppercase text-[10px] tracking-widest leading-relaxed">{error}</AlertDescription>
              </Alert>
            )}

            {lotes.length > 1 && !error && (
              <Alert className="bg-purple-600/5 border-purple-500/20 rounded-2xl py-4 transition-all">
                <div className="flex items-center gap-2">
                  <AlertTriangle className="w-4 h-4 text-purple-600" />
                  <AlertDescription className="text-purple-900 dark:text-purple-400 font-black italic uppercase text-[10px] tracking-widest leading-tight">
                    ATENÇÃO: Operação irreversível. O sistema irá desmembrar o lote em <strong>{lotes.length} sub-lotes</strong> permanentes.
                  </AlertDescription>
                </div>
              </Alert>
            )}
          </div>
        </div>

        <DialogFooter className="p-8 pt-0 gap-3">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isLoading}
            className="rounded-xl h-14 font-black uppercase text-[10px] tracking-[0.2em] italic px-10 border-slate-200 dark:border-white/10 dark:hover:bg-white/5"
          >
            Abortar
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={isLoading || lotes.length < 2}
            className="bg-purple-600 hover:bg-purple-700 text-white rounded-xl h-14 font-black uppercase text-[10px] tracking-[0.2em] italic px-12 shadow-2xl shadow-purple-600/20 border-0 group"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-5 h-5 mr-3 animate-spin" />
                Divisão em Curso...
              </>
            ) : (
              <>
                <Split className="w-5 h-5 mr-3 group-hover:scale-110 transition-transform" />
                Confirmar Divisão
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// @ts-nocheck
import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Scissors, AlertTriangle, CheckCircle, Loader2 } from 'lucide-react';
import { calcularQuantidade, calcularFim, proximoNumero } from '@/core/numeracaoService';

export default function EncurtarLoteDialog({ reserva, open, onOpenChange, onConfirm, isLoading }) {
  const [observacoes, setObservacoes] = useState('');
  const [error, setError] = useState('');

  const decrescente = reserva?.sequencia_decrescente || false;
  const inicial = reserva?.numero_inicial || 0;
  const finalOriginal = reserva?.numero_final || 0;
  const baixada = reserva?.quantidade_baixada || 0;

  // Calcula o novo final como o último número que já foi baixado.
  const novoNumeroFinal = calcularFim(inicial, baixada, decrescente) || inicial;

  const quantidadeLiberada = calcularQuantidade(proximoNumero(novoNumeroFinal, decrescente), finalOriginal, decrescente);
  const numeroInicialLiberado = proximoNumero(novoNumeroFinal, decrescente);
  const numeroFinalLiberado = finalOriginal;

  const handleSubmit = () => {
    setError('');

    if (baixada === 0) {
      setError('Não é possível encurtar um lote sem nenhuma baixa registrada.');
      return;
    }

    if (novoNumeroFinal === finalOriginal) {
      setError('O lote já foi totalmente produzido (fechado).');
      return;
    }

    onConfirm({
      novoNumeroFinal,
      observacoes,
      numeracaoLivre: {
        numero_inicial: numeroInicialLiberado,
        numero_final: numeroFinalLiberado,
        quantidade: quantidadeLiberada
      }
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="md:max-w-xl dark:bg-slate-900/90 dark:border-white/10 rounded-[2.5rem] p-0 overflow-hidden backdrop-blur-3xl shadow-2xl border-0">
        <div className="bg-gradient-to-br from-orange-900 to-amber-900 p-8 text-white relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-orange-500/20 rounded-full -mr-32 -mt-32 blur-3xl opacity-50" />
          <DialogHeader className="relative z-10">
            <DialogTitle className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3">
              <span className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center">
                <Scissors className="w-6 h-6 text-orange-300" />
              </span>
              Encurtar <span className="text-orange-300">Lote</span>
            </DialogTitle>
            <p className="text-xs font-bold text-orange-200/60 uppercase tracking-widest mt-1">
              Finalizar Lote Atual • {reserva?.codigo_completo}
            </p>
          </DialogHeader>
        </div>

        <div className="p-0 overflow-y-auto max-h-[70vh]">
          <div className="p-8 space-y-6">

            <Alert className="bg-blue-500/10 border-blue-500/30 text-blue-900 dark:text-blue-300">
              <AlertDescription className="text-sm font-medium">
                Encurtar este lote significa sinalizar que ele foi finalizado {baixada > 0 ? "já na quantidade baixada" : ""} e liberar o fim da numeração {quantidadeLiberada > 0 ? "para criar outros lotes" : ""}.
              </AlertDescription>
            </Alert>

            {/* Visualização Simples do Divisor */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="bg-emerald-500/5 border border-emerald-500/20 p-5 rounded-3xl shadow-sm text-center">
                <div className="flex justify-center mb-2">
                  <CheckCircle className="w-6 h-6 text-emerald-600 dark:text-emerald-400" />
                </div>
                <p className="text-[11px] font-black uppercase tracking-widest text-emerald-900 dark:text-emerald-500/80 mb-1">
                  Reserva Atualizada (Produzido)
                </p>
                <div className="font-mono text-2xl font-black text-slate-900 dark:text-white">
                  {inicial} <span className="text-emerald-500/50">→</span> {novoNumeroFinal}
                </div>
                <p className="text-xs font-bold text-slate-500 mt-2">
                  Total Final: {baixada} un
                </p>
              </div>

              <div className="bg-orange-500/5 border border-orange-500/20 p-5 rounded-3xl shadow-sm text-center opacity-80">
                <div className="flex justify-center mb-2">
                  <AlertTriangle className="w-6 h-6 text-orange-600 dark:text-orange-400" />
                </div>
                <p className="text-[11px] font-black uppercase tracking-widest text-orange-900 dark:text-orange-500/80 mb-1">
                  Retorna p/ Uso (Livre)
                </p>
                <div className="font-mono text-2xl font-black text-slate-900 dark:text-white">
                  {numeroInicialLiberado} <span className="text-orange-500/50">→</span> {numeroFinalLiberado}
                </div>
                <p className="text-xs font-bold text-slate-500 mt-2">
                  Liberados: {quantidadeLiberada} un
                </p>
              </div>
            </div>

            {/* Observações */}
            <div className="space-y-2 pt-2">
              <Label className="text-slate-700 dark:text-slate-300 font-black uppercase text-[10px] tracking-[0.2em] ml-1">Observações do Encurtamento (Opcional)</Label>
              <Textarea
                value={observacoes}
                onChange={(e) => setObservacoes(e.target.value)}
                placeholder="Exemplo: Faltou insumo, cliente pediu menos... etc"
                className="dark:bg-slate-950 dark:border-white/10 rounded-2xl min-h-[100px] resize-none italic leading-relaxed text-sm p-4"
              />
            </div>

            {/* Alertas de Erro */}
            {error && (
              <Alert variant="destructive" className="rounded-2xl border-red-500/30 bg-red-500/10 py-4 animate-in fade-in slide-in-from-top-1">
                <AlertTriangle className="h-4 w-4 shrink-0" />
                <AlertDescription className="font-black italic uppercase text-[10px] tracking-widest leading-relaxed ml-2">{error}</AlertDescription>
              </Alert>
            )}

            {baixada === 0 && !error && (
              <Alert variant="destructive" className="rounded-2xl border-red-500/30 bg-red-500/10 py-4 animate-in fade-in slide-in-from-top-1">
                <AlertTriangle className="h-4 w-4 shrink-0" />
                <AlertDescription className="font-black italic uppercase text-[10px] tracking-widest leading-relaxed ml-2">Não há baixa registrada para este lote. Não é possível encurtar.</AlertDescription>
              </Alert>
            )}

          </div>
        </div>

        <DialogFooter className="p-8 pt-0 gap-3">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isLoading}
            className="rounded-xl h-14 font-black uppercase text-[10px] tracking-[0.2em] italic px-8 border-slate-200 dark:border-white/10 dark:hover:bg-white/5"
          >
            Cancelar
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={isLoading || baixada === 0 || quantidadeLiberada <= 0}
            className="bg-orange-600 hover:bg-orange-700 text-white rounded-xl h-14 font-black uppercase text-[10px] tracking-[0.2em] italic px-10 shadow-2xl shadow-orange-600/20 group border-0 transition-all"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-5 h-5 mr-3 animate-spin" />
                Processando...
              </>
            ) : (
              <>
                <Scissors className="w-5 h-5 mr-3 group-hover:scale-110 transition-transform" />
                Confirmar Encurtamento
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Bell, BellOff, Check, X, AlertTriangle, Info, CheckCircle, Calendar } from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { cn } from '@/lib/utils';
import { motion, AnimatePresence } from 'framer-motion';
import { PremiumCard } from '@/components/ui/PremiumCard';

export default function NotificacoesReserva({ userId }) {
  const queryClient = useQueryClient();
  const [mostrarTodas, setMostrarTodas] = useState(false);

  const { data: notificacoes = [], isLoading } = useQuery({
    queryKey: ['notificacoes-reserva', userId],
    queryFn: async () => {
      if (!userId) return [];
      return await rdsn.entities.Notificacao.filter({
        usuario_id: userId,
        entidade_tipo: 'ReservaLote',
        arquivada: false
      }, '-created_at', 50);
    },
    enabled: !!userId,
    refetchInterval: 30000 // Atualizar a cada 30s
  });

  const marcarLidaMutation = useMutation({
    mutationFn: (id) => rdsn.entities.Notificacao.update(id, { lida: true }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['notificacoes-reserva'] })
  });

  const marcarTodasLidasMutation = useMutation({
    mutationFn: async () => {
      const naoLidas = notificacoes.filter(n => !n.lida);
      for (const n of naoLidas) {
        await rdsn.entities.Notificacao.update(n.id, { lida: true });
      }
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['notificacoes-reserva'] })
  });

  const arquivarMutation = useMutation({
    mutationFn: (id) => rdsn.entities.Notificacao.update(id, { arquivada: true }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['notificacoes-reserva'] })
  });

  const naoLidas = notificacoes.filter(n => !n.lida);
  const exibir = mostrarTodas ? notificacoes : naoLidas;

  const getUrgentColor = (prioridade) => {
    switch (prioridade) {
      case 'ALTA': return 'border-red-500/50 bg-red-50/80 dark:bg-red-500/10 shadow-red-500/10';
      case 'MEDIA': return 'border-yellow-500/50 bg-yellow-50/80 dark:bg-yellow-500/10 shadow-yellow-500/10';
      default: return 'border-blue-500/50 bg-blue-50/80 dark:bg-blue-500/10 shadow-blue-500/10';
    }
  };

  const getTipoIcon = (tipo) => {
    switch (tipo) {
      case 'ALERTA': return <AlertTriangle className="w-5 h-5 text-yellow-500" />;
      case 'ERRO': return <X className="w-5 h-5 text-red-500" />;
      case 'SUCESSO': return <CheckCircle className="w-5 h-5 text-green-500" />;
      default: return <Info className="w-5 h-5 text-blue-500" />;
    }
  };

  if (isLoading) {
    return (
      <PremiumCard title="Notificações de Reservas" icon={Bell}>
        <div className="flex items-center gap-2 text-slate-500 py-10 justify-center">
          <Bell className="w-6 h-6 animate-bounce mr-2" />
          <span className="text-sm font-medium">Sincronizando...</span>
        </div>
      </PremiumCard>
    );
  }

  return (
    <PremiumCard
      title="Notificações de Reservas"
      icon={Bell}
      iconColor="#3b82f6"
      action={
        <div className="flex gap-2 items-center">
          {naoLidas.length > 0 && <Badge className="bg-red-500 text-white shadow-lg shadow-red-500/20">{naoLidas.length}</Badge>}
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 rounded-xl hover:bg-slate-100 dark:hover:bg-white/5 transition-colors"
            onClick={() => setMostrarTodas(!mostrarTodas)}
          >
            {mostrarTodas ? <BellOff className="w-4 h-4" /> : <Bell className="w-4 h-4" />}
          </Button>
          {naoLidas.length > 0 && (
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 rounded-xl hover:bg-slate-100 dark:hover:bg-white/5 text-emerald-600 transition-colors"
              onClick={() => marcarTodasLidasMutation.mutate()}
              disabled={marcarTodasLidasMutation.isPending}
            >
              <Check className="w-4 h-4" />
            </Button>
          )}
        </div>
      }
    >
      <div className="space-y-4">
        {exibir.length === 0 ? (
          <div className="text-center py-8">
            <BellOff className="w-12 h-12 text-slate-300 mx-auto mb-3" />
            <p className="text-sm text-slate-500 font-medium">Nenhuma notificação {mostrarTodas ? '' : 'não lida'}</p>
          </div>
        ) : (
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
            <AnimatePresence mode='popLayout'>
              {exibir.map((notif) => (
                <motion.div
                  key={notif.id}
                  layout
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: 20 }}
                  className={cn(
                    "p-4 rounded-3xl border transition-all duration-300 group",
                    notif.lida
                      ? "bg-slate-50/50 dark:bg-slate-900/40 border-slate-100 dark:border-white/5 opacity-60 hover:opacity-100"
                      : cn("border-l-4 shadow-md backdrop-blur-sm", getUrgentColor(notif.prioridade))
                  )}
                >
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex items-start gap-3">
                      <div className="mt-1">
                        {getTipoIcon(notif.tipo)}
                      </div>
                      <div>
                        <h4 className={cn(
                          "font-bold text-sm tracking-tight",
                          notif.lida ? "text-slate-600 dark:text-slate-400" : "text-slate-900 dark:text-white"
                        )}>
                          {notif.titulo}
                        </h4>
                        <p className="text-xs text-slate-600 dark:text-slate-400 mt-1 leading-relaxed">
                          {notif.mensagem}
                        </p>
                        <div className="flex items-center gap-3 mt-2 text-[10px] uppercase font-black tracking-widest text-slate-400">
                          <span className="flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            {format(new Date(notif.created_at), 'dd/MM/yyyy HH:mm', { locale: ptBR })}
                          </span>
                        </div>
                      </div>
                    </div>

                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      {!notif.lida && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 rounded-full hover:bg-emerald-100 dark:hover:bg-emerald-900/30 text-emerald-600"
                          onClick={() => marcarLidaMutation.mutate(notif.id)}
                        >
                          <Check className="w-4 h-4" />
                        </Button>
                      )}
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 rounded-full hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600"
                        onClick={() => arquivarMutation.mutate(notif.id)}
                      >
                        <X className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        )}
      </div>
    </PremiumCard>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { useSetor } from '../context/SetorContext';
import { Plus, Edit2, Trash2, Users } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { toast } from "sonner";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

export default function ClientesTab() {
  const queryClient = useQueryClient();
  const { setorAtivo, isAdmin } = useSetor();
  const [showForm, setShowForm] = useState(false);
  const [editingCliente, setEditingCliente] = useState(null);
  const [formData, setFormData] = useState({
    nome: '',
    letra_produto: '',
    modelo: '',
    codigo_produto: '',
    setor_id: '',
    ativo: true
  });

  const { data: clientes = [], isLoading } = useQuery({
    queryKey: ['clientes', setorAtivo],
    queryFn: async () => {
      const todos = await rdsn.entities.Cliente.list();
      if (isAdmin && setorAtivo === 'TODOS') return todos;
      return todos.filter(c => c.setor_id === setorAtivo);
    },
    enabled: !!setorAtivo
  });

  const { data: produtos = [] } = useQuery({
    queryKey: ['produtos', setorAtivo],
    queryFn: async () => {
      const todos = await rdsn.entities.Produto.list();
      if (isAdmin && setorAtivo === 'TODOS') return todos;
      return todos.filter(p => p.setor_id === setorAtivo);
    },
    enabled: !!setorAtivo
  });

  const { data: setores = [] } = useQuery({
    queryKey: ['setores'],
    queryFn: () => rdsn.entities.Setor.list()
  });

  const createMutation = useMutation({
    mutationFn: (data) => rdsn.entities.Cliente.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['clientes'] });
      handleCloseForm();
      toast.success('Cliente cadastrado!');
    }
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => rdsn.entities.Cliente.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['clientes'] });
      handleCloseForm();
      toast.success('Cliente atualizado!');
    }
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => rdsn.entities.Cliente.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['clientes'] });
      toast.success('Cliente removido!');
    }
  });

  const handleOpenForm = (cliente = null) => {
    if (cliente) {
      setEditingCliente(cliente);
      setFormData({
        nome: cliente.nome,
        letra_produto: cliente.letra_produto,
        modelo: cliente.modelo || '',
        codigo_produto: cliente.codigo_produto || '',
        setor_id: cliente.setor_id || '',
        ativo: cliente.ativo ?? true
      });
    } else {
      setEditingCliente(null);
      setFormData({
        nome: '',
        letra_produto: '',
        modelo: '',
        codigo_produto: '',
        setor_id: setorAtivo,
        ativo: true
      });
    }
    setShowForm(true);
  };

  const handleCloseForm = () => {
   setShowForm(false);
   setEditingCliente(null);
   setFormData({ nome: '', letra_produto: '', modelo: '', codigo_produto: '', setor_id: setorAtivo, ativo: true });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (editingCliente) {
      updateMutation.mutate({ id: editingCliente.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  return (
    <>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-xl font-semibold text-slate-900">Clientes</h2>
          <p className="text-sm text-slate-500">Cadastro de clientes e modelos</p>
        </div>
        <Button onClick={() => handleOpenForm()} className="bg-slate-900 hover:bg-slate-800">
          <Plus className="w-4 h-4 mr-2" />
          Novo Cliente
        </Button>
      </div>

      <Card className="border-slate-200">
        <CardHeader className="border-b border-slate-100 bg-slate-50/50">
          <CardTitle className="text-lg font-semibold text-slate-800 flex items-center gap-2">
            <Users className="w-5 h-5" />
            Lista de Clientes
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow className="bg-slate-50/50">
                <TableHead className="text-slate-600">Cliente</TableHead>
                <TableHead className="text-slate-600">Letra</TableHead>
                <TableHead className="text-slate-600">Modelo</TableHead>
                <TableHead className="text-slate-600">Código</TableHead>
                <TableHead className="text-slate-600">Status</TableHead>
                <TableHead className="text-slate-600 text-right">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center py-8 text-slate-500">
                    Carregando...
                  </TableCell>
                </TableRow>
              ) : clientes.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center py-8 text-slate-500">
                    Nenhum cliente cadastrado
                  </TableCell>
                </TableRow>
              ) : (
                clientes.map((cliente) => (
                  <TableRow key={cliente.id} className="hover:bg-slate-50/50">
                    <TableCell className="font-medium text-slate-900">
                      {cliente.nome}
                    </TableCell>
                    <TableCell>
                      <div className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-bold text-sm">
                        {cliente.letra_produto}
                      </div>
                    </TableCell>
                    <TableCell className="text-slate-600">{cliente.modelo || '-'}</TableCell>
                    <TableCell className="font-mono text-slate-600">{cliente.codigo_produto || '-'}</TableCell>
                    <TableCell>
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        cliente.ativo ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-600'
                      }`}>
                        {cliente.ativo ? 'Ativo' : 'Inativo'}
                      </span>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button 
                          variant="ghost" 
                          size="icon"
                          onClick={() => handleOpenForm(cliente)}
                        >
                          <Edit2 className="w-4 h-4" />
                        </Button>
                        <Button 
                          variant="ghost" 
                          size="icon"
                          onClick={() => deleteMutation.mutate(cliente.id)}
                        >
                          <Trash2 className="w-4 h-4 text-red-500" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-md sm:max-w-[90vw] md:max-w-md">
          <DialogHeader>
            <DialogTitle>
              {editingCliente ? 'Editar Cliente' : 'Novo Cliente'}
            </DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label>Nome do Cliente *</Label>
              <Input
                value={formData.nome}
                onChange={(e) => setFormData(prev => ({ ...prev, nome: e.target.value }))}
                placeholder="Nome do cliente"
                required
              />
            </div>

            <div className="space-y-2">
              <Label>Letra do Produto *</Label>
              <Select 
                value={formData.letra_produto} 
                onValueChange={(v) => setFormData(prev => ({ ...prev, letra_produto: v }))}
                required
              >
                <SelectTrigger className="font-mono text-lg">
                  <SelectValue placeholder="Selecione a letra" />
                </SelectTrigger>
                <SelectContent>
                   {[...new Set(produtos.filter(p => p.ativo).map(p => p.letra_produto))].sort().map(letra => (
                     <SelectItem key={letra} value={letra} className="font-mono text-lg">
                       {letra}
                     </SelectItem>
                   ))}
                </SelectContent>
              </Select>
              <p className="text-xs text-slate-500">
                Letras disponíveis: {[...new Set(produtos.filter(p => p.ativo).map(p => p.letra_produto))].sort().join(', ')}
              </p>
            </div>

            <div className="space-y-2">
              <Label>Modelo</Label>
              <Input
                value={formData.modelo}
                onChange={(e) => setFormData(prev => ({ ...prev, modelo: e.target.value }))}
                placeholder="Ex: Hidrômetro DN15"
              />
            </div>

            <div className="space-y-2">
              <Label>Código do Produto</Label>
              <Input
                value={formData.codigo_produto}
                onChange={(e) => setFormData(prev => ({ ...prev, codigo_produto: e.target.value }))}
                placeholder="Ex: HYD-DN15-01"
              />
            </div>

            <div className="space-y-2">
              <Label>Setor Produtivo</Label>
              <Select 
                value={formData.setor_id} 
                onValueChange={(v) => setFormData(prev => ({ ...prev, setor_id: v }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione um setor" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value={null}>Nenhum setor</SelectItem>
                  {setores.filter(s => s.ativo).map(setor => (
                    <SelectItem key={setor.id} value={setor.id}>
                      {setor.nome} ({setor.codigo})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="flex items-center justify-between">
              <Label>Cliente Ativo</Label>
              <Switch
                checked={formData.ativo}
                onCheckedChange={(checked) => setFormData(prev => ({ ...prev, ativo: checked }))}
              />
            </div>

            <DialogFooter>
              <Button type="button" variant="outline" onClick={handleCloseForm}>
                Cancelar
              </Button>
              <Button type="submit" className="bg-slate-900 hover:bg-slate-800">
                {editingCliente ? 'Salvar' : 'Cadastrar'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { CircleCheck, Circle, Clock, Package, XCircle } from 'lucide-react';
import { cn } from '@/lib/utils';

const etapas = [
  { key: 'RESERVADO', label: 'Reservado', icon: Circle },
  { key: 'EM_PRODUCAO', label: 'Em Produção', icon: Clock },
  { key: 'BAIXADO', label: 'Baixado', icon: Package },
  { key: 'PRODUZIDO', label: 'Produzido', icon: CircleCheck }
];

export default function WorkflowVisualReserva({ status, quantidade, quantidadeBaixada }) {
  const statusAtual = status === 'CANCELADO' || status === 'LIBERADO' ? status : 
    (quantidade === quantidadeBaixada && quantidade > 0) ? 'PRODUZIDO' :
    (quantidadeBaixada > 0) ? 'EM_PRODUCAO' : 'RESERVADO';

  const isCancelado = status === 'CANCELADO';
  const isLiberado = status === 'LIBERADO';
  const progressoPercentual = quantidade > 0 ? (quantidadeBaixada / quantidade) * 100 : 0;

  if (isCancelado || isLiberado) {
    return (
      <div className="bg-slate-50 rounded-lg p-4 border border-slate-200">
        <div className="flex items-center gap-3">
          <div className={cn(
            "w-10 h-10 rounded-full flex items-center justify-center",
            isCancelado ? "bg-red-100" : "bg-orange-100"
          )}>
            <XCircle className={cn("w-5 h-5", isCancelado ? "text-red-600" : "text-orange-600")} />
          </div>
          <div>
            <p className={cn(
              "font-semibold",
              isCancelado ? "text-red-900" : "text-orange-900"
            )}>
              {isCancelado ? 'Reserva Cancelada' : 'Reserva Liberada'}
            </p>
            <p className="text-xs text-slate-600">
              {isCancelado 
                ? 'Esta reserva foi cancelada e a numeração liberada'
                : 'Numeração disponível para reutilização'}
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg p-6 border border-slate-200">
      <div className="mb-4">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-slate-700">Progresso da Produção</span>
          <span className="text-sm font-bold text-slate-900">
            {quantidadeBaixada} / {quantidade} unidades
          </span>
        </div>
        <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
          <motion.div 
            className="h-full bg-gradient-to-r from-blue-500 to-blue-600"
            initial={{ width: 0 }}
            animate={{ width: `${progressoPercentual}%` }}
            transition={{ duration: 0.5 }}
          />
        </div>
        <p className="text-xs text-slate-500 mt-1">{Math.round(progressoPercentual)}% concluído</p>
      </div>

      <div className="relative">
        <div className="flex justify-between items-center">
          {etapas.map((etapa, idx) => {
            const isAtual = etapa.key === statusAtual;
            const indexAtual = etapas.findIndex(e => e.key === statusAtual);
            const isConcluido = idx < indexAtual;
            const Icon = etapa.icon;

            return (
              <div key={etapa.key} className="flex-1 flex flex-col items-center relative">
                {/* Linha conectora */}
                {idx < etapas.length - 1 && (
                  <div className="absolute top-5 left-[50%] w-full h-0.5 bg-slate-200 -z-10">
                    <motion.div 
                      className="h-full bg-blue-600"
                      initial={{ width: 0 }}
                      animate={{ 
                        width: isConcluido || (isAtual && idx < indexAtual) ? '100%' : '0%' 
                      }}
                      transition={{ duration: 0.5 }}
                    />
                  </div>
                )}

                {/* Ícone da etapa */}
                <motion.div
                  initial={{ scale: 0.8 }}
                  animate={{ scale: isAtual ? 1.1 : 1 }}
                  className={cn(
                    "w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all shadow-sm mb-2",
                    isConcluido ? "bg-blue-600 border-blue-600" :
                    isAtual ? "bg-blue-600 border-blue-600 shadow-lg shadow-blue-200" :
                    "bg-white border-slate-200"
                  )}
                >
                  <Icon className={cn(
                    "w-5 h-5",
                    isConcluido || isAtual ? "text-white" : "text-slate-400"
                  )} />
                </motion.div>

                {/* Label */}
                <p className={cn(
                  "text-xs font-medium text-center",
                  isAtual ? "text-blue-900" : isConcluido ? "text-slate-700" : "text-slate-400"
                )}>
                  {etapa.label}
                </p>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// @ts-nocheck
import React, { useState, useEffect, useMemo } from 'react';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import {
  Package,
  AlertCircle,
  User,
  Zap,
  Save,
  RefreshCw,
  Fingerprint,
  ShieldCheck,
  Play,
  Square
} from 'lucide-react';
import { toast } from 'sonner';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { rdsn } from '@/api/supabaseClient';
import { useAuth } from '@/lib/AuthContext';
import AlternativasAlocacao from './AlternativasAlocacao';
import { cn } from "@/lib/utils";

export default function ReservaForm({ onSubmit, isLoading, produtos = [], pcpOps = [], hideHeader }) {
  const { user } = useAuth();
  const isAdmin = user?.role === 'admin';

  // Estados
  const [setores, setSetores] = useState([]);
  const [setorAtivo, setSetorAtivo] = useState(null);
  const [formData, setFormData] = useState({
    cliente: '',
    letra_produto: '',
    sufixo: '',
    ano: new Date().getFullYear().toString().slice(-2),
    codigo_produto: '',
    mes_producao: format(new Date(), 'MMMM', { locale: ptBR }).toUpperCase(),
    quantidade: '',
    setor_id: null,
    manual: false,
    sequencia_decrescente: false,
    numero_inicial: '',
    numero_final: '',
    unidade: 'UNIDADE 1'
  });

  const [preview, setPreview] = useState(null);
  const [isAllocating, setIsAllocating] = useState(false);
  const [error, setError] = useState('');
  const [showDuplicataDialog, setShowDuplicataDialog] = useState(false);
  const [permitirDuplicata, setPermitirDuplicata] = useState(false);
  const [lacunasSugeridas, setLacunasSugeridas] = useState([]);

  const [produtoSearch, setProdutoSearch] = useState('');
  const [showProdutoSuggestions, setShowProdutoSuggestions] = useState(false);

  // Carregar setores e configurar estado inicial
  useEffect(() => {
    const fetchSetores = async () => {
      try {
        const data = await rdsn.entities.Setor.list();
        setSetores(data || []);

        if (data?.length > 0) {
          const inicial = isAdmin ? 'ALL' : data[0].id;
          setSetorAtivo(inicial);
          if (inicial !== 'ALL') {
            setFormData(prev => ({ ...prev, setor_id: inicial }));
          }
        }
      } catch (err) {
        console.error("Erro ao carregar setores:", err);
      }
    };
    fetchSetores();
  }, [isAdmin]);

  // Unificar produtos cadastrados (PCPCliente) com itens da programação (pcpOps)
  const produtosUnificados = useMemo(() => {
    // 'produtos' agora vem do PCPCliente em Reservas.jsx
    const list = [...(Array.isArray(produtos) ? produtos : [])];
    const ops = Array.isArray(pcpOps) ? pcpOps : [];

    // Adicionar OPs que não estão na lista de clientes (ex: códigos novos ou temporários)
    ops.forEach(op => {
      const codeToUse = op.codigo_produto || op.codigo_op;
      if (codeToUse && !list.find(p => p.codigo === codeToUse)) {
        list.push({
          codigo: codeToUse,
          nome: op.descricao || op.produto_nome || 'PLANEJAMENTO MENSAL',
          setor_id: op.setor_id,
          letra_padrao: op.letra_produto || '',
          sufixo: op.sufixo || '',
          prefixo_padrao: op.prefixo_padrao || '',
          origem: 'pcp_mapa'
        });
      }
    });

    return list.map(item => {
      // Cruzar dado com pcpOps para saber se tem programação no mês
      const temProgramacao = ops.some(op => op.codigo_produto === item.codigo || op.codigo_op === item.codigo);
      return { ...item, tem_programacao: temProgramacao };
    });
  }, [produtos, pcpOps]);

  // Filtrar produtos pelo setor ativo
  const produtosFiltrados = useMemo(() => {
    if (isAdmin && setorAtivo === 'ALL') return produtosUnificados;
    return produtosUnificados.filter(p => p.setor_id === setorAtivo);
  }, [produtosUnificados, setorAtivo, isAdmin]);

  // Auto-alocacao com debounce ao digitar quantidade
  useEffect(() => {
    const qtd = Number(formData.quantidade);
    const letra = formData.letra_produto;
    const ano = Number(formData.ano);

    // Não disparar se manual, faltam dados essenciais, ou setores ainda não carregaram
    if (formData.manual || !qtd || !letra || !ano || formData.quantidade === '') return;

    // Resolver setor aqui para garantir que está disponível
    const setorResolvido = (setorAtivo && setorAtivo !== 'ALL')
      ? setorAtivo
      : formData.setor_id || setores[0]?.id;

    // Aguardar setores carregarem (evita race condition)
    if (!setorResolvido) {
      console.log('[AutoAlloc] Aguardando setores carregarem...');
      return;
    }

    const timer = setTimeout(async () => {
      // 1) Detectar lacunas: reservas CANCELADAS ou LIBERADAS para o mesmo produto e ano
      try {
        const todas = await rdsn.entities.ReservaLote.filter({
          letra_produto: letra,
          ano: ano,
          setor_id: setorResolvido
        });
        const lacunas = (todas || []).filter(r =>
          (r.status === 'CANCELADO' || r.status === 'LIBERADO') && Number(r.quantidade) === qtd
        );
        setLacunasSugeridas(lacunas);
      } catch {
        setLacunasSugeridas([]);
      }

      // 2) Disparar alocacao automatica com o setor já resolvido
      handleAlocarAutomatico(letra, qtd, setorResolvido);
    }, 600);

    return () => clearTimeout(timer);
  }, [formData.quantidade, formData.letra_produto, formData.ano, formData.manual, setorAtivo, formData.setor_id, setores]); // setores adicionado para reagir quando carregarem

  const handleChange = (field, value) => {
    setFormData(prev => {
      const newData = { ...prev, [field]: value };

      const parseInputNumber = (val) => {
        if (typeof val === 'number') return val;
        return Number(String(val || '').replace(',', '.'));
      };

      // Cálculo automático no Modo Manual: Final = Início + Quantidade - 1
      const isManual = field === 'manual' ? value : prev.manual;
      if (isManual && (field === 'numero_inicial' || field === 'quantidade' || field === 'manual')) {
        const inicio = parseInputNumber(field === 'numero_inicial' ? value : prev.numero_inicial);
        const qtd = parseInputNumber(field === 'quantidade' ? value : prev.quantidade);

        if (inicio > 0 && qtd > 0) {
          const fimCalculado = inicio + qtd - 1;
          // Usar toFixed ou formatar para evitar dízimas de ponto flutuante se necessário, 
          // mas String() costuma ser ok para poucos decimais.
          newData.numero_final = String(Number(fimCalculado.toFixed(4))); 
        }
      }

      // Ao ATIVAR modo manual, sugerir próximo número disponível como ponto de partida
      if (field === 'manual' && value === true) {
        const letra = prev.letra_produto;
        const qtd = Number(prev.quantidade);
        const ano = Number(prev.ano);
        const s_id = prev.setor_id || (setorAtivo !== 'ALL' ? setorAtivo : null) || setores[0]?.id;
        if (letra && qtd > 0 && ano && s_id) {
          // Dispara de forma async sem bloquear o setState
          setTimeout(() => handleAlocarAutomatico(letra, qtd, s_id), 0);
        }
      }

      return newData;
    });

    setError('');

    if (['letra_produto', 'sufixo', 'ano', 'quantidade', 'codigo_produto'].includes(field)) {
      setPreview(null);
    }
  };

  const handleCodigoProdutoChange = (codigo) => {
    if (!codigo) return;

    // Buscar nas duas fontes
    const pArray = produtosFiltrados;
    const produto = pArray.find(p => p.codigo === codigo);

    // Buscar todas as OPs relacionadas (suporta duplicados e atrasos)
    const opsArray = Array.isArray(pcpOps) ? pcpOps : [];
    const opsRelacionadas = opsArray.filter(op =>
      op.codigo_produto === codigo || op.codigo_op === codigo
    );
    const temProgramacao = opsRelacionadas.length > 0;

    const fetchAnteriores = async () => {
      try {
        // Filtrar reservas existentes pelo código e pelo ano atual do formulário
        const rArray = await rdsn.entities.ReservaLote.filter({
          codigo_produto: codigo,
          ano: parseInt(formData.ano), // Filtro por ano para garantir saldo isolado
          status: { $ne: 'CANCELADO' }
        });

        const parseInputNumber = (val) => {
          if (typeof val === 'number') return val;
          return Number(String(val || '').replace(',', '.'));
        };

        const qtdJaReservada = (rArray || []).reduce((acc, r) => acc + (parseInputNumber(r.quantidade) || 0), 0);

        // Somar demanda de todas as OPs encontradas
        const qtdPCPTotal = opsRelacionadas.reduce((acc, op) => acc + (parseInputNumber(op.quantidade_total) || 0), 0);
        const qtdFaltante = Math.max(0, qtdPCPTotal - qtdJaReservada);

        // Pegar dados da OP mais recente ou da primeira para preenchimento
        const opPrincipal = opsRelacionadas[0];

        // Calcular os valores finais para alocação automática ANTES de setFormData
        // Prioridade: cadastro técnico > OP principal > estado atual do formulário
        const letraFinal = produto?.letra_padrao || produto?.letra_produto || opPrincipal?.letra_produto || formData.letra_produto;
        const qtdFinal = qtdFaltante > 0 ? qtdFaltante : (qtdPCPTotal > 0 && qtdJaReservada === 0 ? qtdPCPTotal : Number(formData.quantidade));
        const setorFinal = opPrincipal?.setor_id || produto?.setor_id || formData.setor_id
          || (setorAtivo && setorAtivo !== 'ALL' ? setorAtivo : null)
          || setores[0]?.id;

        // Resolver sufixo: cadastro técnico > extrair do prefixo_padrao > OP > estado atual
        const sufixoFinal = produto?.sufixo
          || produto?.prefixo_padrao?.replace(/^[A-Z]/i, '')
          || opPrincipal?.sufixo
          || '';

        setFormData(prev => {
          const newData = {
            ...prev,
            codigo_produto: codigo,
            modelo: opPrincipal?.descricao || produto?.modelo || produto?.nome || 'PRODUTO',
            // Prioridade absoluta para a letra do cadastro técnico/cliente, fallback para OP
            letra_produto: letraFinal,
            sufixo: sufixoFinal || prev.sufixo || '',
            cliente: opPrincipal?.cliente_nome || produto?.nome || prev.cliente,
            setor_id: setorFinal
          };

          // Autopreencher quantidade apenas se houver saldo no PCP agregado
          if (qtdFaltante > 0) {
            newData.quantidade = String(qtdFaltante);
          } else if (qtdPCPTotal > 0 && qtdJaReservada === 0) {
            newData.quantidade = String(qtdPCPTotal);
          } else {
            newData.quantidade = String(qtdFinal); // Usar o valor já calculado
          }

          return newData;
        });

        if (!temProgramacao) {
          toast.warning("Registrado no cadastro geral, mas sem programação mensal.", {
            description: "Você pode prosseguir, mas este lote não abaterá saldo do mapa mensal."
          });
        } else {
          // Checar se as OPs casam com o mês atual (prevenindo falso-positivo de atrasos remotos)
          const mesAtual = new Date().getMonth() + 1;
          const temAtraso = opsRelacionadas.some(op => (op.mes || op.j_data?.mes) !== mesAtual);

          toast.success(`Demanda Consolidada!`, {
            description: `Saldo Total: ${qtdFaltante} ${temAtraso ? "(inclui atrasos)" : ""} | ${opsRelacionadas.length} OP(s) encontradas.`
          });
        }

        // Tenta alocação automática se tiver os dados necessários
        if (letraFinal && qtdFinal > 0 && !formData.manual) {
          handleAlocarAutomatico(letraFinal, qtdFinal, setorFinal);
        }
      } catch (err) {
        console.error("Erro ao buscar reservas anteriores:", err);
      }
    };

    fetchAnteriores();
  };

  const handleInputCodigoBlur = () => {
    const val = (produtoSearch || formData.codigo_produto || '').toUpperCase();
    const pArray = Array.isArray(produtos) ? produtos : [];
    const produtoMatch = pArray.find(p => p.codigo === val);

    if (produtoMatch) {
      // Forçar atualização mesmo que o código seja o mesmo, para garantir que os dados de OPs foram puxados
      handleCodigoProdutoChange(val);
    }

    // Usar timeout para permitir que o clique no botão de sugestão ocorra
    setTimeout(() => setShowProdutoSuggestions(false), 200);
  };

  const handleAlocarAutomatico = async (overrideLetra, overrideQtd, overrideSetorId) => {
    const parseInputNumber = (val) => {
      if (typeof val === 'number') return val;
      return Number(String(val || '').replace(',', '.'));
    };

    const letra = overrideLetra || formData.letra_produto;
    const qtd = parseInputNumber(overrideQtd || formData.quantidade);
    const ano = parseInputNumber(formData.ano);
    // Resolução robusta do setor: prioridade ao override, depois form, depois tab ativa, depois primeiro da lista
    const s_id = overrideSetorId
      || formData.setor_id
      || (setorAtivo && setorAtivo !== 'ALL' ? setorAtivo : null)
      || setores[0]?.id;

    console.log('[AutoAlloc] Tentando alocar:', { letra, qtd, ano, s_id, setorAtivo, formSetor: formData.setor_id });

    if (!letra || !ano || !qtd || !s_id) {
      const motivo = !letra ? 'letra' : !ano ? 'ano' : !qtd ? 'quantidade' : 'setor';
      console.warn(`[AutoAlloc] Abortado: campo '${motivo}' ausente`);
      if (!overrideLetra) setError(`Preencha o campo '${motivo}' para alocação automática`);
      return;
    }

    setIsAllocating(true);
    setPreview(null);
    setError('');

    try {
      const resp = await rdsn.functions.invoke('alocarNumerosAutomatico', {
        letra_produto: letra,
        ano: ano,
        quantidade: qtd,
        setor_id: s_id
      });

      // A resposta vem encapsulada em 'data' se for via simulator ou fetch real
      const result = resp?.data || resp;

      if (!result) throw new Error('Resposta vazia do serviço de alocação');
      if (result.error) throw new Error(result.error);
      if (!result.intervalo) throw new Error('Nenhum intervalo disponível encontrado');

      console.log('[AutoAlloc] Sucesso:', result.intervalo);
      setPreview(result);
      setFormData(prev => ({
        ...prev,
        numero_inicial: result.intervalo.numero_inicial,
        numero_final: result.intervalo.numero_final
      }));
    } catch (err) {
      console.error('[AutoAlloc] Erro:', err);
      setError(err.message || 'Falha na alocação automática');
    } finally {
      setIsAllocating(false);
    }
  };

  const handleSelecionarAlternativa = (alt) => {
    setFormData(p => ({
      ...p,
      numero_inicial: alt.numero_inicial,
      numero_final: alt.numero_final
    }));
    setPreview(p => ({
      ...p,
      numero_inicial: alt.numero_inicial,
      numero_final: alt.numero_final,
      codigo_completo: alt.codigo_completo
