        if (duplicada) {
          setShowDuplicataDialog(true);
          return;
        }
      } catch (err) {
        console.error("Erro verificação duplicata:", err);
      }
    }

    const parseInputNumber = (val) => {
      if (typeof val === 'number') return val;
      return Number(String(val || '').replace(',', '.'));
