export function usePermissoes() {
  const { data: currentUser } = useQuery({
    queryKey: ['internalUser'],
    queryFn: () => {
      try {
        return SessionManager.getUser();
      } catch {
        return null;
      }
    },
    staleTime: 0,
    gcTime: 0,
  });

  // Buscar o role do usuário e suas permissões consolidadas
  const { data: rolePermissoes } = useQuery({
    queryKey: ['role-permissoes', currentUser?.role_custom],
    queryFn: async () => {
      if (!currentUser?.role_custom) return {};
      const roles = await rdsn.entities.PermissaoRole.filter({ role: currentUser.role_custom });
      if (roles.length > 0 && roles[0].permissoes) {
        return roles[0].permissoes;
      }
      return {};
    },
    enabled: !!currentUser?.role_custom,
    staleTime: 0,
    gcTime: 0,
  });

  const isAdmin = currentUser?.role_custom === 'Admin';

  // Permissões efetivas: customizadas do usuário sobrescrevem as do role
  const permissoesEfetivas = React.useMemo(() => {
    const rolePerms = rolePermissoes || {};
    const userPerms = currentUser?.permissoes_customizadas || {};
    return { ...rolePerms, ...userPerms };
  }, [rolePermissoes, currentUser?.permissoes_customizadas]);

  const temPermissao = (permissaoKey) => {
    if (isAdmin) return true;
    if (!permissaoKey) return false;

    // Checa permissão no formato novo (modulo.acao)
    if (permissoesEfetivas[permissaoKey] === true) return true;

    // Retrocompat: checa formato antigo (ex: criar_reservas -> reservas.criar)
    const legacyMap = {
      acessar_dashboard: 'dashboard.visualizar',
      criar_reservas: 'reservas.criar',
      editar_reservas: 'reservas.editar',
      deletar_reservas: 'reservas.excluir',
      registrar_producao: 'producao.registrar',
      gerenciar_estoque: 'estoque.editar',
      visualizar_relatorios: 'relatorios.visualizar',
      exportar_dados: 'relatorios.exportar',
      visualizar_auditoria: 'auditoria.visualizar',
      criar_usuarios: 'usuarios.criar',
      editar_usuarios: 'usuarios.editar',
      deletar_usuarios: 'usuarios.excluir',
      acessar_agendamento: 'agendamento.visualizar',
    };
    const mappedKey = legacyMap[permissaoKey];
    if (mappedKey && permissoesEfetivas[mappedKey] === true) return true;

    return false;
  };

  const temQualquerPermissao = (permissoesList) => {
    if (isAdmin) return true;
    return permissoesList.some(perm => temPermissao(perm));
  };

  const temTodasPermissoes = (permissoesList) => {
    if (isAdmin) return true;
    return permissoesList.every(perm => temPermissao(perm));
  };

  return {
    temPermissao,
    temQualquerPermissao,
    temTodasPermissoes,
    isAdmin,
    permissoes: permissoesEfetivas,
    currentUser,
    rolePermissoes: rolePermissoes || {},
  };
}

import { useState, useCallback, useMemo } from 'react';

export function useSearch(items = [], searchableFields = []) {
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedTerm, setDebouncedTerm] = useState('');

  // Debounce da busca para melhor performance
  const handleSearch = useCallback((term) => {
    setSearchTerm(term);
    const timer = setTimeout(() => {
      setDebouncedTerm(term.toLowerCase());
    }, 300);
    return () => clearTimeout(timer);
  }, []);

  // Filtragem otimizada com useMemo
  const results = useMemo(() => {
    if (!debouncedTerm) return items;

    return items.filter(item => {
      // Busca em múltiplos campos
      return searchableFields.some(field => {
        const value = item[field];
        if (!value) return false;

        // Converter para string e fazer busca case-insensitive
        const stringValue = String(value).toLowerCase();
        return stringValue.includes(debouncedTerm);
      });
    });
  }, [items, debouncedTerm, searchableFields]);

  return {
    searchTerm,
    setSearchTerm,
    debouncedTerm,
    handleSearch,
    results,
    hasResults: results.length > 0,
    resultCount: results.length
  };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { toast } from 'sonner';
import { useEffect } from 'react';

export function useNotifications(userId) {
  const queryClient = useQueryClient();

  // Buscar notificações
  const { data: notificacoes = [], isLoading } = useQuery({
    queryKey: ['notificacoes', userId],
    queryFn: async () => {
      if (!userId) return [];
      return await rdsn.entities.Notificacao.filter(
        { usuario_id: userId, arquivada: false },
        '-created_at',
        50
      );
    },
    enabled: !!userId,
    refetchInterval: 10000, // Atualiza a cada 10 segundos
  });

  // Notificações não lidas
  const naoLidas = notificacoes.filter(n => !n.lida);

  // Mutation para marcar como lida
  const marcarComoLidaMutation = useMutation({
    mutationFn: async (notificacaoId) => {
      await rdsn.entities.Notificacao.update(notificacaoId, { lida: true });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notificacoes'] });
    },
  });

  // Mutation para arquivar
  const arquivarMutation = useMutation({
    mutationFn: async (notificacaoId) => {
      await rdsn.entities.Notificacao.update(notificacaoId, { arquivada: true });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notificacoes'] });
      toast.success('Notificação arquivada');
    },
  });

  // Mutation para marcar todas como lidas
  const marcarTodasComoLidasMutation = useMutation({
    mutationFn: async () => {
      const promises = naoLidas.map(n => 
        rdsn.entities.Notificacao.update(n.id, { lida: true })
      );
      await Promise.all(promises);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notificacoes'] });
      toast.success('Todas as notificações foram marcadas como lidas');
    },
  });

  // Reproduzir som para novas notificações
  useEffect(() => {
    if (naoLidas.length > 0) {
      const ultimaNotificacao = naoLidas[0];
      const tempoDesdeNotificacao = Date.now() - new Date(ultimaNotificacao.created_at).getTime();

      // Se a notificação foi criada há menos de 5 segundos, é nova
      if (tempoDesdeNotificacao < 5000) {
        playNotificationSound(ultimaNotificacao.prioridade);
      }
    }
  }, [naoLidas.length]);

  return {
    notificacoes,
    naoLidas,
    isLoading,
    marcarComoLida: marcarComoLidaMutation.mutate,
    arquivar: arquivarMutation.mutate,
    marcarTodasComoLidas: marcarTodasComoLidasMutation.mutate,
  };
}

// Função para reproduzir som de notificação
function playNotificationSound(prioridade) {
  try {
    const audio = new Audio();
    // Usar diferentes frequências para diferentes prioridades
    const context = new (window.AudioContext || window['webkitAudioContext'])();
    const oscillator = context.createOscillator();
    const gainNode = context.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(context.destination);

    // Ajustar frequência baseado na prioridade
    switch (prioridade) {
      case 'CRITICA':
        oscillator.frequency.value = 800;
        gainNode.gain.value = 0.3;
        break;
      case 'ALTA':
        oscillator.frequency.value = 600;
        gainNode.gain.value = 0.2;
        break;
      case 'MEDIA':
        oscillator.frequency.value = 450;
        gainNode.gain.value = 0.15;
        break;
      default:
        oscillator.frequency.value = 350;
        gainNode.gain.value = 0.1;
    }

    oscillator.type = 'sine';
    oscillator.start(context.currentTime);
    oscillator.stop(context.currentTime + 0.15);

    // Vibração para dispositivos móveis
    if (navigator.vibrate && prioridade === 'CRITICA') {
      navigator.vibrate([100, 50, 100]);
    }
  } catch (error) {
    console.log('Som de notificação não disponível:', error);
  }
}

// Hook para criar notificações
export function useCreateNotification() {
