import React, { useState } from 'react';
import { Button } from "@/components/ui/button";
import { Download, FileText, Loader2, ArrowDownToLine } from 'lucide-react';
import { toast } from "sonner";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import ExcelJS from 'exceljs';
import { jsPDF } from 'jspdf';

export default function ExportarRelatorio({ dados, colunas, titulo, resumo, filtrosAplicados, observacoes }) {
  const [exportando, setExportando] = useState(null);

  const exportarExcel = async () => {
    if (!dados || dados.length === 0) {
      toast.error('Nenhum dado para exportar');
      return;
    }

    setExportando('excel');
    const loadingToast = toast.loading('Gerando Excel...');

    try {
      const workbook = new ExcelJS.Workbook();
      workbook.creator = 'Sistema';
      workbook.created = new Date();

      // -- ABA RESUMO --
      const resumoSheet = workbook.addWorksheet('Resumo');
      let row = 1;

      resumoSheet.mergeCells(`A${row}:D${row}`);
      const titleCell = resumoSheet.getCell(`A${row}`);
      titleCell.value = (titulo || 'RELATORIO').toUpperCase();
      titleCell.font = { name: 'Arial', size: 14, bold: true, color: { argb: 'FFFFFFFF' } };
      titleCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1e293b' } };
      titleCell.alignment = { horizontal: 'center', vertical: 'middle' };
      resumoSheet.getRow(row).height = 30;
      row += 2;

      const addInfoRow = (label, value) => {
        resumoSheet.getCell(`A${row}`).value = label;
        resumoSheet.getCell(`A${row}`).font = { name: 'Arial', size: 10, bold: true };
        resumoSheet.getCell(`B${row}`).value = value;
        resumoSheet.getCell(`B${row}`).font = { name: 'Arial', size: 10 };
        row++;
      };

      addInfoRow('Gerado em:', new Date().toLocaleString('pt-BR'));
      row++;

      if (filtrosAplicados && Object.keys(filtrosAplicados).length > 0) {
        resumoSheet.mergeCells(`A${row}:D${row}`);
        const fh = resumoSheet.getCell(`A${row}`);
        fh.value = 'FILTROS APLICADOS';
        fh.font = { name: 'Arial', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
        fh.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF475569' } };
        row++;
        Object.entries(filtrosAplicados).forEach(([key, val]) => {
          if (val && val !== 'TODOS' && val !== '' && val !== '-') addInfoRow(key, val);
        });
        row++;
      }

      if (resumo && Object.keys(resumo).length > 0) {
        resumoSheet.mergeCells(`A${row}:D${row}`);
        const rh = resumoSheet.getCell(`A${row}`);
        rh.value = 'RESUMO';
        rh.font = { name: 'Arial', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
        rh.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF475569' } };
        row++;
        Object.entries(resumo).forEach(([key, val]) => {
          addInfoRow(key, typeof val === 'number' ? val.toLocaleString('pt-BR') : val);
        });
      }

      resumoSheet.columns = [{ width: 25 }, { width: 25 }, { width: 20 }, { width: 20 }];

      // -- ABA DADOS --
      const dadosSheet = workbook.addWorksheet('Dados');

      dadosSheet.columns = colunas.map(col => ({
        header: col.label || col.key,
        key: col.key,
        width: col.width || Math.max(12, (col.label || col.key).length + 4)
      }));

      const headerRow = dadosSheet.getRow(1);
      headerRow.height = 25;
      headerRow.eachCell((cell) => {
        cell.font = { name: 'Arial', size: 10, bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1e293b' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = {
          top: { style: 'thin' }, bottom: { style: 'thin' },
          left: { style: 'thin' }, right: { style: 'thin' }
        };
      });

      const statusColors = {
        'RESERVADO': { font: 'FF1E40AF', bg: 'FFDBEAFE' },
        'EM_PRODUCAO': { font: 'FF92400E', bg: 'FFFEF3C7' },
        'PRODUZIDO': { font: 'FF166534', bg: 'FFDCFCE7' },
        'BAIXADO': { font: 'FF6B21A8', bg: 'FFF3E8FF' },
        'CANCELADO': { font: 'FF991B1B', bg: 'FFFEE2E2' },
        'LIBERADO': { font: 'FF0F766E', bg: 'FFCCFBF1' }
      };

      dados.forEach((item, idx) => {
        const rowData = {};
        colunas.forEach(col => {
          rowData[col.key] = item[col.key] !== undefined && item[col.key] !== null ? item[col.key] : '-';
        });

        const dataRow = dadosSheet.addRow(rowData);
        dataRow.font = { name: 'Arial', size: 9 };

        const bgColor = idx % 2 === 0 ? 'FFF1F5F9' : 'FFFFFFFF';
        dataRow.eachCell((cell) => {
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: bgColor } };
          cell.border = {
            top: { style: 'thin', color: { argb: 'FFE2E8F0' } },
            bottom: { style: 'thin', color: { argb: 'FFE2E8F0' } },
            left: { style: 'thin', color: { argb: 'FFE2E8F0' } },
            right: { style: 'thin', color: { argb: 'FFE2E8F0' } }
          };
          cell.alignment = { vertical: 'middle' };
        });

        // Colorir status
        const statusColIdx = colunas.findIndex(c => c.key === 'status');
        if (statusColIdx >= 0) {
          const statusCell = dataRow.getCell(statusColIdx + 1);
          const sv = String(statusCell.value || '').toUpperCase();
          const sc = statusColors[sv];
          if (sc) {
            statusCell.font = { name: 'Arial', size: 9, bold: true, color: { argb: sc.font } };
            statusCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: sc.bg } };
          }
        }
      });

      // Rodapé
      const footerRow = dadosSheet.addRow({});
      footerRow.getCell(1).value = `Total: ${dados.length} registros`;
      footerRow.getCell(1).font = { name: 'Arial', size: 9, bold: true, italic: true };

      dadosSheet.autoFilter = {
        from: { row: 1, column: 1 },
        to: { row: dados.length + 1, column: colunas.length }
      };
      dadosSheet.views = [{ state: 'frozen', ySplit: 1 }];

      // Gerar e baixar
      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${(titulo || 'relatorio').replace(/\s+/g, '_').toLowerCase()}_${new Date().toISOString().split('T')[0]}.xlsx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      toast.success('Excel exportado com sucesso!', { id: loadingToast });
    } catch (error) {
      console.error('Erro ao gerar Excel:', error);
      toast.error('Erro ao gerar Excel: ' + (error.message || 'Erro desconhecido'), { id: loadingToast });
    } finally {
      setExportando(null);
    }
  };

  const exportarPDF = async () => {
    if (!dados || dados.length === 0) {
      toast.error('Nenhum dado para exportar');
      return;
    }

    setExportando('pdf');
    const loadingToast = toast.loading('Gerando PDF...');

    try {
      const numCols = colunas.length;
      const orientacao = numCols > 7 ? 'landscape' : 'portrait';
      const doc = new jsPDF({ orientation: orientacao });
      const pageWidth = doc.internal.pageSize.width;
      const pageHeight = doc.internal.pageSize.height;
      const marginLeft = 10;
      const marginRight = 10;
      const usableWidth = pageWidth - marginLeft - marginRight;

      // Cabeçalho
      doc.setFillColor(15, 23, 42);
      doc.rect(0, 0, pageWidth, 35, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(18);
      doc.setFont(undefined, 'bold');
      doc.text((titulo || 'Relatorio').toUpperCase(), pageWidth / 2, 15, { align: 'center' });
      doc.setFontSize(9);
      doc.setFont(undefined, 'normal');
      doc.text(`Gerado em: ${new Date().toLocaleString('pt-BR')}`, pageWidth / 2, 25, { align: 'center' });

      let y = 42;

      // Filtros
      if (filtrosAplicados && Object.keys(filtrosAplicados).length > 0) {
        const filtrosTexto = Object.entries(filtrosAplicados)
          .filter(([, v]) => v && v !== 'TODOS' && v !== '' && v !== '-')
          .map(([k, v]) => `${k}: ${v}`)
          .join('  |  ');

        if (filtrosTexto) {
          doc.setFillColor(241, 245, 249);
          doc.rect(marginLeft, y, usableWidth, 8, 'F');
          doc.setTextColor(71, 85, 105);
          doc.setFontSize(7);
          doc.setFont(undefined, 'italic');
          doc.text('Filtros: ' + filtrosTexto, marginLeft + 3, y + 5);
          y += 11;
        }
      }

      // Resumo
      if (resumo && Object.keys(resumo).length > 0) {
        doc.setFillColor(241, 245, 249);
        doc.rect(marginLeft, y, usableWidth, 10, 'F');
        doc.setTextColor(30, 41, 59);
        doc.setFontSize(8);
        doc.setFont(undefined, 'bold');
        const resumoTexto = Object.entries(resumo)
          .map(([k, v]) => `${k}: ${typeof v === 'number' ? v.toLocaleString('pt-BR') : v}`)
          .join('   |   ');
        doc.text(resumoTexto, marginLeft + 3, y + 6);
        y += 14;
      }

      // Observações
      if (observacoes && observacoes.trim()) {
        doc.setFillColor(254, 249, 195);
        doc.rect(marginLeft, y, usableWidth, 8, 'F');
        doc.setTextColor(120, 53, 15);
        doc.setFontSize(7);
        doc.setFont(undefined, 'italic');
        doc.text('Obs: ' + observacoes.substring(0, 200), marginLeft + 3, y + 5);
        y += 11;
      }

      // Calcular largura colunas
      const colWidths = colunas.map(col => col.width || 14);
      const totalWidth = colWidths.reduce((a, b) => a + b, 0);
      const scaleFactor = usableWidth / totalWidth;
      const scaledWidths = colWidths.map(w => w * scaleFactor);

      // Header da tabela
      const drawTableHeader = () => {
        doc.setFillColor(100, 116, 139);
        doc.rect(marginLeft, y, usableWidth, 8, 'F');
        doc.setTextColor(255, 255, 255);
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');

        let xPos = marginLeft + 1;
        colunas.forEach((col, idx) => {
          const maxChars = Math.floor(scaledWidths[idx] / 2);
          const label = (col.label || col.key).substring(0, maxChars);
          doc.text(label, xPos, y + 5);
          xPos += scaledWidths[idx];
        });
        y += 10;
      };

      drawTableHeader();

      // Dados
      doc.setFont(undefined, 'normal');
      doc.setFontSize(6.5);

      dados.forEach((item, rowIdx) => {
        if (y > pageHeight - 18) {
          doc.setTextColor(150, 150, 150);
          doc.setFontSize(6);
          doc.text(`Pag ${doc.internal.pages.length - 1}`, pageWidth / 2, pageHeight - 5, { align: 'center' });
          doc.addPage();
          y = 15;
          drawTableHeader();
          doc.setFont(undefined, 'normal');
          doc.setFontSize(6.5);
        }

        if (rowIdx % 2 === 0) {
          doc.setFillColor(248, 250, 252);
          doc.rect(marginLeft, y, usableWidth, 6, 'F');
        }

        doc.setTextColor(51, 65, 85);
        let xPos = marginLeft + 1;
        colunas.forEach((col, idx) => {
          const val = item[col.key];
          let texto = val !== null && val !== undefined ? String(val) : '-';
          const maxChars = Math.floor(scaledWidths[idx] / 2);
          if (texto.length > maxChars) texto = texto.substring(0, maxChars - 1) + '..';
          doc.text(texto, xPos, y + 4);
          xPos += scaledWidths[idx];
        });

        y += 6;
      });

      // Rodapé final
      y += 3;
      doc.setTextColor(100, 116, 139);
      doc.setFontSize(7);
      doc.setFont(undefined, 'bold');
      doc.text(`Total: ${dados.length} registros`, marginLeft, y);

      // Rodapé em todas as paginas
      const totalPages = doc.internal.pages.length - 1;
      for (let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        doc.setFillColor(241, 245, 249);
        doc.rect(0, pageHeight - 12, pageWidth, 12, 'F');
        doc.setTextColor(100, 116, 139);
        doc.setFontSize(6);
        doc.text(`Pagina ${i} de ${totalPages}`, pageWidth / 2, pageHeight - 5, { align: 'center' });
        doc.text('Sistema de Controle de Numeracao', marginLeft, pageHeight - 5);
      }

      doc.save(`${(titulo || 'relatorio').replace(/\s+/g, '_').toLowerCase()}_${new Date().toISOString().split('T')[0]}.pdf`);

      toast.success('PDF exportado com sucesso!', { id: loadingToast });
    } catch (error) {
      console.error('Erro ao gerar PDF:', error);
      toast.error('Erro ao gerar PDF: ' + (error.message || 'Erro desconhecido'), { id: loadingToast });
    } finally {
      setExportando(null);
    }
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button 
          variant="outline" 
          className="h-12 px-5 rounded-2xl bg-white/50 dark:bg-slate-900/50 backdrop-blur-md border border-slate-200/50 dark:border-slate-800/50 text-slate-700 dark:text-slate-300 font-bold uppercase text-[11px] tracking-wider gap-2 hover:bg-white dark:hover:bg-slate-800 transition-all shadow-sm"
          disabled={!!exportando}
        >
          {exportando ? <Loader2 className="w-4 h-4 animate-spin" /> : <ArrowDownToLine className="w-4 h-4" />}
          Exportar
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-56 rounded-2xl border-slate-200/50 dark:border-slate-800/50 bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl p-2 shadow-xl shadow-slate-200/20 dark:shadow-black/40">
        <DropdownMenuItem onClick={exportarExcel} disabled={!!exportando} className="flex items-center gap-3 p-3 rounded-xl cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800/80 font-semibold text-sm text-slate-700 dark:text-slate-200 focus:bg-slate-100 dark:focus:bg-slate-800">
          <Download className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
          Planilha (Excel)
        </DropdownMenuItem>
        <DropdownMenuItem onClick={exportarPDF} disabled={!!exportando} className="flex items-center gap-3 p-3 rounded-xl cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800/80 font-semibold text-sm text-slate-700 dark:text-slate-200 mt-1 focus:bg-slate-100 dark:focus:bg-slate-800">
          <FileText className="w-4 h-4 text-rose-600 dark:text-rose-400" />
          Documento (PDF)
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { X, Sliders } from 'lucide-react';

export default function AdvancedFilters({
  filters,
  onFilterChange,
  opcoesDisponiveis,
  statusOptions,
  isExpanded,
  onToggleExpanded
}) {
  const [tempFilters, setTempFilters] = useState(filters);

  const handleApply = () => {
    onFilterChange(tempFilters);
    onToggleExpanded(false);
  };

  const handleReset = () => {
    const resetFilters = {
      dataInicio: '',
      dataFim: '',
      letra_produto: 'TODOS',
      cliente: 'TODOS',
      status: 'TODOS',
      celula: 'TODOS',
      operador: 'TODOS'
    };
    setTempFilters(resetFilters);
    onFilterChange(resetFilters);
  };

  const handleChange = (field, value) => {
    const updated = { ...tempFilters, [field]: value };
    setTempFilters(updated);
  };

  return (
    <div className="space-y-4">
      {!isExpanded && (
        <Button
          variant="outline"
          onClick={() => onToggleExpanded(true)}
          className="w-full justify-start text-left"
        >
          <Sliders className="w-4 h-4 mr-2" />
          Filtros Avançados
        </Button>
      )}

      {isExpanded && (
        <Card className="border-blue-200 bg-blue-50/50">
          <CardHeader className="pb-3 flex flex-row items-center justify-between">
            <CardTitle className="text-base">Filtros Avançados</CardTitle>
            <Button
              size="icon"
              variant="ghost"
              onClick={() => onToggleExpanded(false)}
              className="h-6 w-6"
            >
              <X className="w-4 h-4" />
            </Button>
          </CardHeader>
          <CardContent>
            <div className="space-y-6">
              {/* Período */}
              <div>
                <h4 className="text-sm font-semibold text-slate-900 mb-3">Período</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  <div className="space-y-2">
                    <Label className="text-xs">Data Início</Label>
                    <Input
                      type="date"
                      value={tempFilters.dataInicio}
                      onChange={(e) => handleChange('dataInicio', e.target.value)}
                      className="text-sm"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label className="text-xs">Data Fim</Label>
                    <Input
                      type="date"
                      value={tempFilters.dataFim}
                      onChange={(e) => handleChange('dataFim', e.target.value)}
                      className="text-sm"
                    />
                  </div>
                </div>
                <div className="flex gap-2 mt-2 text-xs">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => {
                      const today = new Date().toISOString().split('T')[0];
                      handleChange('dataInicio', today);
                      handleChange('dataFim', today);
                    }}
                    className="text-blue-600"
                  >
                    Hoje
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => {
                      const today = new Date();
                      const firstDay = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
                      const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0).toISOString().split('T')[0];
                      handleChange('dataInicio', firstDay);
                      handleChange('dataFim', lastDay);
                    }}
                    className="text-blue-600"
                  >
                    Mês Atual
                  </Button>
                </div>
              </div>

              {/* Produto e Status */}
              <div>
                <h4 className="text-sm font-semibold text-slate-900 mb-3">Produto e Status</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  <div className="space-y-2">
                    <Label className="text-xs">Produto</Label>
                    <Select
                      value={tempFilters.letra_produto}
                      onValueChange={(v) => {
                        handleChange('letra_produto', v);
                        handleChange('celula', 'TODOS');
                        handleChange('operador', 'TODOS');
                      }}
                    >
                      <SelectTrigger className="text-sm">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="TODOS">Todos</SelectItem>
                        {opcoesDisponiveis.letras.map(letra => (
                          <SelectItem key={letra} value={letra}>{letra}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label className="text-xs">Status</Label>
                    <Select
                      value={tempFilters.status}
                      onValueChange={(v) => handleChange('status', v)}
                    >
                      <SelectTrigger className="text-sm">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="TODOS">Todos</SelectItem>
                        {statusOptions.map(st => (
                          <SelectItem key={st} value={st}>{st}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>
              </div>

              {/* Cliente, Célula e Operador */}
              <div>
                <h4 className="text-sm font-semibold text-slate-900 mb-3">Recursos</h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                  <div className="space-y-2">
                    <Label className="text-xs">Cliente</Label>
                    <Select
                      value={tempFilters.cliente}
                      onValueChange={(v) => handleChange('cliente', v)}
                    >
                      <SelectTrigger className="text-sm">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="TODOS">Todos ({opcoesDisponiveis.clientes.length})</SelectItem>
                        {opcoesDisponiveis.clientes.map(cli => (
                          <SelectItem key={cli} value={cli}>{cli}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label className="text-xs">Célula</Label>
                    <Select
                      value={tempFilters.celula}
                      onValueChange={(v) => {
                        handleChange('celula', v);
                        handleChange('operador', 'TODOS');
                      }}
                      disabled={opcoesDisponiveis.celulas.length === 0}
                    >
                      <SelectTrigger className="text-sm">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="TODOS">Todas ({opcoesDisponiveis.celulas.length})</SelectItem>
                        {opcoesDisponiveis.celulas.map(cel => (
                          <SelectItem key={cel} value={cel}>{cel}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label className="text-xs">Operador</Label>
                    <Select
                      value={tempFilters.operador}
                      onValueChange={(v) => handleChange('operador', v)}
                      disabled={opcoesDisponiveis.operadores.length === 0}
                    >
                      <SelectTrigger className="text-sm">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="TODOS">Todos ({opcoesDisponiveis.operadores.length})</SelectItem>
                        {opcoesDisponiveis.operadores.map(op => (
                          <SelectItem key={op} value={op}>{op}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>
              </div>

              {/* Ações */}
              <div className="flex gap-2 pt-4 border-t border-blue-200">
                <Button
                  onClick={handleApply}
                  className="flex-1 bg-blue-600 hover:bg-blue-700"
                >
                  Aplicar Filtros
                </Button>
                <Button
                  onClick={handleReset}
                  variant="outline"
                  className="flex-1"
                >
                  Resetar
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { FileText, Trash2, Share2, Lock, MoreVertical } from 'lucide-react';
import { toast } from 'sonner';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export default function TemplatesPDFManager({ onSelecionarTemplate }) {
  const queryClient = useQueryClient();
  const [dialogOpen, setDialogOpen] = useState(false);

  const { data: templates = [] } = useQuery({
    queryKey: ['templates-pdf'],
    queryFn: () => rdsn.entities.TemplatePDF.list('-created_at')
  });

  const deletarMutation = useMutation({
    mutationFn: (id) => rdsn.entities.TemplatePDF.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['templates-pdf'] });
      toast.success('Template excluído!');
    }
  });

  const compartilharMutation = useMutation({
    mutationFn: ({ id, compartilhado }) => 
      rdsn.entities.TemplatePDF.update(id, { compartilhado }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['templates-pdf'] });
      toast.success('Template atualizado!');
    }
  });

  const handleSelecionar = (template) => {
    onSelecionarTemplate(template);
    setDialogOpen(false);
  };

  return (
    <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
      <DialogTrigger asChild>
        <Button variant="outline">
          <FileText className="w-4 h-4 mr-2" />
          Templates ({templates.length})
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-4xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Templates de PDF Salvos</DialogTitle>
        </DialogHeader>

        {templates.length === 0 ? (
          <div className="text-center py-12">
            <FileText className="w-16 h-16 mx-auto mb-4 text-slate-300" />
            <p className="text-slate-600">Nenhum template salvo</p>
            <p className="text-sm text-slate-500 mt-1">
              Configure um PDF e salve como template para reutilização
            </p>
          </div>
        ) : (
          <div className="grid gap-4">
            {templates.map(template => (
              <Card key={template.id} className="hover:shadow-md transition-shadow">
                <CardHeader>
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <CardTitle className="text-lg flex items-center gap-2">
                        {template.nome}
                        {template.compartilhado ? (
                          <Badge variant="outline" className="text-xs">
                            <Share2 className="w-3 h-3 mr-1" />
                            Compartilhado
                          </Badge>
                        ) : (
                          <Badge variant="outline" className="text-xs">
                            <Lock className="w-3 h-3 mr-1" />
                            Privado
                          </Badge>
                        )}
                      </CardTitle>
                      {template.descricao && (
                        <p className="text-sm text-slate-600 mt-1">{template.descricao}</p>
                      )}
                    </div>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon">
                          <MoreVertical className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          onClick={() => compartilharMutation.mutate({ 
                            id: template.id, 
                            compartilhado: !template.compartilhado 
                          })}
                        >
                          {template.compartilhado ? (
                            <>
                              <Lock className="w-4 h-4 mr-2" />
                              Tornar Privado
                            </>
                          ) : (
                            <>
                              <Share2 className="w-4 h-4 mr-2" />
                              Compartilhar
                            </>
                          )}
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => deletarMutation.mutate(template.id)}
                          className="text-red-600"
                        >
                          <Trash2 className="w-4 h-4 mr-2" />
                          Excluir
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="flex flex-wrap gap-2 mb-3">
                    <Badge>{template.tipo_relatorio}</Badge>
                    <Badge variant="outline">{template.orientacao === 'portrait' ? 'Retrato' : 'Paisagem'}</Badge>
                    <Badge variant="outline">{template.colunas_selecionadas?.length || 0} colunas</Badge>
                    {template.incluir_resumo && <Badge variant="outline">Com resumo</Badge>}
                  </div>
                  <Button 
                    onClick={() => handleSelecionar(template)}
                    size="sm"
                    className="w-full bg-slate-900 hover:bg-slate-800"
                  >
                    Usar este Template
                  </Button>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Trash2, BookmarkPlus, Bookmark } from 'lucide-react';
import { toast } from 'sonner';

export default function ReportPresets({ currentFilters, onLoadPreset }) {
  const [presets, setPresets] = useState([]);
  const [presetName, setPresetName] = useState('');
  const [openDialog, setOpenDialog] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('reportPresets');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error('Erro ao carregar presets:', e);
      }
    }
  }, []);

  const savePreset = () => {
    if (!presetName.trim()) {
      toast.error('Nome do preset é obrigatório');
      return;
    }

    const newPreset = {
      id: Date.now(),
      name: presetName,
      filters: { ...currentFilters },
      createdAt: new Date().toLocaleDateString('pt-BR')
    };

    const updated = [...presets, newPreset];
    setPresets(updated);
    localStorage.setItem('reportPresets', JSON.stringify(updated));
    setPresetName('');
    setOpenDialog(false);
    toast.success('Preset salvo com sucesso!');
  };

  const deletePreset = (id) => {
    const updated = presets.filter(p => p.id !== id);
    setPresets(updated);
    localStorage.setItem('reportPresets', JSON.stringify(updated));
    toast.success('Preset removido');
  };

  const loadPreset = (preset) => {
    onLoadPreset(preset.filters);
    toast.success(`Preset "${preset.name}" carregado`);
  };

  return (
    <div className="space-y-4">
      <div className="flex gap-2">
        <Dialog open={openDialog} onOpenChange={setOpenDialog}>
          <DialogTrigger asChild>
            <Button className="bg-blue-600 hover:bg-blue-700">
              <BookmarkPlus className="w-4 h-4 mr-2" />
              Salvar Preset
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Salvar Configuração de Relatório</DialogTitle>
              <DialogDescription>
                Nomeie este preset para reutilizá-lo later
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <Input
                placeholder="Ex: Relatório Mensal - Célula A"
                value={presetName}
                onChange={(e) => setPresetName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && savePreset()}
              />
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => setOpenDialog(false)}>
                  Cancelar
                </Button>
                <Button onClick={savePreset} className="bg-blue-600 hover:bg-blue-700">
                  Salvar
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {presets.length > 0 && (
        <Card className="bg-blue-50 border-blue-200">
          <CardHeader>
            <CardTitle className="text-sm flex items-center gap-2">
              <Bookmark className="w-4 h-4" />
              Presets Salvos
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {presets.map(preset => (
                <div
                  key={preset.id}
                  className="flex items-center justify-between p-3 bg-white rounded-lg border border-blue-100 hover:border-blue-300 transition-all"
                >
                  <div className="min-w-0 flex-1">
                    <p className="font-medium text-slate-900 truncate">{preset.name}</p>
                    <p className="text-xs text-slate-500">{preset.createdAt}</p>
                  </div>
                  <div className="flex gap-1 ml-2">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => loadPreset(preset)}
                      className="px-2"
                    >
                      Carregar
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => deletePreset(preset.id)}
                      className="text-red-600 hover:text-red-700 hover:bg-red-50 px-2"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import React from 'react';
import { Printer } from 'lucide-react';
import { Button } from '@/components/ui/button';

/**
 * Abre uma janela de impressão com o conteúdo HTML fornecido, incluindo estilos básicos.
 * @param {string} titulo - Título do relatório
 * @param {string} subtitulo - Subtítulo/filtros ativos
 * @param {string} htmlTabela - HTML da tabela/conteúdo a imprimir
 */
export function imprimirRelatorio({ titulo, subtitulo, htmlTabela }) {
  const janela = window.open('', '_blank', 'width=900,height=700');
  janela.document.write(`
    <!DOCTYPE html>
    <html lang="pt-BR">
    <head>
      <meta charset="UTF-8" />
      <title>${titulo}</title>
      <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: Arial, sans-serif; font-size: 12px; color: #111; padding: 24px; }
        h1 { font-size: 18px; margin-bottom: 4px; }
        .subtitulo { font-size: 11px; color: #555; margin-bottom: 16px; }
        table { width: 100%; border-collapse: collapse; margin-top: 8px; }
        th { background: #1e293b; color: #fff; padding: 7px 10px; text-align: left; font-size: 11px; }
        td { padding: 6px 10px; border-bottom: 1px solid #e2e8f0; font-size: 11px; }
        tr:nth-child(even) td { background: #f8fafc; }
        .footer { margin-top: 20px; font-size: 10px; color: #888; text-align: right; }
        @media print {
          body { padding: 12px; }
          button { display: none; }
        }
      </style>
    </head>
    <body>
      <h1>${titulo}</h1>
      <div class="subtitulo">${subtitulo || ''}</div>
      ${htmlTabela}
      <div class="footer">Impresso em ${new Date().toLocaleString('pt-BR')}</div>
      <script>window.onload = () => { window.print(); }</script>
    </body>
    </html>
  `);
  janela.document.close();
}

/**
 * Botão padrão de imprimir com callback onClick.
 */
export default function BotaoImprimir({ onClick, label = 'Imprimir', size = 'sm', variant = 'outline', className = '' }) {
  return (
    <Button size={size} variant={variant} onClick={onClick} className={`gap-1.5 ${className}`}>
      <Printer className="w-3.5 h-3.5" />
      {label}
    </Button>
  );
}

import React, { useState, useMemo } from 'react';
import { rdsn } from '@/api/supabaseClient';
import { useQuery } from '@tanstack/react-query';
import { useSetor } from '@/components/context/SetorContext';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { BarChart3, LineChart as LineIcon, PieChart as PieIcon, Plus } from 'lucide-react';
import ExportarRelatorio from './ExportarRelatorio';

const CORES = ['#0ea5e9', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981', '#6366f1', '#ef4444', '#14b8a6'];

export default function RelatorioCustomizavel() {
  const { setorAtivo, isAdmin } = useSetor();
  const [entidadeSelecionada, setEntidadeSelecionada] = useState('ReservaLote');
  const [camposSelecionados, setCamposSelecionados] = useState([]);
  const [filtros, setFiltros] = useState([]);
  const [agrupamento, setAgrupamento] = useState('');
  const [tipoGrafico, setTipoGrafico] = useState('barra');
  const [campoGraficoX, setCampoGraficoX] = useState('');
  const [campoGraficoY, setCampoGraficoY] = useState('');

  const entidadesDisponiveis = {
    ReservaLote: {
      label: 'Reservas',
      campos: [
        { key: 'codigo_completo', label: 'Código', tipo: 'texto' },
        { key: 'cliente', label: 'Cliente', tipo: 'texto' },
        { key: 'codigo_produto', label: 'Cód. Produto', tipo: 'texto' },
        { key: 'modelo', label: 'Modelo', tipo: 'texto' },
        { key: 'quantidade', label: 'Quantidade', tipo: 'numero' },
        { key: 'quantidade_baixada', label: 'Qtd Baixada', tipo: 'numero' },
        { key: 'status', label: 'Status', tipo: 'texto' },
        { key: 'created_at', label: 'Data Criação', tipo: 'data' }
      ]
    },
    BaixaLote: {
      label: 'Baixas',
      campos: [
        { key: 'tipo', label: 'Tipo', tipo: 'texto' },
        { key: 'quantidade', label: 'Quantidade', tipo: 'numero' },
        { key: 'de_setor', label: 'De Setor', tipo: 'texto' },
        { key: 'para_setor', label: 'Para Setor', tipo: 'texto' },
        { key: 'operador', label: 'Operador', tipo: 'texto' },
        { key: 'created_at', label: 'Data', tipo: 'data' }
      ]
    },
    Produto: {
      label: 'Produtos',
      campos: [
        { key: 'letra_produto', label: 'Letra', tipo: 'texto' },
        { key: 'modelo', label: 'Modelo', tipo: 'texto' },
        { key: 'descricao', label: 'Descrição', tipo: 'texto' },
        { key: 'estoque_atual', label: 'Estoque', tipo: 'numero' },
        { key: 'estoque_minimo', label: 'Estoque Mín', tipo: 'numero' }
      ]
    }
  };

  const { data: dados = [], isLoading } = useQuery({
    queryKey: ['relatorio-dados', entidadeSelecionada, setorAtivo],
    queryFn: async () => {
      const todas = await rdsn.entities[entidadeSelecionada].list();

      // Filtrar por setor
      if (isAdmin && setorAtivo === 'TODOS') return todas;

      if (entidadeSelecionada === 'Produto') {
        return todas.filter(item => item.setor_id === setorAtivo);
      } else if (entidadeSelecionada === 'ReservaLote') {
        return todas.filter(item => item.setor_id === setorAtivo);
      } else if (entidadeSelecionada === 'BaixaLote') {
        // Para baixas, precisamos filtrar pelas reservas do setor
        const reservasDoSetor = await rdsn.entities.ReservaLote.filter({ setor_id: setorAtivo });
        const reservaIds = reservasDoSetor.map(r => r.id);
        return todas.filter(item => reservaIds.includes(item.reserva_id));
      }

      return todas;
    },
    enabled: !!setorAtivo
  });

  const dadosFiltrados = useMemo(() => {
    let resultado = [...dados];

    filtros.forEach(filtro => {
      if (filtro.campo && filtro.valor) {
        resultado = resultado.filter(item => {
          const valor = item[filtro.campo];
          if (filtro.operador === 'contem') {
            return String(valor).toLowerCase().includes(filtro.valor.toLowerCase());
          } else if (filtro.operador === 'igual') {
            return String(valor) === filtro.valor;
          } else if (filtro.operador === 'maior') {
            return Number(valor) > Number(filtro.valor);
          } else if (filtro.operador === 'menor') {
            return Number(valor) < Number(filtro.valor);
          }
          return true;
        });
      }
    });

    return resultado;
  }, [dados, filtros]);

  const dadosAgrupados = useMemo(() => {
    if (!agrupamento || !campoGraficoY) return [];

    const grupos = {};
    dadosFiltrados.forEach(item => {
      const chave = item[agrupamento] || 'Sem categoria';
      if (!grupos[chave]) {
        grupos[chave] = { nome: chave, valor: 0, count: 0 };
      }
      grupos[chave].valor += Number(item[campoGraficoY]) || 0;
      grupos[chave].count += 1;
    });

    return Object.values(grupos);
  }, [dadosFiltrados, agrupamento, campoGraficoY]);

  const colunasExportacao = useMemo(() => {
    const camposConfig = entidadesDisponiveis[entidadeSelecionada].campos;
    const camposExportar = camposSelecionados.length > 0 
      ? camposConfig.filter(c => camposSelecionados.includes(c.key))
      : camposConfig;
    return camposExportar.map(c => ({
      key: c.key,
      label: c.label,
      width: 16,
      tipo: c.tipo === 'numero' ? 'numero' : undefined
    }));
  }, [entidadeSelecionada, camposSelecionados]);

  const resumoExportacao = useMemo(() => {
    const r = { 'Total de Registros': dadosFiltrados.length };
    if (campoGraficoY) {
      const soma = dadosFiltrados.reduce((acc, item) => acc + (Number(item[campoGraficoY]) || 0), 0);
      r[`Total ${campoGraficoY}`] = soma;
    }
    return r;
  }, [dadosFiltrados, campoGraficoY]);

  const adicionarFiltro = () => {
    setFiltros([...filtros, { campo: '', operador: 'contem', valor: '' }]);
  };

  const renderGrafico = () => {
    if (!agrupamento || dadosAgrupados.length === 0) return null;

    const componentes = {
      barra: (
        <BarChart data={dadosAgrupados}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="nome" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Bar dataKey="valor" fill="#0ea5e9" />
        </BarChart>
      ),
      linha: (
        <LineChart data={dadosAgrupados}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="nome" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Line type="monotone" dataKey="valor" stroke="#8b5cf6" strokeWidth={2} />
        </LineChart>
      ),
      pizza: (
        <PieChart>
          <Pie
            data={dadosAgrupados}
            dataKey="valor"
            nameKey="nome"
            cx="50%"
            cy="50%"
            outerRadius={100}
            label
          >
            {dadosAgrupados.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={CORES[index % CORES.length]} />
            ))}
          </Pie>
          <Tooltip />
          <Legend />
        </PieChart>
      )
    };

    return (
      <Card className="border-slate-200 mt-6">
        <CardHeader>
          <CardTitle className="text-base">Visualização Gráfica</CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={300}>
            {componentes[tipoGrafico]}
          </ResponsiveContainer>
        </CardContent>
      </Card>
    );
  };

  return (
    <div className="space-y-6">
      {/* Configuração */}
      <Card className="border-slate-200">
        <CardHeader>
          <CardTitle>Configurar Relatório</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Seleção de Entidade */}
          <div className="space-y-2">
            <Label>Fonte de Dados</Label>
            <Select value={entidadeSelecionada} onValueChange={setEntidadeSelecionada}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(entidadesDisponiveis).map(([key, config]) => (
                  <SelectItem key={key} value={key}>{config.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Seleção de Campos */}
          <div className="space-y-2">
            <Label>Campos para Exibir</Label>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-2 p-4 bg-slate-50 rounded-lg">
              {entidadesDisponiveis[entidadeSelecionada].campos.map(campo => (
                <div key={campo.key} className="flex items-center space-x-2">
                  <Checkbox
                    checked={camposSelecionados.includes(campo.key)}
                    onCheckedChange={(checked) => {
                      if (checked) {
                        setCamposSelecionados([...camposSelecionados, campo.key]);
                      } else {
                        setCamposSelecionados(camposSelecionados.filter(c => c !== campo.key));
                      }
                    }}
                  />
                  <label className="text-sm">{campo.label}</label>
                </div>
              ))}
            </div>
          </div>

          {/* Filtros */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label>Filtros Dinâmicos</Label>
              <Button size="sm" variant="outline" onClick={adicionarFiltro}>
                <Plus className="w-3 h-3 mr-1" />
                Adicionar Filtro
              </Button>
            </div>
            {filtros.map((filtro, idx) => (
              <div key={idx} className="grid grid-cols-3 gap-2 p-2 bg-slate-50 rounded">
                <Select
                  value={filtro.campo}
                  onValueChange={(v) => {
                    const novos = [...filtros];
                    novos[idx].campo = v;
                    setFiltros(novos);
                  }}
                >
                  <SelectTrigger className="text-xs">
                    <SelectValue placeholder="Campo" />
                  </SelectTrigger>
                  <SelectContent>
                    {entidadesDisponiveis[entidadeSelecionada].campos.map(c => (
                      <SelectItem key={c.key} value={c.key}>{c.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Select
                  value={filtro.operador}
                  onValueChange={(v) => {
                    const novos = [...filtros];
                    novos[idx].operador = v;
                    setFiltros(novos);
                  }}
                >
                  <SelectTrigger className="text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="contem">Contém</SelectItem>
                    <SelectItem value="igual">Igual a</SelectItem>
                    <SelectItem value="maior">Maior que</SelectItem>
                    <SelectItem value="menor">Menor que</SelectItem>
                  </SelectContent>
                </Select>
                <Input
                  placeholder="Valor"
                  value={filtro.valor}
                  onChange={(e) => {
                    const novos = [...filtros];
                    novos[idx].valor = e.target.value;
                    setFiltros(novos);
                  }}
                  className="text-xs"
                />
              </div>
            ))}
          </div>

          {/* Gráficos */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label>Agrupamento</Label>
              <Select value={agrupamento} onValueChange={setAgrupamento}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value={null}>Nenhum</SelectItem>
                  {entidadesDisponiveis[entidadeSelecionada].campos
                    .filter(c => c.tipo === 'texto')
                    .map(c => (
                      <SelectItem key={c.key} value={c.key}>{c.label}</SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Campo Numérico</Label>
              <Select value={campoGraficoY} onValueChange={setCampoGraficoY}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione" />
                </SelectTrigger>
                <SelectContent>
                  {entidadesDisponiveis[entidadeSelecionada].campos
                    .filter(c => c.tipo === 'numero')
                    .map(c => (
                      <SelectItem key={c.key} value={c.key}>{c.label}</SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Tipo de Gráfico</Label>
              <div className="flex gap-2">
                <Button
                  size="sm"
                  variant={tipoGrafico === 'barra' ? 'default' : 'outline'}
                  onClick={() => setTipoGrafico('barra')}
                  className="flex-1"
                >
                  <BarChart3 className="w-4 h-4" />
                </Button>
                <Button
                  size="sm"
                  variant={tipoGrafico === 'linha' ? 'default' : 'outline'}
                  onClick={() => setTipoGrafico('linha')}
                  className="flex-1"
                >
                  <LineIcon className="w-4 h-4" />
                </Button>
                <Button
                  size="sm"
                  variant={tipoGrafico === 'pizza' ? 'default' : 'outline'}
                  onClick={() => setTipoGrafico('pizza')}
                  className="flex-1"
                >
                  <PieIcon className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </div>


          {/* Ações de Exportação */}
          <div className="flex gap-3 pt-4 border-t border-slate-200">
            <ExportarRelatorio
              dados={dadosFiltrados}
              colunas={colunasExportacao}
              titulo={`Relatorio de ${entidadesDisponiveis[entidadeSelecionada].label}`}
              resumo={resumoExportacao}
              filtrosAplicados={{ 'Fonte': entidadesDisponiveis[entidadeSelecionada].label }}
            />
          </div>

        </CardContent>
      </Card>

      {/* Gráfico */}
      {renderGrafico()}

      {/* Tabela de Dados */}
      <Card className="border-slate-200">
        <CardHeader>
          <CardTitle className="text-base flex items-center justify-between">
            <span>Dados ({dadosFiltrados.length} registros)</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="text-center py-8">Carregando...</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-slate-200">
                    {entidadesDisponiveis[entidadeSelecionada].campos
                      .filter(c => camposSelecionados.length === 0 || camposSelecionados.includes(c.key))
                      .map(campo => (
                        <th key={campo.key} className="text-left p-2 font-semibold text-slate-700">
                          {campo.label}
                        </th>
                      ))}
                  </tr>
                </thead>
                <tbody>
                  {dadosFiltrados.slice(0, 50).map((row, idx) => (
                    <tr key={idx} className="border-b border-slate-100 hover:bg-slate-50">
                      {entidadesDisponiveis[entidadeSelecionada].campos
                        .filter(c => camposSelecionados.length === 0 || camposSelecionados.includes(c.key))
                        .map(campo => (
                          <td key={campo.key} className="p-2">
                            {row[campo.key] || '-'}
                          </td>
                        ))}
                    </tr>
                  ))}
                </tbody>
              </table>
              {dadosFiltrados.length > 50 && (
                <p className="text-xs text-slate-500 mt-2 text-center">
                  Exibindo 50 de {dadosFiltrados.length} registros. Exporte para ver todos.
                </p>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { Camera, X, Zap, CheckCircle2, AlertCircle, Loader2, ScanLine } from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";

export default function BarcodeScanner({ onScan, onClose, placeholder = "Aponte a câmera para o código" }) {
  const [scanning, setScanning] = useState(false);
  const [status, setStatus] = useState('idle'); // idle, scanning, success, error
  const [lastCode, setLastCode] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const scannerRef = useRef(null);
  const html5QrCodeRef = useRef(null);
  const audioContextRef = useRef(null);

  // Criar contexto de áudio
  useEffect(() => {
    audioContextRef.current = new (window.AudioContext || window['webkitAudioContext'])();
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, []);

  // Tocar som de sucesso
  const playSuccessSound = () => {
    if (!audioContextRef.current) return;

    const ctx = audioContextRef.current;
    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    oscillator.frequency.setValueAtTime(800, ctx.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1);

    gainNode.gain.setValueAtTime(0.3, ctx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15);

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.15);

    // Vibração
    if (navigator.vibrate) {
      navigator.vibrate([50, 30, 50]);
    }
  };

  // Tocar som de erro
  const playErrorSound = () => {
    if (!audioContextRef.current) return;

    const ctx = audioContextRef.current;
    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    oscillator.frequency.setValueAtTime(400, ctx.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.2);

    gainNode.gain.setValueAtTime(0.3, ctx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.25);

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.25);

    // Vibração
    if (navigator.vibrate) {
      navigator.vibrate([100, 50, 100]);
    }
  };

  // Tocar som de scan
  const playScanSound = () => {
    if (!audioContextRef.current) return;

    const ctx = audioContextRef.current;
    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    oscillator.frequency.value = 600;
    gainNode.gain.setValueAtTime(0.2, ctx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.05);

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.05);
  };

  const startScanning = async () => {
    try {
      setScanning(true);
      setStatus('scanning');
      setErrorMsg('');

      html5QrCodeRef.current = new Html5Qrcode("barcode-scanner");

      const config = { 
        fps: 10,
        qrbox: { width: 300, height: 150 },
        aspectRatio: 1.777778
      };

      await html5QrCodeRef.current.start(
        { facingMode: "environment" },
        config,
        (decodedText) => {
          playScanSound();
          setLastCode(decodedText);
          setStatus('success');
          playSuccessSound();

          // Chamar callback após pequeno delay para mostrar feedback
          setTimeout(() => {
            onScan(decodedText);
            stopScanning();
          }, 800);
        },
        (errorMessage) => {
          // Ignorar erros de scan contínuo
        }
      );
    } catch (error) {
      console.error('Erro ao iniciar scanner:', error);
      setStatus('error');
      setErrorMsg(error.message || 'Não foi possível acessar a câmera');
      playErrorSound();
      setScanning(false);
    }
  };

  const stopScanning = async () => {
    try {
      if (html5QrCodeRef.current) {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current.clear();
        html5QrCodeRef.current = null;
      }
    } catch (error) {
      console.error('Erro ao parar scanner:', error);
    }
    setScanning(false);
    setStatus('idle');
  };

  useEffect(() => {
    return () => {
      stopScanning();
    };
  }, []);

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.95 }}
      className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4"
    >
      <Card className="w-full max-w-2xl bg-white shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-900 to-slate-800 text-white p-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
