  eApos
} from '../core/numeracaoService.js';

export async function alocarNumerosAutomatico(payload) {
  try {
    const { letra_produto, ano, quantidade, setor_id, criterio } = payload;

    if (!letra_produto || !ano || !quantidade || !setor_id) {
      return { data: { error: 'Parâmetros obrigatórios: letra_produto, ano, quantidade, setor_id' }, status: 400 };
    }

    // Buscar sequência atual
    let sequencias = [];
    try {
      const todas = await rdsn.asServiceRole.entities.SequenciaAnual.list();
      sequencias = todas.filter(s =>
        String(s.letra_produto) === String(letra_produto) &&
        String(s.ano) === String(ano) &&
        String(s.setor_id) === String(setor_id)
      );
    } catch (err) {
      console.log('Erro ao buscar sequências', err);
    }

    let sequencia;
    if (sequencias.length === 0) {
      try {
        sequencia = await rdsn.asServiceRole.entities.SequenciaAnual.create({
          letra_produto,
          ano,
          setor_id,
          ultimo_numero: 0,
          encerrado: false
        });
      } catch (err) {
        return { data: { error: 'Erro ao criar sequência: ' + err.message }, status: 500 };
      }
    } else {
      sequencia = sequencias[0];
    }

    if (sequencia.encerrado) {
      return { data: { error: 'Ano encerrado. Não é possível criar novas reservas' }, status: 400 };
    }

    const todasReservas = await rdsn.asServiceRole.entities.ReservaLote.filter({
      letra_produto,
      ano,
      setor_id
    });

    const reservas = todasReservas.filter(r =>
      ['RESERVADO', 'EM_PRODUCAO', 'BAIXADO', 'PRODUZIDO'].includes(r.status)
    );

    let numeracoesLivres = [];
    try {
      const todasNumLivres = await rdsn.asServiceRole.entities.NumeracaoLivre.list();
      numeracoesLivres = todasNumLivres.filter(n =>
        String(n.letra_produto) === String(letra_produto) &&
        String(n.ano) === String(ano) &&
        String(n.setor_id) === String(setor_id) &&
        n.disponivel === true
      );
    } catch (err) {
      console.log('NumeracaoLivre não possui registros ou erro ao buscar');
    }

    const agora = new Date().toISOString();
    let bloqueiosAtivos = [];
    try {
      const todosBloqueios = await rdsn.asServiceRole.entities.BloqueioIntervalo.list();
      bloqueiosAtivos = todosBloqueios.filter(b =>
        String(b.letra_produto) === String(letra_produto) &&
        String(b.ano) === String(ano) &&
        String(b.setor_id) === String(setor_id) &&
        (!b.expira_em || new Date(b.expira_em) > new Date(agora))
      );
    } catch (err) {
      console.log('BloqueioIntervalo não possui registros ou erro ao buscar');
    }

    const intervalosOcupados = reservas.map(r => ({
      inicio: r.numero_inicial,
      fim: r.numero_final
    }));

    const intervalosLivresExistentes = numeracoesLivres.map(n => ({
      inicio: n.numero_inicial,
      fim: n.numero_final,
      quantidade: n.quantidade,
      isLivre: true
    }));

    const verificarIntervaloLivre = (inicio, fim) => {
      for (const ocupado of intervalosOcupados) {
        if (checarSobreposicao(inicio, fim, ocupado.inicio, ocupado.fim)) {
          return false;
        }
      }
      for (const bloqueio of bloqueiosAtivos) {
        if (checarSobreposicao(inicio, fim, bloqueio.numero_inicial, bloqueio.numero_final)) {
          return false;
        }
      }
      return true;
    };

    const calcularProximidadeReservas = (inicio, fim) => {
      const proximaReserva = reservas
        .map(r => r.numero_inicial)
        .filter(n => n > fim)
        .sort((a, b) => a - b)[0];

      return proximaReserva ? calcularQuantidade(proximo(fim), anteriorNumero(proximaReserva)) : Infinity;
    };

    const calcularScoreQualidade = (intervalo) => {
      let score = 0;
      if (intervalo.origem === 'numeracao_livre') score += 100;
      if (intervalo.origem === 'numeracao_livre_combinada') score += 90;
      if (intervalo.origem === 'numeracao_livre_parcial') score += 60;
      if (intervalo.origem === 'sequencia_nova') score += 40;

      if (intervalo.origem !== 'numeracao_livre_parcial' && intervalo.quantidadeDisponivel > intervalo.quantidade) {
        const desperdicio = intervalo.quantidadeDisponivel - intervalo.quantidade;
        score -= Math.min(20, desperdicio / 100);
      }

      const proximidade = calcularProximidadeReservas(intervalo.inicio, intervalo.fim);
      if (proximidade > 100 && proximidade < 1000) {
        score += 15;
      } else if (proximidade < 100 && proximidade > 0) {
        score -= 10;
      }

      return score;
    };

    const intervalosDisponiveis = [];

    for (const livre of intervalosLivresExistentes) {
      if (livre.quantidade >= quantidade && verificarIntervaloLivre(livre.inicio, livre.fim)) {
        const intervalo = {
          inicio: livre.inicio,
          fim: calcularFim(livre.inicio, quantidade),
          quantidade: quantidade,
          origem: 'numeracao_livre',
          quantidadeDisponivel: livre.quantidade,
          motivo: 'Reutiliza espaço liberado anteriormente'
        };
        intervalo.score = calcularScoreQualidade(intervalo);
        intervalosDisponiveis.push(intervalo);
      }
      else if (livre.quantidade > 0 && livre.quantidade < quantidade) {
        const inicioLivre = livre.inicio;
        const fimLivre = livre.fim;
        const quantidadeLivre = livre.quantidade;
        const quantidadeFaltante = quantidade - quantidadeLivre;
        const fimTotal = calcularFim(inicioLivre, quantidade);

        if (verificarIntervaloLivre(inicioLivre, fimTotal)) {
          const intervalo = {
            inicio: inicioLivre,
            fim: fimTotal,
            quantidade: quantidade,
            origem: 'numeracao_livre_combinada',
            quantidadeDisponivel: quantidade,
            quantidadeLivre: quantidadeLivre,
            quantidadeSequencial: quantidadeFaltante,
            motivo: `Combina ${quantidadeLivre} números livres (${inicioLivre}-${fimLivre}) + ${quantidadeFaltante} sequenciais (${proximo(fimLivre)}-${fimTotal})`
          };
          intervalo.score = calcularScoreQualidade(intervalo);
          intervalosDisponiveis.push(intervalo);
        }
      }
    }

    const todosNumeros = [...intervalosOcupados].sort((a, b) => a.inicio - b.inicio);

    if (todosNumeros.length > 0) {
      const primeiraReserva = todosNumeros[0];
      const espacoInicial = primeiraReserva.inicio - 1;

      if (espacoInicial >= quantidade) {
        const intervalo = {
          inicio: 1,
          fim: quantidade,
          quantidade: quantidade,
          origem: 'inicio_sequencia',
          quantidadeDisponivel: espacoInicial,
          motivo: `Usa espaço disponível no início (1 a ${espacoInicial})`
        };
        intervalo.score = calcularScoreQualidade(intervalo) + 50;
        intervalosDisponiveis.push(intervalo);
      }
    }

    for (let i = 0; i < todosNumeros.length - 1; i++) {
      const fimAtual = todosNumeros[i].fim;
      const inicioProximo = todosNumeros[i + 1].inicio;
      const gap = calcularQuantidade(proximo(fimAtual), anteriorNumero(inicioProximo));

      if (gap >= quantidade) {
        const inicioGap = proximo(fimAtual);
        const intervalo = {
          inicio: inicioGap,
          fim: calcularFim(inicioGap, quantidade),
          quantidade: quantidade,
          origem: 'gap_entre_reservas',
          quantidadeDisponivel: gap,
          motivo: `Preenche lacuna de ${gap} números entre reservas`
        };
        intervalo.score = calcularScoreQualidade(intervalo);
        intervalosDisponiveis.push(intervalo);
      }
    }

    // Próximo número = fim da ÚLTIMA RESERVA CONFIRMADA + 1
    // Ignora ultimo_numero (pode estar contaminado por simulações antigas)
    // A fonte da verdade é sempre o banco de dados de reservas confirmadas.
    const maxOcupado = reservas.reduce((max, r) => {
      const nf = Number(r.numero_final) || 0;
      if (max === 0) return nf;
      return eApos(nf, max) ? nf : max;
    }, 0);
    const proximoNumeroDisp = proximo(maxOcupado);

    if (verificarIntervaloLivre(proximoNumeroDisp, calcularFim(proximoNumeroDisp, quantidade))) {
      const intervalo = {
        inicio: proximoNumeroDisp,
        fim: calcularFim(proximoNumeroDisp, quantidade),
        quantidade: quantidade,
        origem: 'sequencia_nova',
        quantidadeDisponivel: quantidade,
        motivo: `Continuação sequencial: ${proximoNumeroDisp.toLocaleString()} – ${calcularFim(proximoNumeroDisp, quantidade).toLocaleString()}`
      };
      intervalo.score = calcularScoreQualidade(intervalo);
      intervalosDisponiveis.push(intervalo);
    }

    if (intervalosDisponiveis.length === 0) {
      return {
        data: {
          error: 'Não há intervalos disponíveis para a quantidade solicitada',
          sugestao: 'Considere reduzir a quantidade ou usar numeração manual'
        }, status: 400
      };
    }

    let intervaloSelecionado;
    const alternativasOrdenadas = [...intervalosDisponiveis].sort((a, b) => b.score - a.score);

    if (criterio === 'menor_intervalo') {
      intervaloSelecionado = alternativasOrdenadas
        .filter(i => i.origem === 'numeracao_livre')[0]
        || alternativasOrdenadas[0];
    } else if (criterio === 'maior_contiguo') {
      intervaloSelecionado = alternativasOrdenadas
        .sort((a, b) => b.quantidadeDisponivel - a.quantidadeDisponivel)[0];
    } else if (criterio === 'sequencial') {
      intervaloSelecionado = intervalosDisponiveis
        .find(i => i.origem === 'sequencia_nova' && i.quantidade === quantidade);

      if (!intervaloSelecionado) {
        intervaloSelecionado = intervalosDisponiveis
          .find(i => i.origem === 'sequencia_nova')
          || alternativasOrdenadas[0];
      }
    } else {
      const numLivreCompleta = alternativasOrdenadas.find(i => i.origem === 'numeracao_livre');
      const numLivreParcial = alternativasOrdenadas.find(i => i.origem === 'numeracao_livre_parcial');

      if (numLivreCompleta) {
        intervaloSelecionado = numLivreCompleta;
      } else if (numLivreParcial && numLivreParcial.score > 20) {
        intervaloSelecionado = numLivreParcial;
      } else {
        intervaloSelecionado = alternativasOrdenadas[0];
      }
    }

    const topAlternativas = alternativasOrdenadas.slice(0, 3).map(alt => ({
      numero_inicial: alt.inicio,
      numero_final: alt.fim,
      origem: alt.origem,
      motivo: alt.motivo,
      score: Math.round(alt.score),
      quantidadeDisponivel: alt.quantidadeDisponivel
    }));

    // NOTA: ultimo_numero NÃO é atualizado aqui.
    // Esta função é read-only — apenas sugere um intervalo.
    // O ultimo_numero deve ser atualizado somente quando a reserva for
    // efetivamente confirmada (salva no banco via ReservaLote.create).
    // A sequência correta sempre é derivada de maxOcupado (reservas confirmadas).

    return {
      data: {
        success: true,
        intervalo: {
          numero_inicial: intervaloSelecionado.inicio,
          numero_final: intervaloSelecionado.fim,
          quantidade: quantidade,
          origem: intervaloSelecionado.origem,
          criterio_aplicado: criterio || 'inteligente',
          motivo: intervaloSelecionado.motivo,
          score: Math.round(intervaloSelecionado.score)
        },
        alternativas: topAlternativas,
        totalAlternativas: intervalosDisponiveis.length,
        mensagem: `Intervalo alocado (score ${Math.round(intervaloSelecionado.score)}): ${intervaloSelecionado.inicio.toLocaleString()} - ${intervaloSelecionado.fim.toLocaleString()}`
      }
    };

  } catch (error) {
    console.error('Erro ao alocar números:', error);
    return { data: { error: error.message || 'Erro ao alocar números automaticamente' }, status: 500 };
  }
}

import { rdsn } from './supabaseClient.js';
import { checarSobreposicao } from '../core/numeracaoService.js';

export async function validarIntervalosNumeracao(payload) {
  try {
    const { letra_produto, ano, numero_inicial, numero_final, reserva_id_ignorar, setor_id } = payload;

    // Buscar todas as reservas ativas para esta letra, ano E setor
    // Excluir também reservas LIBERADAS pois elas já foram liberadas para reutilização
    const todasReservas = await rdsn.asServiceRole.entities.ReservaLote.filter({
      letra_produto,
      ano,
      setor_id
    });

    // Filtro no client-side para array operators (devido limitação simples de shim)
    const reservas = todasReservas.filter(r =>
      r.status !== 'CANCELADO' && r.status !== 'LIBERADO'
    );

    const conflitos = [];

    // Verificar sobreposição com reservas
    for (const reserva of reservas) {
      if (reserva_id_ignorar && reserva.id === reserva_id_ignorar) continue;

      const sobrepoe = checarSobreposicao(numero_inicial, numero_final, reserva.numero_inicial, reserva.numero_final);

      if (sobrepoe) {
        conflitos.push({
          tipo: 'RESERVA',
          id: reserva.id,
          codigo: reserva.codigo_completo,
          cliente: reserva.cliente,
          intervalo: `${reserva.numero_inicial} - ${reserva.numero_final}`,
          status: reserva.status
        });
      }
    }

    // NOTA: A validação por ultimo_numero foi removida intencionalmente.
    // Reservas CANCELADAS ou LIBERADAS liberam seus intervalos para reutilização.
    // A proteção anti-sobreposição já vem do filtro de reservas ativas acima (linhas 16-18).


    return {
      data: {
        valido: conflitos.length === 0,
        conflitos,
        intervalo_solicitado: `${numero_inicial} - ${numero_final}`
      }
    };

  } catch (error) {
    return { data: { error: error.message }, status: 500 };
  }
}

export async function restaurarBackup(payload, rdsn) {
    console.log('[RESTAURAR SHIM] Iniciando restauração local...', payload);
    try {
        const { arquivo_url, entidades_para_restaurar } = payload;
        const user = await rdsn.auth.me();

        if (user?.role !== 'admin') {
            return { data: { error: 'Não autorizado - apenas admins' }, status: 403 };
        }

        if (!arquivo_url) {
            return { data: { error: 'URL do arquivo é obrigatória' }, status: 400 };
        }

        // Baixar o arquivo (pode ser um blob url local ou url remota)
        const response = await fetch(arquivo_url);
        const backup = await response.json();

        if (!backup.dados) {
            throw new Error('Arquivo de backup inválido');
        }

        const mapeamento = {
            reservas: 'ReservaLote',
            baixas: 'BaixaLote',
            sequencias: 'SequenciaAnual',
            numeracoes: 'NumeracaoLivre',
            bloqueios: 'BloqueioIntervalo',
            movimentacoes: 'MovimentacaoEstoque',
            auditorias: 'Auditoria',
            alertas: 'Alerta',
            notificacoes: 'Notificacao',
            producao_dia: 'ProducaoDia',
            producao_dia_lotes: 'ProducaoDiaLote'
        };

        const transacionais = Object.keys(mapeamento);
        const entidadesAlvo = entidades_para_restaurar || transacionais;

        const resultados = {};
        let totalRestaurado = 0;

        for (const chave of entidadesAlvo) {
            const entidade = mapeamento[chave];
            const dados = backup.dados[chave];

            if (!entidade || !dados || !Array.isArray(dados) || dados.length === 0) {
                continue;
            }

            console.log(`[RESTAURAR SHIM] Restaurando ${entidade}: ${dados.length} registros`);

            const dadosLimpos = dados.map(item => {
                const { id, created_at, created_date, updated_at, updated_date, created_by, ...resto } = item;
                return resto;
            });

            try {
                // Usar o novo bulkCreate que adicionaremos ao supabaseClient
                await rdsn.asServiceRole.entities[entidade].bulkCreate(dadosLimpos);
                resultados[chave] = { restaurados: dadosLimpos.length };
                totalRestaurado += dadosLimpos.length;
            } catch (err) {
                console.error(`[RESTAURAR SHIM] Erro em ${entidade}:`, err.message);
                resultados[chave] = { restaurados: 0, erro: err.message };
            }
        }

        return {
            data: {
                sucesso: true,
                mensagem: `Restauração local concluída: ${totalRestaurado} registros`,
                total_restaurado: totalRestaurado,
                detalhes: resultados
            }
        };

    } catch (error) {
        console.error('[RESTAURAR SHIM] Erro crítico:', error);
        return { data: { error: error.message }, status: 500 };
    }
}

import { rdsn } from './supabaseClient.js';

export async function enviarWebhook(bodyObj) {
  try {
    const { integracao_id, evento, dados, payload } = bodyObj;

    // Buscar configuração da integração
    const integracao = await rdsn.entities.IntegracaoExterna.get(integracao_id);

    if (!integracao || !integracao.ativa) {
      return { data: { error: 'Integração não encontrada ou inativa' }, status: 404 };
    }

    // Verificar se o evento está habilitado
    if (!integracao.eventos_habilitados?.includes(evento)) {
      return {
        data: {
          success: false,
          message: 'Evento não habilitado para esta integração'
        }
      };
    }

    const startTime = Date.now();

    // Preparar headers de autenticação
    const headers = {
      'Content-Type': 'application/json',
    };

    if (integracao.tipo_autenticacao === 'API Key') {
      headers['X-API-Key'] = integracao.chave_api;
    } else if (integracao.tipo_autenticacao === 'Bearer Token') {
      headers['Authorization'] = `Bearer ${integracao.chave_api}`;
    } else if (integracao.tipo_autenticacao === 'Basic Auth') {
      headers['Authorization'] = `Basic ${integracao.chave_api}`;
    }

    // Formatar payload conforme o formato escolhido (usar payload fornecido ou dados)
    let payloadFinal;
    if (payload) {
      // Payload já fornecido (reenvio)
      payloadFinal = payload;
      if (integracao.formato_exportacao === 'XML') {
        headers['Content-Type'] = 'application/xml';
      } else if (integracao.formato_exportacao === 'CSV') {
        headers['Content-Type'] = 'text/csv';
      }
    } else {
      // Criar novo payload
      if (integracao.formato_exportacao === 'JSON') {
        payloadFinal = JSON.stringify({
          evento,
          timestamp: new Date().toISOString(),
          dados
        });
      } else if (integracao.formato_exportacao === 'XML') {
        payloadFinal = `<?xml version="1.0" encoding="UTF-8"?>
<evento>
  <tipo>${evento}</tipo>
  <timestamp>${new Date().toISOString()}</timestamp>
  <dados>${JSON.stringify(dados)}</dados>
</evento>`;
        headers['Content-Type'] = 'application/xml';
      } else {
        const csvData = Object.entries(dados).map(([k, v]) => `${k},${v}`).join('\n');
        payloadFinal = csvData;
        headers['Content-Type'] = 'text/csv';
      }
    }

    // Enviar webhook com retry automático
    let response;
    let tentativa = 0;
    const maxTentativas = 3;
    let fallbackText = '';

    while (tentativa < maxTentativas) {
      try {
        response = await fetch(integracao.url_webhook, {
          method: 'POST',
          headers,
          body: payloadFinal,
          signal: AbortSignal.timeout(30000) // 30s timeout
        });

        if (response.ok) break;

        // Se não foi OK e ainda tem tentativas, aguarda antes de tentar novamente
        if (tentativa < maxTentativas - 1) {
          await new Promise(resolve => setTimeout(resolve, 2000 * (tentativa + 1))); // backoff exponencial
        }
      } catch (error) {
        if (tentativa === maxTentativas - 1) {
          fallbackText = error.message;
        } else {
          await new Promise(resolve => setTimeout(resolve, 2000 * (tentativa + 1)));
        }
      }
      tentativa++;
    }

    const tempoResposta = Date.now() - startTime;
    const isOk = response && response.ok;
    const status = isOk ? 'SUCESSO' : 'FALHA';

    const erroTxt = response ? await response.text() : fallbackText;

    // Registrar log
    await rdsn.asServiceRole.entities.LogIntegracao.create({
      integracao_id,
      evento,
      payload: payloadFinal.substring(0, 5000), // Limitar tamanho
      status,
      codigo_resposta: response ? response.status : 500,
      mensagem_erro: isOk ? null : `Tentativa ${tentativa}/${maxTentativas}: ${erroTxt}`,
      tempo_resposta_ms: tempoResposta
    });

    // Atualizar integração
    if (isOk) {
      await rdsn.asServiceRole.entities.IntegracaoExterna.update(integracao_id, {
        ultima_sincronizacao: new Date().toISOString(),
        erros_consecutivos: 0
      });
    } else {
      await rdsn.asServiceRole.entities.IntegracaoExterna.update(integracao_id, {
        erros_consecutivos: (integracao.erros_consecutivos || 0) + 1
      });
    }

    return {
      data: {
        success: isOk,
        status: response ? response.status : 500,
        tempo_resposta_ms: tempoResposta,
        mensagem: isOk ? 'Webhook enviado com sucesso' : 'Erro ao enviar webhook'
      }
    };

  } catch (error) {
    return {
      data: {
        success: false,
        error: error.message
      }, status: 500
    };
  }
}

export async function redefinirParaCopia(payload, rdsn) {
    console.log('[REDEFINIR SHIM] Iniciando execução local...', payload);
    try {
        const { confirmar_codigo } = payload;

        console.log('[REDEFINIR SHIM] Verificando sessão...');
        const user = await rdsn.auth.me();
        console.log('[REDEFINIR SHIM] Usuário identificado:', user?.email, 'Role:', user?.role);

        if (!user || user.role !== 'admin') {
            console.error('[REDEFINIR SHIM] Acesso negado: Usuário não é admin');
            return { data: { error: 'Não autorizado - apenas admins' }, status: 403 };
        }

        if (confirmar_codigo !== 'REDEFINIR-SISTEMA') {
            return {
                data: {
                    error: 'Código de confirmação inválido. Digite REDEFINIR-SISTEMA para confirmar.',
                    requer_confirmacao: true
                }, status: 400
            };
        }

        console.log('[REDEFINIR SHIM] Iniciando limpeza massiva de dados transacionais...');

        // Entidades transacionais que devem ser limpas
        const entidadesTransacionais = [
            'ReservaLote',
            'BaixaLote',
            'SequenciaAnual',
            'NumeracaoLivre',
            'BloqueioIntervalo',
            'MovimentacaoEstoque',
            'Auditoria',
            'Alerta',
            'Notificacao',
            'ProducaoDia',
            'ProducaoDiaLote',
            'PCPOrdemProducao',
            'PCPProducaoDiaria',
            'PCPSimulacao',
            'BackupHistorico',
            'HistoricoAuditoria',
            'AuditoriaUsuarios',
            'Etiqueta',
            'LogIntegracao'
        ];

        const resultados = {};
        let totalRemovido = 0;

        for (const entidade of entidadesTransacionais) {
            console.log(`[REDEFINIR SHIM] Limpando entidade: ${entidade}...`);
            try {
                // Obter ids para informar no log, mas apagar tudo de uma vez
                const registros = await rdsn.asServiceRole.entities[entidade].list();
                const qtd = registros.length;

                if (qtd > 0) {
                    // Em vez de loop, apagar todos de uma vez (Supabase permite delete condicional)
                    // Mas como o mock asServiceRole.entities não tem deleteAll, 
                    // vamos fazer em pedaços de 50 para não estourar mas ser rápido
                    const ids = registros.map(r => r.id);
                    const chunkSize = 50;
                    for (let i = 0; i < ids.length; i += chunkSize) {
                        const chunk = ids.slice(i, i + chunkSize);
                        for (const id of chunk) {
                            await rdsn.asServiceRole.entities[entidade].delete(id);
                        }
                        console.log(`[REDEFINIR SHIM] ${entidade}: Limpando... ${i + chunk.length}/${qtd}`);
                    }

                    resultados[entidade] = { removidos: qtd };
                    totalRemovido += qtd;
                    console.log(`[REDEFINIR SHIM] ${entidade}: OK! ${qtd} registros removidos`);
                } else {
                    resultados[entidade] = { removidos: 0 };
                }
            } catch (err) {
                console.error(`[REDEFINIR SHIM] Erro ao limpar ${entidade}:`, err.message);
                resultados[entidade] = { removidos: 0, erro: err.message };
            }
        }

        console.log(`[REDEFINIR SHIM] Concluído com Sucesso! Total removido: ${totalRemovido}`);

        return {
            data: {
                success: true,
                mensagem: `Sistema redefinido localmente: ${totalRemovido} registros removidos.`,
                total_removido: totalRemovido,
                detalhes: resultados
            }
        };

    } catch (error) {
        console.error('[REDEFINIR SHIM] Erro crítico catastrófico:', error);
        return { data: { error: error.message || 'Erro interno no simulador' }, status: 500 };
    }
}

