            // Tenta Supabase Nativo
            const { data: { user } } = await supabase.auth.getUser();

            if (user) {
                console.log('[AUTH] Sessão Supabase ok, buscando perfil estendido:', user.id);
                const { data: profile } = await supabase.from('usuarios').select('*').eq('id', user.id).single();
                console.log('[AUTH] Perfil carregado:', profile?.id);
                const finalUser = { ...user, ...(profile || {}) };
                // Normaliza role para o Shim
                if (finalUser.role_custom) finalUser.role = finalUser.role_custom.toLowerCase();
                return finalUser;
            }

            // Fallback para SessionManager (Local)
            console.log('[AUTH] Nenhuma sessão ativa no Supabase, tentando SessionManager...');
            try {
                const sessionUser = SessionManager.getUser();
                if (sessionUser) {
                    console.log('[AUTH] Sessão local encontrada:', sessionUser.username);
                    // Normaliza para o Shim (espera 'role' em minúsculo)
                    return {
                        ...sessionUser,
                        role: sessionUser.role_custom?.toLowerCase() || 'user'
                    };
                }
            } catch (e) {
                console.error('[AUTH] Erro ao ler sessão local:', e);
            }

            console.log('[AUTH] Nenhuma sessão ativa encontrada');
            return null;
        },
        logout: async () => {
            return await supabase.auth.signOut();
        }
    },
    functions: {
        invoke: async (functionName, payloadOrOptions = {}) => {
            let body = payloadOrOptions;
            if (payloadOrOptions && payloadOrOptions.body) {
                body = payloadOrOptions.body;
            }

            // SIMULADOR LOCAL PARA EDGE FUNCTIONS COMPLEXAS SEM DOCKER/CLI
            // Se a função estiver na lista de mocks offline (criados devido ao problema de deploy)
            // ele rodará localmente consumindo a mesma API nativa
            try {
                if (functionName === 'alocarNumerosAutomatico') {
                    const module = await import('./alocarNumerosAutomatico.js');
                    return await module.alocarNumerosAutomatico(body);
                }

                if (functionName === 'sincronizarBaixasComPCP') {
                    const module = await import('./sincronizarBaixasComPCP.js');
                    return await module.sincronizarBaixasComPCP(body);
                }

                if (functionName === 'registrarEtiqueta') {
                    const module = await import('./registrarEtiqueta.js');
                    return await module.registrarEtiqueta(body);
                }

                if (functionName === 'enviarWebhook') {
                    const module = await import('./enviarWebhook.js');
                    return await module.enviarWebhook(body);
                }

                if (functionName === 'validarIntervalosNumeracao') {
                    const module = await import('./validarIntervalosNumeracao.js');
                    return await module.validarIntervalosNumeracao(body);
                }

                if (functionName === 'redefinirParaCopia') {
                    const module = await import('./redefinirParaCopia.js');
                    return await module.redefinirParaCopia(body, rdsn);
                }

                if (functionName === 'backupDados') {
                    const module = await import('./backupDados.js');
                    return await module.backupDados(body, rdsn);
                }

                if (functionName === 'restaurarBackup') {
                    const module = await import('./restaurarBackup.js');
                    return await module.restaurarBackup(body, rdsn);
                }

                // Exemplo fallback se falhar (mantém o envio via network se for as outras que não mapeamos ainda)
                const { data, error } = await supabase.functions.invoke(functionName, {
                    body: body,
                });
                if (error) throw error;

                // RDSN usually returned an object containing { data: { success: true, ... } }
                // Some code might expect the outer response to have `.data`
                // and the inner payload to be the actual function response.
                // Edge functions usually return JSON directly.
                if (data && data.success !== undefined) {
                    return { data: data };
                }
                return { data };
            } catch (err) {
                console.error(`Error invoking function ${functionName}:`, err);
                throw err;
            }
        }
    },
    /** @type {Record<string, any>} */
    entities: new Proxy({}, {
        get: (target, prop) => {
            if (!target[prop]) {
                target[prop] = createEntityAdapter(prop);
            }
            return target[prop];
        }
    }),
    asServiceRole: {
        /** @type {Record<string, any>} */
        entities: new Proxy({}, {
            get: (target, prop) => {
                if (!target[prop]) {
                    target[prop] = createEntityAdapter(prop);
                }
                return target[prop];
            }
        })
    }
};

import { rdsn } from './supabaseClient.js';

export async function sincronizarBaixasComPCP(payload) {
  try {
    const { mes, ano, op_id, setor_id } = payload;

    if (!mes || !ano) {
      return { data: { error: 'mes e ano são obrigatórios' }, status: 400 };
    }

    // 1. Buscar OPs do mês/ano
    let filtroOps = op_id
      ? { id: op_id, mes, ano }
      : { mes, ano, status: 'Ativo' };

    if (setor_id && !op_id) {
      filtroOps = { ...filtroOps, setor_id };
    }

    const ops = await rdsn.entities.PCPOrdemProducao.filter(filtroOps, null, 200);
    const opsComCodigo = ops.filter(op => (op.codigo_produto && op.codigo_produto.trim()) || (op.codigo_op && op.codigo_op.trim()));

    if (opsComCodigo.length === 0) {
      return { data: { message: 'Nenhuma OP encontrada para sincronizar', sincronizadas: 0 } };
    }

    // 2. Buscar reservas em paralelo por cada codigo_produto único
    const getCodigoOP = (op) => (op.codigo_produto && op.codigo_produto.trim()) || op.codigo_op;
    const codigosUnicos = [...new Set(opsComCodigo.map(o => getCodigoOP(o)).filter(Boolean))];

    const [reservasPorCodigoArr, todasProducoesMes] = await Promise.all([
      Promise.all(
        codigosUnicos.map(codigo =>
          rdsn.entities.ReservaLote.filter({ codigo_produto: codigo }, null, 500)
            .then(reservas => ({ codigo, reservas }))
            .catch(() => ({ codigo, reservas: [] }))
        )
      ),
      rdsn.entities.PCPProducaoDiaria.filter({ mes, ano }, null, 5000)
    ]);

    const reservasPorCodigo = {};
    for (const { codigo, reservas } of reservasPorCodigoArr) {
      reservasPorCodigo[codigo] = reservas;
    }

    const producaoExistentePorKey = {};
    const registrosOrfaos = [];
    for (const p of todasProducoesMes) {
      const key = `${p.op_id}-${p.dia}`;
      const existing = producaoExistentePorKey[key];
      if (!existing) {
        producaoExistentePorKey[key] = p;
      } else {
        if (p.setor_id && !existing.setor_id) {
          registrosOrfaos.push(existing);
          producaoExistentePorKey[key] = p;
        } else if (!p.setor_id && existing.setor_id) {
          registrosOrfaos.push(p);
        } else if (p.setor_id && existing.setor_id && setor_id) {
          if (p.setor_id === setor_id && existing.setor_id !== setor_id) {
            registrosOrfaos.push(existing);
            producaoExistentePorKey[key] = p;
          } else {
            registrosOrfaos.push(p);
          }
        }
      }
    }

    if (registrosOrfaos.length > 0) {
      await Promise.allSettled(
        registrosOrfaos.map(p => {
          const key = `${p.op_id}-${p.dia}`;
          const correto = producaoExistentePorKey[key];
          if (correto && p.realizado > 0 && (!correto.realizado || correto.realizado === 0)) {
            return rdsn.entities.PCPProducaoDiaria.update(correto.id, { realizado: p.realizado })
              .then(() => rdsn.entities.PCPProducaoDiaria.delete(p.id));
          }
          return rdsn.entities.PCPProducaoDiaria.delete(p.id);
        })
      );
    }

    const anoCompleto = 2000 + ano;
    const inicioMes = new Date(anoCompleto, mes - 1, 1).toISOString();
    const fimMes = new Date(anoCompleto, mes, 0, 23, 59, 59).toISOString();

    const todasReservas = Object.values(reservasPorCodigo).flat();
    const reservaIdSet = new Set(todasReservas.map(r => r.id));

    const baixasPorReservaArr = await Promise.all(
      [...reservaIdSet].map(reservaId =>
        rdsn.entities.BaixaLote.filter({ reserva_id: reservaId }, null, 1000)
          .then(baixas => ({ reservaId, baixas }))
          .catch(() => ({ reservaId, baixas: [] }))
      )
    );

    const baixasPorReserva = {};
    for (const { reservaId, baixas } of baixasPorReservaArr) {
      baixasPorReserva[reservaId] = baixas.filter(b => {
        if (!b.created_at) return true;
        return b.created_at >= inicioMes && b.created_at <= fimMes;
      });
    }

    const erros = [];

    const resultados = await Promise.allSettled(
      opsComCodigo.map(async (op) => {
        const codigoBusca = getCodigoOP(op);
        const reservas = reservasPorCodigo[codigoBusca] || [];
        const todasBaixas = reservas.flatMap(r => baixasPorReserva[r.id] || []);

        if (todasBaixas.length === 0) return { op_id: op.id, skipped: true };

        const qtdPorDia = {};
        for (const baixa of todasBaixas) {
          const dia = baixa.created_at ? new Date(baixa.created_at).getDate() : 1;
          qtdPorDia[dia] = (qtdPorDia[dia] || 0) + (baixa.quantidade || 0);
        }

        const writes = Object.entries(qtdPorDia).map(([diaStr, qtd]) => {
          const dia = Number(diaStr);
          const existente = producaoExistentePorKey[`${op.id}-${dia}`];
          if (existente) {
            if (existente.realizado === qtd) return Promise.resolve();
            return rdsn.entities.PCPProducaoDiaria.update(existente.id, { realizado: qtd });
          } else {
            return rdsn.entities.PCPProducaoDiaria.create({
              op_id: op.id, mes, ano, dia, previsto: 0, realizado: qtd, setor_id: setor_id || op.setor_id || ''
            });
          }
        });

        await Promise.all(writes);
        return { op_id: op.id, dias: Object.keys(qtdPorDia).length };
      })
    );

    let totalSincronizadas = 0;
    for (const r of resultados) {
      if (r.status === 'fulfilled' && !r.value?.skipped) {
        totalSincronizadas++;
      } else if (r.status === 'rejected') {
        erros.push(r.reason?.message || 'Erro desconhecido');
      }
    }

    return {
      data: {
        success: true,
        message: 'Sincronização concluída',
        sincronizadas: totalSincronizadas,
        erros: erros.length > 0 ? erros : undefined,
        mes,
        ano
      }
    };

  } catch (error) {
    return { data: { error: error.message }, status: 500 };
  }
}

export async function backupDados(payload, rdsn) {
    console.log('[BACKUP SHIM] Iniciando geração de backup local...');
    try {
        const user = await rdsn.auth.me();
        const userEmail = user?.email || 'Sistema Local';
        const dataBackup = new Date().toISOString();

        // Lista de entidades para backup (mesma do functions/backupDados.ts)
        const entidades = {
            reservas: 'ReservaLote',
            baixas: 'BaixaLote',
            sequencias: 'SequenciaAnual',
            numeracoes: 'NumeracaoLivre',
            bloqueios: 'BloqueioIntervalo',
            produtos: 'Produto',
            clientes: 'Cliente',
            setores: 'Setor',
            movimentacoes: 'MovimentacaoEstoque',
            auditorias: 'Auditoria',
            alertas: 'Alerta',
            notificacoes: 'Notificacao',
            usuarios_internos: 'UsuarioInterno',
            producao_dia: 'ProducaoDia',
            producao_dia_lotes: 'ProducaoDiaLote'
        };

        const dados = {};
        const estatisticas = {};

        for (const [chave, entidade] of Object.entries(entidades)) {
            console.log(`[BACKUP SHIM] Extraindo ${entidade}...`);
            const registros = await rdsn.asServiceRole.entities[entidade].list();
            dados[chave] = registros;
            estatisticas[`total_${chave}`] = registros.length;
        }

        const backup = {
            versao: '1.0-LOCAL',
            data_backup: dataBackup,
            gerado_por: userEmail,
            dados,
            estatisticas
        };

        const backupJson = JSON.stringify(backup, null, 2);
        const totalRegistros = Object.values(dados).reduce(
            (acc, arr) => acc + (Array.isArray(arr) ? arr.length : 0),
            0
        );

        // Simular o upload gerando um Blob URL temporário para o frontend baixar
        const blob = new Blob([backupJson], { type: 'application/json' });
        const dummyUrl = URL.createObjectURL(blob);

        // Registrar no histórico local
        await rdsn.asServiceRole.entities.BackupHistorico.create({
            data_backup: dataBackup,
            status: 'SUCESSO',
            tipo: 'MANUAL_LOCAL',
            total_registros: totalRegistros,
            tamanho_bytes: blob.size,
            arquivo_url: dummyUrl,
            detalhes: JSON.stringify(estatisticas)
        });

        return {
            data: {
                sucesso: true,
                mensagem: 'Backup local realizado com sucesso',
                arquivo_url: dummyUrl,
                total_registros: totalRegistros,
                tamanho_mb: (blob.size / 1024 / 1024).toFixed(2)
            }
        };

    } catch (error) {
        console.error('[BACKUP SHIM] Erro ao gerar backup:', error);
        return { data: { sucesso: false, erro: error.message }, status: 500 };
    }
}

