import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { Plus, Edit2, Trash2, Send, Download, Activity, CheckCircle2, XCircle, Clock, RefreshCw, FileText } from 'lucide-react';
import { Link } from 'react-router-dom';
import { createPageUrl } from '../utils';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { useSetor } from '@/components/context/SetorContext';

export default function Integracoes() {
  const queryClient = useQueryClient();
  const { setorAtivo } = useSetor();
  const [showForm, setShowForm] = useState(false);
  const [showExport, setShowExport] = useState(false);
  const [showLogs, setShowLogs] = useState(null);
  const [editingIntegracao, setEditingIntegracao] = useState(null);
  const [formData, setFormData] = useState({
    nome: '',
    tipo: 'ERP',
    url_base: '',
    tipo_autenticacao: 'API Key',
    chave_api: '',
    url_webhook: '',
    eventos_habilitados: [],
    formato_exportacao: 'JSON',
    ativa: true
  });

  const { data: integracoes = [] } = useQuery({
    queryKey: ['integracoes'],
    queryFn: () => rdsn.entities.IntegracaoExterna.list()
  });

  const { data: logs = [] } = useQuery({
    queryKey: ['logs-integracao', showLogs],
    queryFn: () => showLogs ? rdsn.entities.LogIntegracao.filter({ integracao_id: showLogs }) : [],
    enabled: !!showLogs
  });

  const createMutation = useMutation({
    mutationFn: (data) => rdsn.entities.IntegracaoExterna.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['integracoes'] });
      setShowForm(false);
      resetForm();
      toast.success('Integração criada com sucesso!');
    }
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => rdsn.entities.IntegracaoExterna.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['integracoes'] });
      setShowForm(false);
      resetForm();
      toast.success('Integração atualizada!');
    }
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => rdsn.entities.IntegracaoExterna.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['integracoes'] });
      toast.success('Integração removida!');
    }
  });

  const testarConexaoMutation = useMutation({
    mutationFn: async (integracao) => {
      const response = await rdsn.functions.invoke('enviarWebhook', {
        integracao_id: integracao.id,
        evento: 'TESTE_CONEXAO',
        dados: { teste: true, timestamp: new Date().toISOString() }
      });
      return response.data;
    },
    onSuccess: (data) => {
      if (data.success) {
        toast.success('Conexão testada com sucesso!');
      } else {
        toast.error('Falha ao testar conexão: ' + data.mensagem);
      }
    }
  });

  const resetForm = () => {
    setFormData({
      nome: '',
      tipo: 'ERP',
      url_base: '',
      tipo_autenticacao: 'API Key',
      chave_api: '',
      url_webhook: '',
      eventos_habilitados: [],
      formato_exportacao: 'JSON',
      ativa: true
    });
    setEditingIntegracao(null);
  };

  const handleOpenForm = (integracao = null, template = null) => {
    if (integracao) {
      setEditingIntegracao(integracao);
      setFormData(integracao);
    } else if (template === 'SIRC') {
      setFormData({
        nome: 'SIRC',
        tipo: 'ERP',
        url_base: 'https://api.sirc.exemplo.com',
        tipo_autenticacao: 'API Key',
        chave_api: '',
        url_webhook: 'https://api.sirc.exemplo.com/webhooks/producao',
        eventos_habilitados: ['PRODUCAO_CONFIRMADA', 'LOTE_FINALIZADO', 'RESERVA_CRIADA', 'RESERVA_CANCELADA'],
        formato_exportacao: 'JSON',
        ativa: true
      });
    }
    setShowForm(true);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (editingIntegracao) {
      updateMutation.mutate({ id: editingIntegracao.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const handleExportar = async (formato) => {
    try {
      const response = await rdsn.functions.invoke('exportarProducao', {
