                  placeholder="https://api.sirc.exemplo.com/webhooks/producao"
                />
                <p className="text-xs text-slate-500">URL para notificações de eventos</p>
                <p className="text-xs text-slate-500">Exemplo SIRC: https://api.sirc.exemplo.com/webhooks/producao</p>
              </div>

              <div className="space-y-2">
                <Label>Eventos para Webhook</Label>
                <div className="grid grid-cols-2 gap-3 p-4 bg-slate-50 rounded-lg">
                  {eventosDisponiveis.map(evento => (
                    <div key={evento.value} className="flex items-center space-x-2">
                      <Checkbox
                        checked={formData.eventos_habilitados?.includes(evento.value)}
                        onCheckedChange={(checked) => {
                          const novos = checked
                            ? [...(formData.eventos_habilitados || []), evento.value]
                            : formData.eventos_habilitados.filter(e => e !== evento.value);
                          setFormData({ ...formData, eventos_habilitados: novos });
                        }}
                      />
                      <label className="text-sm">{evento.label}</label>
                    </div>
                  ))}
                </div>
              </div>

              <div className="space-y-2">
                <Label>Formato de Exportação</Label>
                <Select
                  value={formData.formato_exportacao}
                  onValueChange={(v) => setFormData({ ...formData, formato_exportacao: v })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="JSON">JSON</SelectItem>
                    <SelectItem value="CSV">CSV</SelectItem>
                    <SelectItem value="XML">XML</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="flex items-center justify-between">
                <Label>Integração Ativa</Label>
                <Switch
                  checked={formData.ativa}
                  onCheckedChange={(checked) => setFormData({ ...formData, ativa: checked })}
                />
              </div>

              <DialogFooter>
                <Button type="button" variant="outline" onClick={() => setShowForm(false)}>
                  Cancelar
                </Button>
                <Button type="submit" className="bg-slate-900 hover:bg-slate-800">
                  {editingIntegracao ? 'Salvar' : 'Criar Integração'}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>

        {/* Dialog - Exportar Dados */}
        <Dialog open={showExport} onOpenChange={setShowExport}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Exportar Dados de Produção</DialogTitle>
              <p className="text-sm text-slate-500 mt-2">
                Selecione o formato de exportação desejado
              </p>
            </DialogHeader>
            <div className="space-y-3">
              <Button
                className="w-full justify-start h-auto p-4"
                variant="outline"
                onClick={() => handleExportar('JSON')}
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
                    <span className="text-blue-600 font-bold text-sm">{ }</span>
                  </div>
                  <div className="text-left">
                    <div className="font-semibold">JSON</div>
                    <div className="text-xs text-slate-500">Formato estruturado para APIs</div>
                  </div>
                </div>
              </Button>
              <Button
                className="w-full justify-start h-auto p-4"
                variant="outline"
                onClick={() => handleExportar('CSV')}
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
                    <span className="text-green-600 font-bold text-sm">CSV</span>
                  </div>
                  <div className="text-left">
                    <div className="font-semibold">CSV</div>
                    <div className="text-xs text-slate-500">Planilha compatível com Excel</div>
                  </div>
                </div>
              </Button>
              <Button
                className="w-full justify-start h-auto p-4"
                variant="outline"
                onClick={() => handleExportar('XML')}
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-orange-100 rounded-lg flex items-center justify-center">
                    <span className="text-orange-600 font-bold text-sm">XML</span>
                  </div>
                  <div className="text-left">
                    <div className="font-semibold">XML</div>
                    <div className="text-xs text-slate-500">Formato padrão para ERP/MES</div>
                  </div>
                </div>
              </Button>
            </div>
          </DialogContent>
        </Dialog>

        {/* Dialog - Logs */}
        <Dialog open={!!showLogs} onOpenChange={() => setShowLogs(null)}>
          <DialogContent className="max-w-4xl max-h-[80vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Logs de Integração</DialogTitle>
            </DialogHeader>
            <div className="space-y-2">
              {logs.slice(0, 50).map(log => (
                <div key={log.id} className="p-3 bg-slate-50 rounded-lg border border-slate-200">
                  <div className="flex items-start justify-between">
                    <div className="flex items-center gap-2">
                      {log.status === 'SUCESSO' ? (
                        <CheckCircle2 className="w-4 h-4 text-green-600" />
                      ) : (
                        <XCircle className="w-4 h-4 text-red-600" />
                      )}
                      <div>
                        <p className="font-medium text-sm">{log.evento}</p>
                        <p className="text-xs text-slate-500">
                          {new Date(log.created_at).toLocaleString('pt-BR')} •
                          {log.tempo_resposta_ms}ms
                        </p>
                      </div>
                    </div>
                    <Badge variant={log.status === 'SUCESSO' ? 'default' : 'destructive'}>
                      {log.codigo_resposta}
                    </Badge>
                  </div>
                  {log.mensagem_erro && (
                    <p className="text-xs text-red-600 mt-2">{log.mensagem_erro}</p>
                  )}
                </div>
              ))}
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
}

// @ts-nocheck
import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { useSetor } from '@/components/context/SetorContext';
import { cn } from "@/lib/utils";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Hash, AlertTriangle, CheckCircle, XCircle, Search, Activity, Plus, Settings, Clock, History, Trash2, Play } from 'lucide-react';
import { toast } from 'sonner';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

const severidadeConfig = {
  CRITICA: { color: 'bg-red-100 text-red-800 border-red-200 dark:bg-red-900/30 dark:text-red-400 dark:border-red-900/50', icon: XCircle },
  ALTA: { color: 'bg-orange-100 text-orange-800 border-orange-200 dark:bg-orange-900/30 dark:text-orange-400 dark:border-orange-900/50', icon: AlertTriangle },
  MEDIA: { color: 'bg-yellow-100 text-yellow-800 border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-400 dark:border-yellow-900/50', icon: AlertTriangle },
  BAIXA: { color: 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-900/50', icon: Activity }
};

const tiposVerificacao = [
  { value: 'SOBREPOSICAO', label: 'Sobreposição de Números' },
  { value: 'LACUNAS', label: 'Lacunas na Numeração' },
  { value: 'DUPLICIDADE', label: 'Números Duplicados' },
  { value: 'SEQUENCIA_INVALIDA', label: 'Sequência Inválida' },
  { value: 'NUMERACAO_LIVRE_INVALIDA', label: 'Numeração Livre Inválida' }
];

export default function AuditoriaNumeracao() {
  const { setorAtivo, isAdmin } = useSetor();
  const queryClient = useQueryClient();
  const [letraSelecionada, setLetraSelecionada] = useState('');
  const [anoSelecionado, setAnoSelecionado] = useState('');
  const [problemas, setProblemas] = useState(null);
  const [loading, setLoading] = useState(false);
  const [dialogRegraOpen, setDialogRegraOpen] = useState(false);
  const [novaRegra, setNovaRegra] = useState({
    nome: '',
    descricao: '',
    tipo_verificacao: 'SOBREPOSICAO',
    severidade: 'MEDIA',
    ativa: true
  });

  const { data: produtos = [] } = useQuery({
    queryKey: ['produtos', setorAtivo],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.Produto.list();
      }
      return await rdsn.entities.Produto.filter({ setor_id: setorAtivo });
    },
    enabled: !!setorAtivo
  });

  const { data: sequencias = [] } = useQuery({
    queryKey: ['sequencias', setorAtivo],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.SequenciaAnual.list();
      }
      return await rdsn.entities.SequenciaAnual.filter({ setor_id: setorAtivo });
    },
    enabled: !!setorAtivo
  });

  const { data: reservas = [] } = useQuery({
    queryKey: ['reservas-auditoria', setorAtivo, letraSelecionada, anoSelecionado],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.ReservaLote.list('-created_at', 500);
      }
      return await rdsn.entities.ReservaLote.filter({ setor_id: setorAtivo }, '-created_at', 500);
    },
    enabled: !!letraSelecionada && !!anoSelecionado && !!setorAtivo
  });

  const { data: numeracoesLivres = [] } = useQuery({
    queryKey: ['numeracoes-livres-auditoria', setorAtivo, letraSelecionada, anoSelecionado],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.NumeracaoLivre.list('-created_at', 500);
      }
      return await rdsn.entities.NumeracaoLivre.filter({ setor_id: setorAtivo }, '-created_at', 500);
    },
    enabled: !!letraSelecionada && !!anoSelecionado && !!setorAtivo
  });

  const { data: regras = [] } = useQuery({
    queryKey: ['regras-auditoria'],
    queryFn: () => rdsn.entities.RegraAuditoria.list()
  });

  const { data: historico = [] } = useQuery({
    queryKey: ['historico-auditoria'],
    queryFn: () => rdsn.entities.HistoricoAuditoria.list('-created_at', 50)
  });

  const letras = [...new Set(produtos.map(p => p.letra_produto))];
  const anos = [...new Set(sequencias.map(s => s.ano))];

  const reservasFiltradas = reservas.filter(r =>
    r.letra_produto === letraSelecionada &&
    r.ano === Number(anoSelecionado) &&
    r.status !== 'CANCELADO'
  );

  const livresFiltradas = numeracoesLivres.filter(nl =>
    nl.letra_produto === letraSelecionada &&
    nl.ano === Number(anoSelecionado)
  );

  const criarRegraMutation = useMutation({
    mutationFn: (dados) => rdsn.entities.RegraAuditoria.create(dados),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['regras-auditoria'] });
      setDialogRegraOpen(false);
      setNovaRegra({
        nome: '',
        descricao: '',
        tipo_verificacao: 'SOBREPOSICAO',
        severidade: 'MEDIA',
        ativa: true
      });
      toast.success('Regra criada com sucesso!');
    }
  });

  const deletarRegraMutation = useMutation({
    mutationFn: (id) => rdsn.entities.RegraAuditoria.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['regras-auditoria'] });
      toast.success('Regra excluída!');
    }
  });

  const toggleRegraMutation = useMutation({
    mutationFn: ({ id, ativa }) => rdsn.entities.RegraAuditoria.update(id, { ativa }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['regras-auditoria'] });
    }
  });

  const handleAnalisar = async () => {
    if (!letraSelecionada || !anoSelecionado) {
      toast.error('Selecione letra e ano');
      return;
    }

    setLoading(true);
    try {
      const response = await rdsn.functions.invoke('executarAuditoriaAutomatica', {
        letra_produto: letraSelecionada,
        ano: Number(anoSelecionado),
        setor_id: setorAtivo === 'ALL' ? null : setorAtivo,
        tipo_execucao: 'MANUAL'
      });

      setProblemas(response.data);
      queryClient.invalidateQueries({ queryKey: ['historico-auditoria'] });

      if (response.data.total_problemas === 0) {
        toast.success('Nenhum problema detectado!');
      } else {
        toast.warning(`${response.data.total_problemas} problema(s) encontrado(s)`);
      }
    } catch (error) {
      toast.error('Erro ao analisar: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const executarAuditoriaComRegras = async () => {
    if (!letraSelecionada || !anoSelecionado) {
      toast.error('Selecione letra e ano');
      return;
    }

    const regrasAtivas = regras.filter(r => r.ativa).map(r => r.id);
    if (regrasAtivas.length === 0) {
      toast.error('Nenhuma regra ativa! Crie regras customizadas primeiro.');
      return;
    }

    setLoading(true);
    try {
      const response = await rdsn.functions.invoke('executarAuditoriaAutomatica', {
        letra_produto: letraSelecionada,
        ano: Number(anoSelecionado),
        setor_id: setorAtivo === 'ALL' ? null : setorAtivo,
        regras_ids: regrasAtivas,
        tipo_execucao: 'MANUAL'
      });

      setProblemas(response.data);
      queryClient.invalidateQueries({ queryKey: ['historico-auditoria'] });

      toast.success(`Auditoria concluída! ${response.data.total_problemas} problema(s) encontrado(s)`);
    } catch (error) {
      toast.error('Erro ao executar auditoria: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const construirMapaNumeros = () => {
    if (reservasFiltradas.length === 0 && livresFiltradas.length === 0) return null;

    const todosNumeros = [];

    reservasFiltradas.forEach(r => {
      todosNumeros.push({
        tipo: 'RESERVA',
        inicio: r.numero_inicial,
        fim: r.numero_final,
        dados: r
      });
    });

    livresFiltradas.forEach(nl => {
      todosNumeros.push({
        tipo: 'LIVRE',
        inicio: nl.numero_inicial,
        fim: nl.numero_final,
        dados: nl
      });
    });

    todosNumeros.sort((a, b) => a.inicio - b.inicio);
    return todosNumeros;
  };

  const mapaNumeros = construirMapaNumeros();

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 p-6 transition-colors duration-300">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header Premium */}
        <div className="relative overflow-hidden rounded-[2.5rem] bg-white dark:bg-slate-900/40 backdrop-blur-3xl p-5 sm:p-6 shadow-2xl border border-slate-200 dark:border-white/5 mb-6">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_-20%,rgba(168,85,247,0.15),transparent)] pointer-events-none" />
          <div className="relative flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8">
            <div className="flex items-center gap-4 sm:gap-5">
              <div className="w-16 h-16 sm:w-14 sm:h-14 bg-gradient-to-br from-purple-600 to-fuchsia-500 rounded-[2.5rem] flex items-center justify-center shadow-[0_0_30px_rgba(168,85,247,0.4)] transition-all hover:scale-105 active:scale-95 group border border-purple-400/20">
                <Hash className="w-8 h-8 sm:w-6 sm:h-6 text-white group-hover:rotate-12 transition-transform duration-500" />
              </div>
              <div className="space-y-1">
                <h1 className="text-2xl sm:text-3xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter leading-none">
                  Auditoria de <span className="text-purple-600 dark:text-purple-400">Numeração</span>
                </h1>
                <p className="text-xs sm:text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em] italic opacity-80 flex items-center gap-2">
                  Validação Automatizada • Histórico de Alocação
                </p>
              </div>
            </div>
          </div>
        </div>

        <Tabs defaultValue="analise" className="w-full">
          <TabsList className="grid w-full grid-cols-3 bg-slate-100 dark:bg-slate-900 p-1 rounded-xl">
            <TabsTrigger value="analise" className="rounded-lg transition-all dark:data-[state=active]:bg-slate-800 dark:data-[state=active]:text-slate-100">Análise Manual</TabsTrigger>
            <TabsTrigger value="regras" className="rounded-lg transition-all dark:data-[state=active]:bg-slate-800 dark:data-[state=active]:text-slate-100">Regras Customizadas</TabsTrigger>
            <TabsTrigger value="historico" className="rounded-lg transition-all dark:data-[state=active]:bg-slate-800 dark:data-[state=active]:text-slate-100">Histórico</TabsTrigger>
          </TabsList>

          <TabsContent value="analise" className="space-y-6 mt-6">
            <Card className="border border-slate-200 dark:border-white/5 shadow-2xl bg-white dark:bg-slate-900/40 backdrop-blur-xl overflow-hidden rounded-[2.5rem]">
              <CardHeader className="border-b border-slate-100 dark:border-slate-800">
                <CardTitle className="text-slate-900 dark:text-slate-100">Selecionar Escopo</CardTitle>
              </CardHeader>
              <CardContent className="pt-6">
                <div className="flex gap-4 items-end">
                  <div className="flex-1 space-y-2">
                    <label className="text-sm font-medium">Letra do Produto</label>
                    <Select value={letraSelecionada} onValueChange={setLetraSelecionada}>
                      <SelectTrigger className="dark:bg-slate-800 dark:border-slate-700 dark:text-white">
                        <SelectValue placeholder="Selecione" />
                      </SelectTrigger>
                      <SelectContent className="dark:bg-slate-900 dark:border-slate-800">
                        {letras.map(letra => (
                          <SelectItem key={letra} value={letra}>{letra}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="flex-1 space-y-2">
                    <label className="text-sm font-medium">Ano</label>
                    <Select value={anoSelecionado} onValueChange={setAnoSelecionado}>
                      <SelectTrigger className="dark:bg-slate-800 dark:border-slate-700 dark:text-white">
                        <SelectValue placeholder="Selecione" />
                      </SelectTrigger>
                      <SelectContent className="dark:bg-slate-900 dark:border-slate-800">
                        {anos.map(ano => (
                          <SelectItem key={ano} value={String(ano)}>{ano}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <Button
                    onClick={handleAnalisar}
                    disabled={!letraSelecionada || !anoSelecionado || loading}
                    className="bg-slate-900 hover:bg-slate-800 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200 font-bold"
                  >
                    <Search className="w-4 h-4 mr-2" />
                    {loading ? 'Analisando...' : 'Análise Padrão'}
                  </Button>

                  <Button
                    onClick={executarAuditoriaComRegras}
                    disabled={!letraSelecionada || !anoSelecionado || loading}
                    variant="outline"
                    className="dark:border-slate-700 dark:hover:bg-slate-800 dark:text-slate-300"
                  >
                    <Play className="w-4 h-4 mr-2" />
                    Com Regras
                  </Button>
                </div>
              </CardContent>
            </Card>

            {problemas && (
              <Card className={cn(
                "shadow-2xl bg-white dark:bg-slate-900/40 backdrop-blur-xl overflow-hidden rounded-[2.5rem]",
                problemas.total_problemas > 0
                  ? "border-2 border-orange-200 dark:border-orange-900/50"
                  : "border-2 border-green-200 dark:border-green-900/50"
              )}>
                <CardHeader className="border-b border-slate-100 dark:border-slate-800">
                  <div className="flex items-center justify-between">
                    <CardTitle className="flex items-center gap-2">
                      {problemas.total_problemas === 0 ? (
                        <>
                          <CheckCircle className="w-6 h-6 text-green-600" />
                          Sistema Íntegro
                        </>
                      ) : (
                        <>
                          <AlertTriangle className="w-6 h-6 text-orange-600" />
                          Problemas Detectados
                        </>
                      )}
                    </CardTitle>
                    <Badge className={
                      problemas.total_problemas === 0
                        ? 'bg-green-100 text-green-800'
                        : 'bg-orange-100 text-orange-800'
                    }>
                      {problemas.total_problemas} problema(s)
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent className="pt-6">
                  {problemas.total_problemas === 0 ? (
                    <p className="text-slate-600 dark:text-slate-400">Nenhum problema de integridade detectado para {letraSelecionada}{anoSelecionado}</p>
                  ) : (
                    <div className="space-y-3">
                      {problemas.problemas.map((problema, idx) => {
                        const config = severidadeConfig[problema.severidade];
                        const Icon = config?.icon || AlertTriangle;
                        return (
                          <Alert key={idx} className={`border-2 ${config?.color || 'bg-gray-100'}`}>
                            <Icon className="w-4 h-4" />
                            <AlertDescription>
                              <div className="font-semibold mb-1">{problema.descricao}</div>
                              {problema.regra_nome && (
                                <div className="text-xs text-slate-500 mb-2">Regra: {problema.regra_nome}</div>
                              )}
                              <div className="text-xs bg-white/50 dark:bg-slate-950/50 p-2 rounded mt-2 font-mono dark:text-slate-300">
                                {JSON.stringify(problema.detalhes, null, 2)}
                              </div>
                            </AlertDescription>
                          </Alert>
                        );
                      })}
                    </div>
                  )}
                </CardContent>
              </Card>
            )}

            {mapaNumeros && mapaNumeros.length > 0 && (
              <Card className="border border-slate-200 dark:border-white/5 shadow-2xl bg-white dark:bg-slate-900/40 backdrop-blur-xl overflow-hidden rounded-[2.5rem]">
                <CardHeader className="border-b border-slate-100 dark:border-slate-800">
                  <CardTitle className="text-slate-900 dark:text-slate-100">Mapa de Alocação de Números</CardTitle>
                </CardHeader>
                <CardContent className="pt-6">
                  <div className="space-y-2">
                    {mapaNumeros.map((item, idx) => (
                      <div
                        key={idx}
                        className={cn(
                          "flex items-center justify-between p-3 rounded-lg border-2",
                          item.tipo === 'RESERVA'
                            ? 'bg-blue-50 border-blue-200 dark:bg-blue-900/10 dark:border-blue-900/30'
                            : 'bg-green-50 border-green-200 dark:bg-green-900/10 dark:border-green-900/30'
                        )}
                      >
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <Badge className={item.tipo === 'RESERVA' ? 'bg-blue-600' : 'bg-green-600'}>
                              {item.tipo}
                            </Badge>
                            <span className="font-mono font-bold dark:text-slate-200">
                              {item.inicio.toLocaleString()} - {item.fim.toLocaleString()}
                            </span>
                            <span className="text-sm text-slate-600 dark:text-slate-400">
                              ({(item.fim - item.inicio + 1).toLocaleString()} números)
                            </span>
                          </div>
                          {item.tipo === 'RESERVA' && (
                            <div className="text-xs text-slate-600 dark:text-slate-400 mt-1">
                              Cliente: {item.dados.cliente || '-'} | Status: {item.dados.status}
                            </div>
                          )}
                          {item.tipo === 'LIVRE' && (
                            <div className="text-xs text-slate-600 dark:text-slate-400 mt-1">
                              Motivo: {item.dados.motivo} | Disponível: {item.dados.disponivel ? 'Sim' : 'Não'}
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </TabsContent>

          <TabsContent value="regras" className="space-y-6 mt-6">
            <div className="flex justify-between items-center">
              <p className="text-sm text-slate-600 dark:text-slate-400">Defina regras customizadas para detecção automatizada</p>
              <Dialog open={dialogRegraOpen} onOpenChange={setDialogRegraOpen}>
                <DialogTrigger asChild>
                  <Button className="bg-slate-900 hover:bg-slate-800 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200 font-bold">
                    <Plus className="w-4 h-4 mr-2" />
                    Nova Regra
                  </Button>
                </DialogTrigger>
                <DialogContent className="max-w-2xl dark:bg-slate-900 dark:border-slate-800">
                  <DialogHeader>
                    <DialogTitle className="dark:text-slate-100">Criar Regra de Auditoria</DialogTitle>
                  </DialogHeader>
                  <div className="space-y-4">
                    <div>
                      <Label className="dark:text-slate-300">Nome da Regra</Label>
                      <Input
                        value={novaRegra.nome}
                        onChange={(e) => setNovaRegra({ ...novaRegra, nome: e.target.value })}
                        placeholder="Ex: Verificar sobreposições críticas"
                        className="dark:bg-slate-800 dark:border-slate-700 dark:text-white"
                      />
                    </div>

                    <div>
                      <Label className="dark:text-slate-300">Descrição</Label>
                      <Textarea
                        value={novaRegra.descricao}
                        onChange={(e) => setNovaRegra({ ...novaRegra, descricao: e.target.value })}
                        placeholder="Descreva o objetivo desta regra"
                        className="dark:bg-slate-800 dark:border-slate-700 dark:text-white"
                      />
                    </div>

                    <div>
                      <Label className="dark:text-slate-300">Tipo de Verificação</Label>
                      <Select value={novaRegra.tipo_verificacao} onValueChange={(v) => setNovaRegra({ ...novaRegra, tipo_verificacao: v })}>
                        <SelectTrigger className="dark:bg-slate-800 dark:border-slate-700 dark:text-white">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent className="dark:bg-slate-900 dark:border-slate-800">
                          {tiposVerificacao.map(tipo => (
                            <SelectItem key={tipo.value} value={tipo.value}>{tipo.label}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    <div>
                      <Label className="dark:text-slate-300">Severidade</Label>
                      <Select value={novaRegra.severidade} onValueChange={(v) => setNovaRegra({ ...novaRegra, severidade: v })}>
                        <SelectTrigger className="dark:bg-slate-800 dark:border-slate-700 dark:text-white">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent className="dark:bg-slate-900 dark:border-slate-800">
                          <SelectItem value="BAIXA">Baixa</SelectItem>
                          <SelectItem value="MEDIA">Média</SelectItem>
                          <SelectItem value="ALTA">Alta</SelectItem>
                          <SelectItem value="CRITICA">Crítica</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="flex items-center gap-2">
                      <Switch
                        checked={novaRegra.ativa}
                        onCheckedChange={(checked) => setNovaRegra({ ...novaRegra, ativa: checked })}
                      />
                      <Label className="dark:text-slate-300">Regra ativa</Label>
                    </div>

                    <Button
                      onClick={() => criarRegraMutation.mutate(novaRegra)}
                      disabled={!novaRegra.nome || criarRegraMutation.isPending}
                      className="w-full"
                    >
                      Criar Regra
                    </Button>
                  </div>
                </DialogContent>
              </Dialog>
            </div>

            <div className="grid gap-4">
              {regras.map(regra => (
                <Card key={regra.id} className={cn(
                  "border border-slate-200 dark:border-white/5 shadow-2xl bg-white dark:bg-slate-900/40 backdrop-blur-xl overflow-hidden rounded-[2.5rem]",
                  !regra.ativa && 'opacity-60'
                )}>
                  <CardHeader>
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <CardTitle className="text-lg dark:text-slate-100">{regra.nome}</CardTitle>
                        <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">{regra.descricao}</p>
                      </div>
                      <div className="flex items-center gap-2">
                        <Switch
                          checked={regra.ativa}
                          onCheckedChange={(checked) => toggleRegraMutation.mutate({ id: regra.id, ativa: checked })}
                        />
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => deletarRegraMutation.mutate(regra.id)}
                        >
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="flex gap-2">
                      <Badge>{tiposVerificacao.find(t => t.value === regra.tipo_verificacao)?.label}</Badge>
                      <Badge className={severidadeConfig[regra.severidade]?.color}>
                        {regra.severidade}
                      </Badge>
                    </div>
                  </CardContent>
                </Card>
              ))}
              {regras.length === 0 && (
                <Card className="border border-slate-200 dark:border-white/5 shadow-2xl bg-white dark:bg-slate-900/40 backdrop-blur-xl overflow-hidden rounded-[2.5rem]">
                  <CardContent className="text-center py-8">
                    <Settings className="w-12 h-12 mx-auto mb-3 text-slate-400 dark:text-slate-600" />
                    <p className="text-slate-600 dark:text-slate-400">Nenhuma regra customizada criada</p>
                    <p className="text-sm text-slate-500 dark:text-slate-500 mt-1">Crie regras para automatizar verificações</p>
                  </CardContent>
                </Card>
              )}
            </div>
          </TabsContent>

          <TabsContent value="historico" className="space-y-6 mt-6">
            <Card className="border border-slate-200 dark:border-white/5 shadow-2xl bg-white dark:bg-slate-900/40 backdrop-blur-xl overflow-hidden rounded-[2.5rem]">
              <CardHeader className="border-b border-slate-100 dark:border-slate-800">
                <CardTitle className="flex items-center gap-2 dark:text-slate-100">
                  <History className="w-5 h-5" />
                  Histórico de Auditorias
                </CardTitle>
              </CardHeader>
              <CardContent className="pt-6">
                <div className="space-y-3">
                  {historico.map(item => (
                    <div key={item.id} className="p-4 border dark:border-slate-800 rounded-lg bg-white dark:bg-slate-950">
                      <div className="flex items-start justify-between mb-2">
                        <div>
                          <div className="flex items-center gap-2">
                            <Badge variant={item.tipo_execucao === 'AUTOMATICA' ? 'default' : 'outline'}>
                              {item.tipo_execucao}
                            </Badge>
                            {item.escopo?.letra_produto && (
                              <span className="text-sm font-mono font-bold dark:text-slate-200">
                                {item.escopo.letra_produto}{item.escopo.ano}
                              </span>
                            )}
                          </div>
                          <p className="text-xs text-slate-500 dark:text-slate-500 mt-1">
                            {format(new Date(item.created_at), 'dd/MM/yyyy HH:mm', { locale: ptBR })} • {item.executado_por}
                          </p>
                        </div>
                        <Badge className={item.total_problemas > 0 ? 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400' : 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400'}>
                          {item.total_problemas} problema(s)
                        </Badge>
                      </div>
                      {item.total_problemas > 0 && (
                        <div className="text-sm text-slate-600 dark:text-slate-400 mt-2">
                          {item.problemas?.slice(0, 3).map((p, idx) => (
                            <div key={idx} className="text-xs">• {p.descricao}</div>
                          ))}
                        </div>
                      )}
                    </div>
                  ))}
                  {historico.length === 0 && (
                    <div className="text-center py-8">
                      <Clock className="w-12 h-12 mx-auto mb-3 text-slate-400 dark:text-slate-600" />
                      <p className="text-slate-600 dark:text-slate-400">Nenhuma auditoria executada ainda</p>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

// @ts-nocheck
import React, { useState, useMemo, useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { useSetor } from '@/components/context/SetorContext';
import { cn } from "@/lib/utils";
import { PremiumCard } from '@/components/ui/PremiumCard';
import { Button } from '@/components/ui/button';
import {
  Filter,
  Download,
  Activity,
  ArrowUpDown,
  Calendar,
  Layers,
  User,
  Package,
  TrendingUp,
  BarChart3,
  CalendarDays,
  Hash,
  ScanLine
} from "lucide-react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, PieChart, Pie, Cell, Legend } from 'recharts';
import FiltroBaixas from '@/components/baixas/FiltroBaixas';
import BaixaCard from '@/components/baixas/BaixaCard';
import { formatarNumeracao, extrairPrefixo } from '../components/formatacao/FormatacaoNumeracao';

export default function BaixasPage() {
  const { setorAtivo, isAdmin } = useSetor();
  const queryClient = useQueryClient();
  const [filtroData, setFiltroData] = useState('todos'); // hoje, semana, mes, todos, especifico
  const [dataEspecifica, setDataEspecifica] = useState('');
  const [filtros, setFiltros] = useState({
    clientes: [],
    codigos: [],
    operadores: [],
    tipos: [],
    deSetores: [],
    paraSetores: [],
    dataInicio: '',
    dataFim: '',
    consultores: [],
    setoresIndustriais: [],
    requisicao: '',
    pedido: '',
    op: '',
    chassi: ''
  });
  const [mostrarFiltros, setMostrarFiltros] = useState(false);

  // Buscar reservas do setor primeiro
  const { data: reservas = [] } = useQuery({
    queryKey: ['reservas-baixas', setorAtivo],
    queryFn: async () => {
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.ReservaLote.list();
      }
      return await rdsn.entities.ReservaLote.filter({ setor_id: setorAtivo });
    },
    enabled: !!setorAtivo
  });

  // Buscar baixas apenas das reservas do setor
  const { data: baixas = [], isLoading } = useQuery({
    queryKey: ['baixas', setorAtivo, reservas],
    queryFn: async () => {
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.BaixaLote.list('-created_at');
      }
      // Filtrar baixas pelas reservas do setor
      const reservaIds = reservas.map(r => r.id);
      if (reservaIds.length === 0) return [];
      const todas = await rdsn.entities.BaixaLote.list('-created_at');
      return todas.filter(b => reservaIds.includes(b.reserva_id));
    },
    enabled: !!setorAtivo && reservas.length >= 0
  });

  // Buscar setores
  const { data: setores = [] } = useQuery({
    queryKey: ['setores'],
    queryFn: () => rdsn.entities.Setor.list()
  });

  // Quando novas baixas chegam, sincronizar com PCP automaticamente
  useEffect(() => {
    if (baixas.length === 0) return;
    // Descobrir meses/anos únicos das baixas recentes e sincronizar
    const hoje = new Date();
    const mes = hoje.getMonth() + 1;
    const ano = hoje.getFullYear() % 100;
    rdsn.functions.invoke('sincronizarBaixasComPCP', { mes, ano })
      .then(() => {
        queryClient.invalidateQueries({ queryKey: ['pcp-producoes', mes, ano] });
      })
      .catch(() => { });
  }, [baixas.length]);

  // Subscription em tempo real para novas baixas
  useEffect(() => {
    const unsubscribe = rdsn.entities.BaixaLote.subscribe((event) => {
      if (event.type === 'create' || event.type === 'update') {
        queryClient.invalidateQueries({ queryKey: ['baixas'] });
        // Sincronizar com PCP no mês correto da baixa
        const hoje = new Date();
        const mes = hoje.getMonth() + 1;
        const ano = hoje.getFullYear() % 100;
        rdsn.functions.invoke('sincronizarBaixasComPCP', { mes, ano })
          .then(() => queryClient.invalidateQueries({ queryKey: ['pcp-producoes', mes, ano] }))
          .catch(() => { });
      }
    });
    return () => unsubscribe();
  }, []);

  // Enriquecer baixas com informações de reserva
  const baixasEnriquecidas = baixas.map(baixa => {
    const reserva = reservas.find(r => r.id === baixa.reserva_id);
    return { ...baixa, reserva };
  });

  // Aplicar filtros (somente se houver filtros ativos)
  const baixasFiltradas = useMemo(() => {
    return baixasEnriquecidas.filter(baixa => {
      // Filtro por data rápido
      const hoje = new Date();
      const hojeStr = hoje.toISOString().split('T')[0]; // YYYY-MM-DD

      if (filtroData === 'hoje') {
        const dataBaixaStr = baixa.created_at?.split('T')[0];
        if (dataBaixaStr !== hojeStr) return false;
      } else if (filtroData === 'semana') {
        const dataBaixa = baixa.created_at ? new Date(baixa.created_at) : null;
        if (!dataBaixa) return false;
        const inicioSemana = new Date(hoje);
        inicioSemana.setDate(hoje.getDate() - hoje.getDay());
        inicioSemana.setHours(0, 0, 0, 0);
        if (dataBaixa < inicioSemana) return false;
      } else if (filtroData === 'mes') {
        const dataBaixa = baixa.created_at ? new Date(baixa.created_at) : null;
        if (!dataBaixa) return false;
        const inicioMes = new Date(hoje.getFullYear(), hoje.getMonth(), 1);
        inicioMes.setHours(0, 0, 0, 0);
        if (dataBaixa < inicioMes) return false;
      } else if (filtroData === 'especifico' && dataEspecifica) {
        const dataBaixaStr = baixa.created_at?.split('T')[0];
        if (dataBaixaStr !== dataEspecifica) return false;
      }

      if (filtros.clientes?.length > 0 && !filtros.clientes.includes(baixa.reserva?.cliente)) return false;
      if (filtros.codigos?.length > 0 && !filtros.codigos.includes(baixa.reserva?.codigo_produto)) return false;
      if (filtros.operadores?.length > 0 && !filtros.operadores.includes(baixa.operador)) return false;
      if (filtros.tipos?.length > 0 && !filtros.tipos.includes(baixa.tipo)) return false;
      if (filtros.deSetores?.length > 0 && !filtros.deSetores.includes(baixa.de_setor)) return false;
      if (filtros.paraSetores?.length > 0 && !filtros.paraSetores.includes(baixa.para_setor)) return false;

      // Novos filtros industriais
      if (filtros.consultores?.length > 0 && !filtros.consultores.includes(baixa.consultor)) return false;
      if (filtros.setoresIndustriais?.length > 0 && !filtros.setoresIndustriais.includes(baixa.setor)) return false;
      if (filtros.requisicao && !baixa.requisicao?.toLowerCase().includes(filtros.requisicao.toLowerCase())) return false;
      if (filtros.pedido && !baixa.pedido?.toLowerCase().includes(filtros.pedido.toLowerCase())) return false;
      if (filtros.op && !baixa.op?.toLowerCase().includes(filtros.op.toLowerCase())) return false;
      if (filtros.chassi && !baixa.chassi?.toLowerCase().includes(filtros.chassi.toLowerCase())) return false;

      if (filtros.dataInicio && new Date(baixa.created_at) < new Date(filtros.dataInicio)) return false;
      if (filtros.dataFim && new Date(baixa.created_at) > new Date(filtros.dataFim)) return false;
      return true;
    });
  }, [baixasEnriquecidas, filtros, filtroData, dataEspecifica]);

  // Calcular estatísticas
  const stats = {
    totalBaixas: baixasFiltradas.length,
    totalUnidades: baixasFiltradas.reduce((sum, b) => sum + (b.quantidade || 0), 0),
    baixasManual: baixasFiltradas.filter(b => b.tipo === 'MANUAL').length,
    baixasColeta: baixasFiltradas.filter(b => b.tipo === 'COLETA').length
  };

  // Dados para gráficos
  const baixasPorTipo = [
    { name: 'Manual', value: stats.baixasManual, color: '#1e293b' },
    { name: 'Coleta', value: stats.baixasColeta, color: '#475569' }
  ];

  const baixasPorDia = baixasFiltradas.reduce((acc, baixa) => {
    const data = new Date(baixa.created_at).toLocaleDateString('pt-BR');
    const existing = acc.find(item => item.data === data);
    if (existing) {
      existing.quantidade += baixa.quantidade || 0;
    } else {
      acc.push({ data, quantidade: baixa.quantidade || 0 });
    }
    return acc;
  }, []).slice(0, 7).reverse();

  const baixasPorOperador = baixasFiltradas.reduce((acc, baixa) => {
    const operador = baixa.operador || 'Sem operador';
    const existing = acc.find(item => item.operador === operador);
    if (existing) {
      existing.quantidade += baixa.quantidade || 0;
    } else {
      acc.push({ operador, quantidade: baixa.quantidade || 0 });
    }
    return acc;
  }, []).sort((a, b) => b.quantidade - a.quantidade).slice(0, 5);

  const handleExportar = async () => {
    try {
      const ExcelJS = await import('exceljs');
      const workbook = new ExcelJS.Workbook();
      const worksheet = workbook.addWorksheet('Baixas de Produção');

      // Definir colunas
      worksheet.columns = [
        { header: 'Data', key: 'data', width: 20 },
        { header: 'Código Produto', key: 'codigo', width: 15 },
        { header: 'Cliente', key: 'cliente', width: 25 },
        { header: 'Intervalo', key: 'intervalo', width: 30 },
        { header: 'Quantidade', key: 'quantidade', width: 12 },
        { header: 'Tipo', key: 'tipo', width: 10 },
        { header: 'De Setor', key: 'de_setor', width: 12 },
        { header: 'Local Origem', key: 'local', width: 12 },
        { header: 'Para Setor', key: 'para_setor', width: 12 },
        { header: 'Local Destino', key: 'local_destino', width: 12 },
        { header: 'Operador', key: 'operador', width: 20 },
        { header: 'Consultor', key: 'consultor', width: 15 },
        { header: 'Setor Industrial', key: 'setor', width: 15 },
        { header: 'Requisição', key: 'requisicao', width: 15 },
        { header: 'Pedido', key: 'pedido', width: 15 },
        { header: 'OP', key: 'op', width: 12 },
        { header: 'Chassi', key: 'chassi', width: 20 },
        { header: 'Descrição', key: 'descricao', width: 30 }
      ];

      // Estilizar cabeçalho
      worksheet.getRow(1).font = { bold: true };
      worksheet.getRow(1).fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'FF1e293b' }
      };
      worksheet.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } };

      // Adicionar dados
      baixasFiltradas.forEach((baixa) => {
        const setor = setores.find(s => s.id === baixa.reserva?.setor_id);
        const setorNome = setor?.nome || '';
        const prefixo = baixa.reserva ? extrairPrefixo(baixa.reserva.codigo_completo) : '';
        const numInicial = baixa.reserva ? formatarNumeracao(baixa.numero_inicial, prefixo, setorNome) : '';
        const numFinal = baixa.reserva ? formatarNumeracao(baixa.numero_final, prefixo, setorNome) : '';
        const intervalo = baixa.reserva ? `${baixa.reserva.codigo_completo}${numInicial} - ${baixa.reserva.codigo_completo}${numFinal}` : '';

        worksheet.addRow({
          data: new Date(baixa.created_at).toLocaleString('pt-BR'),
          codigo: baixa.reserva?.codigo_produto || '',
          cliente: baixa.reserva?.cliente || '',
          intervalo,
          quantidade: baixa.quantidade || 0,
          tipo: baixa.tipo || '',
          de_setor: baixa.de_setor || '',
          local: baixa.local || '',
          para_setor: baixa.para_setor || '',
          local_destino: baixa.local_destino || '',
          operador: baixa.operador || '',
          consultor: baixa.consultor || '',
          setor: baixa.setor || '',
          requisicao: baixa.requisicao || '',
          pedido: baixa.pedido || '',
          op: baixa.op || '',
          chassi: baixa.chassi || '',
          descricao: baixa.descricao_item || ''
        });
      });

      // Gerar arquivo
      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `baixas-producao-${new Date().toISOString().split('T')[0]}.xlsx`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Erro ao exportar:', error);
      alert('Erro ao exportar dados');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 p-3 sm:p-6 transition-colors duration-300">
      <div className="max-w-7xl mx-auto space-y-4 sm:space-y-6">
        {/* Header Premium */}
        <div className="relative overflow-hidden rounded-[2.5rem] bg-white dark:bg-slate-900/40 backdrop-blur-3xl p-5 sm:p-6 shadow-2xl border border-slate-200 dark:border-white/5 mb-6">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_-20%,rgba(37,99,235,0.1),transparent)] pointer-events-none" />
          <div className="relative flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8">
            <div className="flex items-center gap-4 sm:gap-5">
