                                          }
                                        </p>
                                      </div>
                                      <Badge className="bg-slate-200 text-slate-800 dark:bg-slate-800 dark:text-slate-300 w-fit">
                                        {caixa.quantidade} peças
                                      </Badge>
                                    </motion.div>
                                  ))}
                                </div>

                                <Button
