      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.ReservaLote.filter(
          { status: { $in: ['RESERVADO', 'EM_PRODUCAO'] } },
          '-created_at',
          100
        );
      }
      return await rdsn.entities.ReservaLote.filter(
        { status: { $in: ['RESERVADO', 'EM_PRODUCAO'] }, setor_id: setorAtivo },
        '-created_at',
        100
      );
    },
    placeholderData: keepPreviousData,
    enabled: !!setorAtivo
  });

  const { data: produtos = [] } = useQuery({
    queryKey: ['produtos', setorAtivo, isAdmin],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.Produto.list();
      }
      return await rdsn.entities.Produto.filter({ setor_id: setorAtivo });
    },
    enabled: !!setorAtivo
  });

  React.useEffect(() => {
    const unsubRes = rdsn.entities.ReservaLote.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['reservas'] });
    });
    const unsubProd = rdsn.entities.Produto.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
    });
    const unsubBaixa = rdsn.entities.BaixaLote.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['reservas'] });
    });

    return () => {
      unsubRes();
      unsubProd();
      unsubBaixa();
    };
  }, [queryClient]);

  const createBaixaMutation = useMutation({
    mutationFn: async (data) => {
      const baixa = await rdsn.entities.BaixaLote.create(data);

      const reserva = reservas.find((r) => r.id === data.reserva_id);
      const novaBaixada = (reserva.quantidade_baixada || 0) + data.quantidade;
      const novoStatus = novaBaixada >= reserva.quantidade ? 'PRODUZIDO' : 'EM_PRODUCAO';

      await rdsn.entities.ReservaLote.update(data.reserva_id, {
        quantidade_baixada: novaBaixada,
        status: novoStatus
      });

      // Atualizar estoque se houver produto associado
      const produto = produtos.find((p) => p.letra_produto === reserva.letra_produto);
      if (produto) {
        const estoqueAnterior = produto.estoque_atual || 0;
        const estoqueNovo = estoqueAnterior + data.quantidade;

        await rdsn.entities.Produto.update(produto.id, {
          estoque_atual: estoqueNovo
        });

        // Registrar movimentação
        await rdsn.entities.MovimentacaoEstoque.create({
          produto_id: produto.id,
          tipo: 'PRODUCAO',
          quantidade: data.quantidade,
          quantidade_anterior: estoqueAnterior,
          quantidade_nova: estoqueNovo,
          referencia_id: baixa.id,
          referencia_tipo: 'BaixaLote',
          observacao: `Baixa de lote ${reserva.codigo_completo}`,
          celula: data.celula || '',
          operador: data.operador || ''
        });
      }

      await rdsn.entities.Auditoria.create({
        entidade: 'BaixaLote',
        entidade_id: baixa.id,
        acao: 'BAIXA_REGISTRADA',
        letra_produto: reserva.letra_produto,
        ano: reserva.ano,
        numero_inicial: data.numero_inicial,
        numero_final: data.numero_final,
        detalhes: JSON.stringify({ quantidade: data.quantidade, tipo: data.tipo })
      });

      return baixa;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['reservas-producao'] });
      setShowBaixa(false);
      setSelectedReserva(null);
      toast.success('Baixa registrada com sucesso!');
    },
    onError: (error) => {
      toast.error('Erro ao registrar baixa: ' + error.message);
    }
  });

  const stats = useMemo(() => {
    const emProducao = reservas.filter((r) => r.status === 'EM_PRODUCAO');
    const reservados = reservas.filter((r) => r.status === 'RESERVADO');
    const totalPendente = reservas.reduce((acc, r) => acc + ((r.quantidade || 0) - (r.quantidade_baixada || 0)), 0);

    return {
      emProducao: emProducao.length,
      reservados: reservados.length,
      totalPendente
    };
  }, [reservas]);

  const reservasFiltradas = useMemo(() => {
    let result = [...reservas];

    if (filters.cliente) {
      const search = filters.cliente.toLowerCase();
      result = result.filter((r) => r.cliente?.toLowerCase().includes(search));
    }

    if (filters.codigoProduto) {
      const search = filters.codigoProduto.toLowerCase();
      result = result.filter((r) => r.codigo_produto?.toLowerCase().includes(search));
    }

    if (filters.modelo) {
      const search = filters.modelo.toLowerCase();
      result = result.filter((r) => r.modelo?.toLowerCase().includes(search));
    }

    if (filters.status) {
      result = result.filter((r) => r.status === filters.status);
    }

    if (filters.dataInicio) {
      const dataInicio = new Date(filters.dataInicio);
      result = result.filter((r) => new Date(r.created_at) >= dataInicio);
    }

    if (filters.dataFim) {
      const dataFim = new Date(filters.dataFim);
      dataFim.setHours(23, 59, 59, 999);
      result = result.filter((r) => new Date(r.created_at) <= dataFim);
    }

    // Agrupamento Lógico Contínuo (Plano de Sequência)
    const gruposEmProducao = new Set(
      reservas.filter(r => r.status === 'EM_PRODUCAO').map(r => `${r.cliente || ''}-${r.codigo_completo}`)
    );

    const gruposMap = new Map();
    result.forEach(r => {
      // Criamos a chave única que define o que é uma "Sequência do mesmo cliente e produto"
      const key = `${r.cliente || ''}-${r.codigo_completo}-${r.codigo_produto || ''}`;
      if (!gruposMap.has(key)) {
        gruposMap.set(key, {
          key,
          cliente: r.cliente || '',
          prefixo: r.codigo_completo,
          // Se qualqer item da familia geral do cliente/prefixo estiver em produção na base inteira, prioriza
          temProducao: gruposEmProducao.has(`${r.cliente || ''}-${r.codigo_completo}`),
          itens: []
        });
      }
      gruposMap.get(key).itens.push(r);
    });

    const gruposArray = Array.from(gruposMap.values());

    // 1. Grupos que têm itens já em produção vêm primeiro, depois ordem alfabética Cliente > Prefixo
    gruposArray.sort((a, b) => {
      if (a.temProducao && !b.temProducao) return -1;
      if (!a.temProducao && b.temProducao) return 1;

      if (a.cliente < b.cliente) return -1;
      if (a.cliente > b.cliente) return 1;

      if (a.prefixo < b.prefixo) return -1;
      if (a.prefixo > b.prefixo) return 1;

      return 0;
    });

    // Combina e ordena os itens internamente
    const flattenedResult = [];
    const coresDisponiveis = [
      { bg: "bg-emerald-500 text-white", shadow: "shadow-emerald-500/40", ring: "ring-emerald-500/20" },
      { bg: "bg-blue-500 text-white", shadow: "shadow-blue-500/40", ring: "ring-blue-500/20" },
      { bg: "bg-purple-500 text-white", shadow: "shadow-purple-500/40", ring: "ring-purple-500/20" },
      { bg: "bg-amber-500 text-white", shadow: "shadow-amber-500/40", ring: "ring-amber-500/20" },
      { bg: "bg-pink-500 text-white", shadow: "shadow-pink-500/40", ring: "ring-pink-500/20" },
      { bg: "bg-teal-500 text-white", shadow: "shadow-teal-500/40", ring: "ring-teal-500/20" },
      { bg: "bg-orange-500 text-white", shadow: "shadow-orange-500/40", ring: "ring-orange-500/20" },
    ];

    let colorIndex = 0;
    gruposArray.forEach(g => {
      const colorData = coresDisponiveis[colorIndex % coresDisponiveis.length];
      colorIndex++;

      // Ordena itens do grupo
      g.itens.sort((a, b) => {
        if (a.status === 'EM_PRODUCAO' && b.status !== 'EM_PRODUCAO') return -1;
        if (a.status !== 'EM_PRODUCAO' && b.status === 'EM_PRODUCAO') return 1;

        const isDesc = a.sequencia_decrescente === true;

        if (isDesc) return b.numero_final - a.numero_final;
        return a.numero_inicial - b.numero_inicial;
      });

      // Adiciona metadados de UI nos itens
      g.itens.forEach((item, innerIdx) => {
        flattenedResult.push({
          ...item,
          _uiSeqIndex: innerIdx + 1,
          _uiColor: colorData,
          _uiIsFirstOfGroup: innerIdx === 0
        });
      });
    });

    return flattenedResult;
  }, [reservas, filters, produtos]);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 p-6 transition-colors duration-300">
      <div className="max-w-7xl mx-auto space-y-6">
        <SetorReadonlyBanner />
        {/* Header */}
        {/* Header Premium */}
        <div className="relative overflow-hidden rounded-[2.5rem] bg-white dark:bg-slate-900/40 backdrop-blur-3xl p-5 sm:p-6 shadow-2xl border border-slate-200 dark:border-white/5">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_-20%,rgba(37,99,235,0.1),transparent)] pointer-events-none" />
          <div className="relative flex flex-col md:flex-row justify-between items-start md:items-center gap-8">
            <div className="flex items-center gap-4 sm:gap-5">
              <div className="w-16 h-16 sm:w-14 sm:h-14 bg-gradient-to-br from-blue-600 to-indigo-400 rounded-[2rem] flex items-center justify-center shadow-[0_0_30px_rgba(37,99,235,0.3)] transition-all hover:scale-105 active:scale-95 group cursor-pointer">
                <ScanLine className="w-8 h-8 sm:w-6 sm:h-6 text-white group-hover:rotate-12 transition-transform" />
              </div>
              <div className="space-y-1">
                <h1 className="text-2xl sm:text-3xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter leading-none">
                  Fluxo de <span className="text-blue-600 dark:text-blue-400">Produção</span>
                </h1>
                <p className="text-xs sm:text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em] italic opacity-80">Industrial Control Hub • Tempo Real</p>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
              <div className="flex bg-slate-100 dark:bg-slate-950/60 p-1.5 rounded-[1.5rem] border border-slate-200 dark:border-white/10 backdrop-blur-xl">
                <button
                  onClick={() => { setModoProducaoDia(false); localStorage.setItem('modoProducaoDia', 'false'); }}
                  className={cn(
                    "flex items-center gap-2 px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all",
                    !modoProducaoDia
                      ? "bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-xl transform scale-[1.02]"
                      : "text-slate-500 dark:text-slate-500 hover:text-slate-900 dark:hover:text-slate-300"
                  )}
                >
                  <ScanLine className="w-3.5 h-3.5" />
                  Operação Global
                </button>
                <button
                  onClick={() => { setModoProducaoDia(true); localStorage.setItem('modoProducaoDia', 'true'); }}
                  className={cn(
                    "flex items-center gap-2 px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all",
                    modoProducaoDia
                      ? "bg-blue-600 text-white shadow-lg shadow-blue-500/30 transform scale-[1.02]"
                      : "text-slate-500 dark:text-slate-500 hover:text-slate-900 dark:hover:text-slate-300"
                  )}
                >
                  <CalendarDays className="w-3.5 h-3.5" />
                  Meta do Dia
                </button>
              </div>
              <Button
                onClick={() => navigate(createPageUrl('Baixas'))}
                className="h-14 px-8 rounded-[1.5rem] bg-slate-950 dark:bg-blue-600 text-white font-black uppercase text-[10px] tracking-[0.2em] gap-3 shadow-2xl transition-all hover:scale-[1.02] active:scale-95 border-0"
              >
                <Activity className="w-4 h-4" />
                Histórico
              </Button>
            </div>
          </div>
        </div>

        {modoProducaoDia ? (
          /* === MODO PRODUÇÃO DO DIA === */
          <ModoProducaoDia reservas={reservas} produtos={produtos} setorInfo={setorInfo} />
        ) : (
          /* === MODO NORMAL === */
          <>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <PremiumCard title="Em Produção" icon={ScanLine} className="bg-blue-600/5">
                <h3 className="text-4xl font-black text-slate-900 dark:text-white italic tracking-tighter leading-none">{stats.emProducao}</h3>
                <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest italic opacity-60 mt-2">lotes ativos na fila</p>
              </PremiumCard>

              <PremiumCard title="Reservados" icon={Package} className="bg-amber-600/5">
                <h3 className="text-4xl font-black text-slate-900 dark:text-white italic tracking-tighter leading-none">{stats.reservados}</h3>
                <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest italic opacity-60 mt-2">lotes aguardando início</p>
              </PremiumCard>

              <PremiumCard title="Total Pendente" icon={Activity} className="bg-emerald-600/5">
                <h3 className="text-4xl font-black text-slate-900 dark:text-white italic tracking-tighter leading-none">{stats.totalPendente.toLocaleString()}</h3>
                <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest italic opacity-60 mt-2">unidades a coletar</p>
              </PremiumCard>
            </div>

            <PremiumCard title="Fila Industrial de Lotes" icon={ScanLine} noPadding>
              <div className="bg-slate-50/50 dark:bg-slate-950/30 p-4 border-b border-slate-200 dark:border-white/5">
                <FiltroProducaoAvancado
                  filters={filters}
                  setFilters={setFilters}
                  reservas={reservas}
                  onClear={() => setFilters({
                    cliente: '',
                    codigoProduto: '',
                    modelo: '',
                    status: '',
                    dataInicio: '',
                    dataFim: ''
                  })} />
              </div>
              {isLoading ?
                <div className="p-8 text-center text-slate-500 dark:text-slate-400">Carregando...</div> :
                reservas.length === 0 ?
                  <div className="p-8 text-center text-slate-500 dark:text-slate-400">Nenhum lote disponível</div> :
                  reservasFiltradas.length === 0 ?
                    <div className="p-8 text-center text-slate-500 dark:text-slate-400">Nenhum lote encontrado com os filtros aplicados</div> :

                    <div className="divide-y divide-slate-100 dark:divide-slate-800/10">
                      {reservasFiltradas.map((reserva) => {
                        const restante = (reserva.quantidade || 0) - (reserva.quantidade_baixada || 0);
                        const progresso = reserva.quantidade > 0 ?
                          Math.round((reserva.quantidade_baixada || 0) / reserva.quantidade * 100) :
                          0;

                        return (
                          <React.Fragment key={reserva.id}>
                            {reserva._uiIsFirstOfGroup && (
                              <div className="h-1 w-full bg-slate-100 dark:bg-slate-800/10" />
                            )}
                            <div className="flex relative items-stretch border-b border-slate-100 dark:border-slate-800/10 last:border-0 hover:bg-slate-50 dark:hover:bg-blue-600/5 group">
                              <div className="w-12 sm:w-16 flex-shrink-0 flex flex-col items-center pt-10 sm:pt-14 border-r border-slate-100 dark:border-transparent z-10 transition-colors">
                                <div className={cn(
                                  "w-8 h-8 rounded-full flex items-center justify-center font-black text-xs shadow-lg transition-all",
                                  reserva._uiSeqIndex === 1
                                    ? `${reserva._uiColor.bg} ${reserva._uiColor.shadow} ${reserva._uiColor.ring} ring-4 z-20 scale-110`
                                    : reserva._uiSeqIndex <= 3
                                      ? `${reserva._uiColor.bg} ${reserva._uiColor.shadow} z-10`
                                      : "bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400"
                                )}>
                                  {reserva._uiSeqIndex}º
                                </div>
                              </div>

                              <div className="flex-1 p-6 sm:p-10 relative overflow-hidden">
                                <div className="absolute top-0 left-0 w-1.5 h-0 group-hover:h-full bg-blue-600 transition-all duration-500" />
                                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                                  <div className="flex items-start gap-6 flex-1 min-w-0">
                                    <div className="w-16 h-16 sm:w-14 sm:h-14 bg-slate-950 dark:bg-white text-white dark:text-slate-900 rounded-[1.5rem] flex items-center justify-center font-black text-3xl shadow-2xl transition-all group-hover:rotate-6 group-hover:scale-110 shrink-0">
                                      {reserva.codigo_completo?.substring(0, 1)}
                                    </div>

                                    <div className="flex-1 space-y-4 min-w-0">
                                      <div className="flex flex-wrap items-center gap-3">
                                        {/* Título do produto truncado — máx 45% do espaço */}
                                        <span className="text-xl font-black text-slate-900 dark:text-white tracking-tighter leading-none truncate uppercase italic max-w-[45vw] lg:max-w-[28vw]" title={reserva.modelo}>
                                          {reserva.modelo}
                                        </span>
                                        <Badge variant="outline" className="bg-slate-100 dark:bg-slate-800 border-0 text-slate-500 dark:text-slate-400 font-black text-[10px] uppercase px-3 py-1 rounded-full tracking-widest shrink-0">
                                          {reserva.codigo_produto}
                                        </Badge>
                                        <StatusBadge status={reserva.status} />
                                      </div>

                                      {/* Grid 3 colunas flexível: cliente | range | botões de ação */}
                                      <div className="grid grid-cols-1 sm:grid-cols-[minmax(0,1fr)_minmax(0,1.8fr)_auto] gap-4 items-end">
                                        <div className="space-y-1 min-w-0">
                                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] italic">Cliente de Destino</p>
                                          <p className="text-base font-bold text-slate-700 dark:text-slate-300 truncate uppercase tracking-tight" title={reserva.cliente || 'OCASIONAL'}>
                                            {reserva.cliente || 'OCASIONAL'}
                                          </p>
                                        </div>

                                        <div className="space-y-1 min-w-0">
                                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] italic">Range de Identificação</p>
                                          <div className="px-2 py-1.5 bg-slate-100 dark:bg-slate-950/60 rounded-lg border border-slate-200 dark:border-white/5 break-all sm:break-normal">
                                            <p className="text-xs font-black text-slate-900 dark:text-white tracking-tight">
                                              {reserva.codigo_completo}{formatarNumeracao(reserva.numero_inicial, extrairPrefixo(reserva.codigo_completo), setorAtivo)} – {reserva.codigo_completo}{formatarNumeracao(reserva.numero_final, extrairPrefixo(reserva.codigo_completo), setorAtivo)}
                                            </p>
                                          </div>
                                        </div>

                                        {/* Botões de ação — ficam na 3ª coluna do grid */}
                                        <div className="flex flex-col gap-2 shrink-0">
                                          {(() => {
                                            const isInvertida = reserva.sequencia_decrescente === true;
                                            return (
                                              <>
                                                {isInvertida && (
                                                  <Badge className="bg-indigo-500/10 text-indigo-500 border-0 font-black text-[9px] uppercase tracking-widest py-1 justify-center rounded-xl">
                                                    NUMERAÇÃO REVERSA
                                                  </Badge>
                                                )}
                                                <Button
                                                  onClick={() => {
                                                    setSelectedReserva(reserva);
                                                    setShowBaixa(true);
                                                  }}
                                                  disabled={isReadonly}
                                                  className="h-11 px-6 rounded-2xl bg-slate-900 dark:bg-blue-600 hover:bg-slate-800 dark:hover:bg-blue-700 text-white font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-500/10 transition-all active:scale-95 disabled:grayscale w-full"
                                                >
                                                  <ScanLine className="w-4 h-4 mr-2" />
                                                  Coletar Baixa
                                                </Button>
                                              </>
                                            );
                                          })()}
                                        </div>
                                      </div>
                                    </div>
                                  </div>

                                  {/* Bloco direito: Fluxo de Entrega + A Produzir */}
                                  <div className="flex flex-wrap items-center gap-6 lg:gap-10 shrink-0">
                                    <div className="space-y-3">
                                      <div className="flex justify-between items-end gap-4">
                                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] italic leading-none">Fluxo de Entrega</span>
                                        <span className="text-xl font-black text-blue-500 italic tracking-tighter">{progresso}%</span>
                                      </div>
                                      <div className="h-2.5 w-36 bg-slate-100 dark:bg-slate-950 rounded-full overflow-hidden border border-slate-200 dark:border-white/5">
                                        <div
                                          className="h-full bg-blue-600 rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(37,99,235,0.4)]"
                                          style={{ width: `${progresso}%` }} />
                                      </div>
                                      <p className="text-[10px] font-black text-center text-slate-500 dark:text-slate-400 uppercase tracking-widest opacity-60">
                                        {(reserva.quantidade_baixada || 0).toLocaleString()} / {reserva.quantidade?.toLocaleString()} un
                                      </p>
                                    </div>

                                    <div className="text-right space-y-1">
                                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] italic leading-none">A Produzir</span>
                                      <p className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter leading-none italic">{restante.toLocaleString()}</p>
                                    </div>
                                  </div>
                                </div>
                              </div>
                            </div>
                          </React.Fragment>
                        );
                      })}
                    </div>
              }
            </PremiumCard>

            {/* Baixa Dialog Premium Industrial */}
            <Dialog open={showBaixa} onOpenChange={setShowBaixa}>
              <DialogContent className="max-w-5xl h-[95vh] flex flex-col p-0 overflow-hidden border-0 bg-white dark:bg-slate-950 rounded-none sm:rounded-[3rem] shadow-[0_0_80px_rgba(0,0,0,0.5)]">

                {/* Header Industrial */}
                <div className="relative bg-slate-950 px-10 py-8 shrink-0 overflow-hidden">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 rounded-full blur-[80px] -mr-32 -mt-32" />

                  <DialogHeader className="relative z-10">
                    <div className="flex items-center gap-4 mb-3">
                      <div className="w-12 h-12 rounded-2xl bg-blue-600 flex items-center justify-center shadow-lg shadow-blue-600/20">
                        <ScanLine className="w-6 h-6 text-white" />
                      </div>
                      <DialogTitle className="text-3xl font-black text-white italic uppercase tracking-tighter leading-none">
                        Consumo de <span className="text-blue-500">Numerários</span>
                      </DialogTitle>
                    </div>
                    <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] flex items-center gap-2 italic">
                      Coleta • Lote {selectedReserva?.codigo_completo}
                    </p>
                  </DialogHeader>

                  <Button
                    variant="ghost"
                    onClick={() => setShowBaixa(false)}
                    className="absolute top-8 right-8 text-slate-500 hover:text-white hover:bg-white/10 rounded-full w-12 h-12 p-0 transition-all"
                  >
                    <X className="w-8 h-8" />
                  </Button>
                </div>

                <div className="flex-1 overflow-y-auto min-h-0 custom-scrollbar scrollbar-thin scrollbar-thumb-slate-300 dark:scrollbar-thumb-slate-700">
                  <div className="p-6 sm:p-10">
                    {selectedReserva && (
                      <BaixaForm
                        reserva={selectedReserva}
                        setorInfo={setorInfo}
                        onSubmit={(data) => createBaixaMutation.mutate(data)}
                        isLoading={createBaixaMutation.isPending}
                        onCancel={() => {
                          setShowBaixa(false);
                          setSelectedReserva(null);
                        }}
                      />
                    )}
                  </div>
                </div>

                <div className="px-10 py-4 shrink-0 bg-slate-50 dark:bg-black/40 border-t border-slate-100 dark:border-white/5 flex items-center justify-center gap-2 opacity-30">
                  <div className="w-1.5 h-1.5 rounded-full bg-blue-500" />
                  <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest italic">Sistema de Rastreabilidade Matrix Ativo</span>
                </div>
              </DialogContent>
            </Dialog>
          </>
        )}
      </div>
    </div>
  );
}

// @ts-nocheck
import React, { useState, useMemo, useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { Package, TrendingUp, AlertTriangle, CircleCheck, Clock, BarChart3, XCircle, PlayCircle, Zap, Activity, Users, Target, CheckCircle2 } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import ProducaoChart from '../components/charts/ProducaoChart';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { PremiumCard } from '@/components/ui/PremiumCard';
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { LoadingPage } from "@/components/ui/loading-spinner";
import { PageTransition, SlideIn } from "@/components/ui/page-transition";
import { useSetor } from '@/components/context/SetorContext';
import { cn } from "@/lib/utils";

export default function Dashboard() {
  const [filtroAno, setFiltroAno] = useState(new Date().getFullYear() % 100);
  const { setorAtivo, isAdmin } = useSetor();
  const queryClient = useQueryClient();

  useEffect(() => {
    const unsubReservas = rdsn.entities.ReservaLote.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['reservas'] });
    });
    const unsubSeq = rdsn.entities.SequenciaAnual.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['sequencias'] });
    });
    const unsubMov = rdsn.entities.MovimentacaoEstoque.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['movimentacoes-dashboard'] });
    });
    const unsubOps = rdsn.entities.PCPOrdemProducao.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['pcp-ops-dashboard'] });
    });
    const unsubProd = rdsn.entities.PCPProducaoDiaria.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['pcp-producoes-dashboard'] });
    });
    const unsubAud = rdsn.entities.Auditoria.subscribe(() => {
      queryClient.invalidateQueries({ queryKey: ['auditoria-dashboard'] });
    });

    return () => {
      if (unsubReservas) unsubReservas();
      if (unsubSeq) unsubSeq();
      if (unsubMov) unsubMov();
      if (unsubOps) unsubOps();
      if (unsubProd) unsubProd();
      if (unsubAud) unsubAud();
    };
  }, [queryClient]);

  const { data: reservas = [], isLoading: loadingReservas } = useQuery({
    queryKey: ['reservas', setorAtivo, isAdmin],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.ReservaLote.list('-created_at', 1000);
      }
      return await rdsn.entities.ReservaLote.filter({ setor_id: setorAtivo }, '-created_at', 1000);
    },
    enabled: !!setorAtivo
  });

  const { data: sequencias = [], isLoading: loadingSequencias } = useQuery({
    queryKey: ['sequencias', setorAtivo, isAdmin],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.SequenciaAnual.list();
      }
      return await rdsn.entities.SequenciaAnual.filter({ setor_id: setorAtivo });
    },
    enabled: !!setorAtivo
  });
  const { data: movimentacoes = [], isLoading: loadingMovimentacoes } = useQuery({
    queryKey: ['movimentacoes-dashboard', setorAtivo, isAdmin],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && (setorAtivo === 'ALL' || setorAtivo === 'TODOS')) {
        return await rdsn.entities.MovimentacaoEstoque.list('-created_at', 500);
      }

      // Filtrar por produtos do setor
      const produtos = await rdsn.entities.Produto.filter({ setor_id: setorAtivo });
      const produtoIds = produtos.map(p => p.id);
      const todasMov = await rdsn.entities.MovimentacaoEstoque.list('-created_at', 500);
      return todasMov.filter(m => (m.produto_id && produtoIds.includes(m.produto_id)) || (m.setor_id === setorAtivo));
    },
    enabled: !!setorAtivo
  });


  const { data: pcpOps = [] } = useQuery({
    queryKey: ['pcp-ops-dashboard', setorAtivo, filtroAno],
    queryFn: async () => {
      if (!setorAtivo || setorAtivo === 'ALL') {
        return rdsn.entities.PCPOrdemProducao.filter({ ano: filtroAno }, '-created_at', 2000);
      }
      return rdsn.entities.PCPOrdemProducao.filter({ setor_id: setorAtivo, ano: filtroAno }, '-created_at', 2000);
    },
    enabled: !!setorAtivo
  });

  const { data: pcpProducoes = [] } = useQuery({
    queryKey: ['pcp-producoes-dashboard', setorAtivo, filtroAno],
    queryFn: async () => {
      if (!setorAtivo || setorAtivo === 'ALL') {
        return rdsn.entities.PCPProducaoDiaria.filter({ ano: filtroAno }, '-created_at', 5000);
      }
      return rdsn.entities.PCPProducaoDiaria.filter({ setor_id: setorAtivo, ano: filtroAno }, '-created_at', 5000);
    },
    enabled: !!setorAtivo
  });

  const { data: auditoria = [], isLoading: loadingAuditoria } = useQuery({
    queryKey: ['auditoria-dashboard', setorAtivo, isAdmin],
    queryFn: async () => {
      if (!setorAtivo) return [];
      if (isAdmin && setorAtivo === 'ALL') {
        return await rdsn.entities.Auditoria.list('-created_at', 50);
      }

      // Filtrar por produtos do setor
      const seqs = await rdsn.entities.SequenciaAnual.filter({ setor_id: setorAtivo });
      const letras = [...new Set(seqs.map(s => s.letra_produto))];
      const todasAud = await rdsn.entities.Auditoria.list('-created_at', 50);
      return todasAud.filter(a => letras.includes(a.letra_produto));
    },
    enabled: !!setorAtivo
  });

  const stats = useMemo(() => {
    const hoje = new Date().toDateString();

    // Variáveis de acumulação
    let totalReservado = 0;
    let totalProduzido = 0;
    let emProducao = 0;
    let pendentes = 0;
    let totalAnoAnterior = 0;
    let reservasAtivasCount = 0;
    const countStatus = {};
    const countPorCliente = {};
    const countPorMes = {};
    const lotesNaoFinalizados = [];

    // Passagem única pelas reservas (1000 items O(N))
    for (let i = 0; i < reservas.length; i++) {
        const r = reservas[i];

        // Verifica o ano
        if (r.ano === (filtroAno - 1)) {
            totalAnoAnterior += (r.quantidade || 0);
        }

        if (!filtroAno || r.ano === filtroAno) {
            const qtd = r.quantidade || 0;
            const qtdBaixada = r.quantidade_baixada || 0;
            const status = r.status || 'INDEFINIDO';
            const m = r.mes_producao || 'Sem Mês';
            const cli = r.cliente || 'Desconhecido';

            totalReservado += qtd;
            totalProduzido += qtdBaixada;

            if (status === 'EM_PRODUCAO') emProducao++;
            if (status === 'RESERVADO') pendentes++;

            countStatus[status] = (countStatus[status] || 0) + 1;

            if (['RESERVADO', 'EM_PRODUCAO'].includes(status)) {
                reservasAtivasCount++;
                if (qtdBaixada < qtd) {
                    lotesNaoFinalizados.push(r);
                }
            }

            if (!countPorCliente[cli]) countPorCliente[cli] = { reservado: 0, produzido: 0 };
            countPorCliente[cli].reservado += qtd;
            countPorCliente[cli].produzido += qtdBaixada;

            if (!countPorMes[m]) countPorMes[m] = { reservado: 0, produzido: 0 };
            countPorMes[m].reservado += qtd;
            countPorMes[m].produzido += qtdBaixada;
        }
    }

    // Produção do dia (movimentacoes) - O(N)
    let producaoDia = 0;
    const gargalosMap = {};
    for (let i = 0; i < movimentacoes.length; i++) {
        const m = movimentacoes[i];
        if (m.tipo === 'PRODUCAO') {
            const qtd = m.quantidade || 0;
            if (new Date(m.created_at).toDateString() === hoje) {
                producaoDia += qtd;
            }
            if (m.celula) {
                gargalosMap[m.celula] = (gargalosMap[m.celula] || 0) + qtd;
            }
        }
    }

    const gargalos = Object.entries(gargalosMap)
        .sort((a, b) => b[1] - a[1]) // highest first
        .slice(0, 3)
        .map(([celula, quantidade]) => ({ celula, quantidade }));

    // Alertas recentes (auditoria) - O(N)
    const ultimas24h = new Date(Date.now() - 24 * 60 * 60 * 1000);
    const alertasRecentes = [];
    for (let i = 0; i < auditoria.length; i++) {
        const a = auditoria[i];
        if (new Date(a.created_at) >= ultimas24h && ['RESERVA_CANCELADA', 'ANO_ENCERRADO'].includes(a.acao)) {
            alertasRecentes.push(a);
        }
    }

    // KPIs do PCP (ops) - O(N)
    let totalOPsPrevistas = 0;
    let opsComAtraso = 0;
    for (let i = 0; i < pcpOps.length; i++) {
        const op = pcpOps[i];
        if (op.ano === filtroAno) {
            const qt = op.quantidade_total || 0;
            const qr = op.realizado || 0;
            totalOPsPrevistas += qt;
            if (op.status === 'Ativo' && qt > 0 && qr < qt) {
                opsComAtraso++;
            }
        }
    }

    let totalOPsRealizadas = 0;
    for (let i = 0; i < pcpProducoes.length; i++) {
        totalOPsRealizadas += (pcpProducoes[i].realizado || 0);
    }

    // --- SCORE DE RISCO ---
    const taxaProducao = totalReservado > 0 ? (totalProduzido / totalReservado) * 100 : 0;
    let riskScore = 20;
    if (taxaProducao < 30 && reservasAtivasCount > 10) riskScore = 85;
    else if (taxaProducao < 50 && reservasAtivasCount > 5) riskScore = 60;
    else if (taxaProducao < 70) riskScore = 40;

    let riskLevel = 'low';
    if (riskScore > 70) riskLevel = 'high';
    else if (riskScore > 40) riskLevel = 'medium';

    const riskConfig = {
      low: { bg: 'bg-emerald-500', text: 'text-emerald-500', label: 'BAIXO' },
      medium: { bg: 'bg-amber-500', text: 'text-amber-500', label: 'MÉDIO' },
      high: { bg: 'bg-red-500', text: 'text-red-500', label: 'ALTO' }
    }[riskLevel];

    // --- TOP CLIENTES ---
    const topClientes = Object.entries(countPorCliente)
      .sort(([, a], [, b]) => b.reservado - a.reservado)
      .slice(0, 5)
      .map(([name, data]) => ({ name, ...data }));

    const totalVolTop3 = topClientes.slice(0, 3).reduce((acc, c) => acc + c.reservado, 0);
    const top3Percentual = totalReservado > 0 ? Math.round((totalVolTop3 / totalReservado) * 100) : 0;

    // --- COMPARATIVO ---
    const crescimento = totalAnoAnterior > 0 ? Math.round(((totalReservado - totalAnoAnterior) / totalAnoAnterior) * 100) : 0;

    // --- DADOS MENSAIS ---
    const dadosMensais = Object.entries(countPorMes).map(([name, data]) => ({
      name,
      ...data,
      eficiencia: data.reservado > 0 ? Math.round((data.produzido / data.reservado) * 100) : 0
    }));

    const eficienciaMedia = dadosMensais.length > 0
      ? Math.round(dadosMensais.reduce((acc, m) => acc + m.eficiencia, 0) / dadosMensais.length)
      : 0;

    return {
      producaoDia,
      alertasRecentes,
      lotesNaoFinalizados,
      totalReservado,
      totalProduzido,
      emProducao,
      pendentes,
      statusCount: countStatus,
      topClientes,
      top3Percentual,
      crescimento,
      dadosMensais,
      eficienciaMedia,
      riskScore,
      riskLevel,
      riskConfig,
      totalOPsPrevistas,
      totalOPsRealizadas,
      opsComAtraso,
      percentualProduzido: totalReservado > 0 ? Math.round((totalProduzido / totalReservado) * 100) : 0,
      taxaProducao: Math.round(taxaProducao),
      gargalos
    };
  }, [reservas, movimentacoes, auditoria, pcpOps, pcpProducoes, filtroAno]);

  const anosDisponiveis = useMemo(() => {
    return [...new Set(sequencias.filter(s => s && s.ano).map(s => s.ano))]
      .sort((a, b) => Number(b) - Number(a));
  }, [sequencias]);

  const isLoading = loadingReservas || loadingSequencias || loadingMovimentacoes || loadingAuditoria;

  if (isLoading) {
    return <LoadingPage message="Carregando dashboard..." />;
  }

  return (
    <PageTransition>
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 p-3 sm:p-4 md:p-6 transition-colors duration-300">
        <div className="max-w-7xl mx-auto space-y-4 sm:space-y-6">
          {/* Header Minimalista */}
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
            <div>
              <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                <Activity className="w-6 h-6 text-blue-600 dark:text-blue-500" />
                Dashboard PCP
              </h1>
              <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Visão geral da produção e indicadores</p>
            </div>

            <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 rounded-lg border border-slate-200 dark:border-slate-800 shadow-sm">
              <div className="px-3 py-1.5 border-r border-slate-200 dark:border-slate-800 flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                <span className="text-xs font-semibold text-slate-600 dark:text-slate-300">Ano Base</span>
              </div>
              <Select value={filtroAno?.toString()} onValueChange={(v) => setFiltroAno(Number(v))}>
                <SelectTrigger className="w-[120px] h-8 bg-transparent border-0 text-slate-900 dark:text-white font-semibold text-sm focus:ring-0">
                  <SelectValue placeholder="Ano" />
                </SelectTrigger>
                <SelectContent>
                  {anosDisponiveis.map(ano => (
                    <SelectItem key={ano} value={ano.toString()}>{ano}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
            <PremiumCard title="OPs Previstas" icon={Target} iconColor="#3b82f6">
              <p className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter italic">{stats.totalOPsPrevistas.toLocaleString()}</p>
              <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest italic mt-1">unidades planejadas</p>
            </PremiumCard>
            <PremiumCard title="OPs Realizadas" icon={CircleCheck} iconColor="#059669">
              <p className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter italic">{stats.totalOPsRealizadas.toLocaleString()}</p>
              <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest italic mt-1">{stats.totalOPsPrevistas > 0 ? Math.round((stats.totalOPsRealizadas / stats.totalOPsPrevistas) * 100) : 0}% do plano</p>
            </PremiumCard>
            <PremiumCard title="Em Produção" icon={PlayCircle} iconColor="#6366f1">
              <p className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter italic">{stats.emProducao}</p>
              <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest italic mt-1">lotes em operação</p>
            </PremiumCard>
            <PremiumCard title="Alertas (24h)" icon={AlertTriangle} iconColor={stats.alertasRecentes.length > 5 ? "#e11d48" : "#64748b"} badge={stats.alertasRecentes.length > 0 && <Badge className="bg-red-500 text-white border-0 px-2 py-0 h-5 text-[9px] font-black uppercase italic">Alerta</Badge>}>
              <p className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter italic">{stats.alertasRecentes.length}</p>
              <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest italic mt-1">eventos críticos</p>
            </PremiumCard>
          </div>

          {/* Score de Risco e Eficiência (Dashboard Executivo) */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Risk Score Card */}
            <PremiumCard title="Score de Risco" icon={Activity} iconColor="#ef4444" className="bg-slate-900 border-0 shadow-2xl overflow-hidden relative lg:col-span-1 rounded-[2.5rem]">
              <div className="absolute inset-0 bg-grid-white/[0.03] bg-[size:16px_16px]" />
              <div className="relative z-10 flex flex-col justify-center h-full">
                <div className="flex items-baseline gap-4 mt-4">
                  <span className="text-7xl font-black text-white italic tracking-tighter">{stats.riskScore}</span>
                  <Badge className={cn("px-3 py-1 rounded-full text-[10px] font-black border text-center uppercase tracking-widest",
                    stats.riskLevel === 'low' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' :
                      stats.riskLevel === 'medium' ? 'bg-amber-500/20 text-amber-400 border-amber-500/30' :
                        'bg-red-500/20 text-red-400 border-red-500/30'
                  )}>
                    {stats.riskConfig.label}
                  </Badge>
                </div>
                <div className="mt-8 pt-6 border-t border-white/10 space-y-3">
                  <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase italic tracking-widest">
                    <span>Eficiência Média</span>
                    <span className="text-white">{stats.eficienciaMedia}%</span>
                  </div>
                  <div className="h-2 bg-white/5 rounded-full overflow-hidden border border-white/5 shadow-inner">
                    <div className="h-full bg-gradient-to-r from-blue-600 to-indigo-500 shadow-[0_0_15px_rgba(59,130,246,0.6)] transition-all duration-1000" style={{ width: `${stats.eficienciaMedia}%` }} />
                  </div>
                </div>
              </div>
            </PremiumCard>

            <PremiumCard title="Eficiência de Produção" icon={TrendingUp} className="lg:col-span-2">
              <div className="h-56 mt-4">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={stats.dadosMensais}>
                    <XAxis dataKey="name" tick={{ fill: '#64748b', fontSize: 10, fontWeight: 'bold' }} axisLine={false} tickLine={false} />
                    <Tooltip
                      contentStyle={{ backgroundColor: '#0f172a', border: 'none', borderRadius: '12px', color: '#fff', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                      cursor={{ fill: 'rgba(255,255,255,0.05)' }}
                    />
                    <Bar dataKey="eficiencia" fill="#3b82f6" radius={[6, 6, 0, 0]} barSize={34} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </PremiumCard>
          </div>



          {/* Charts Row */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <SlideIn direction="up" delay={0.6}>
              <ProducaoChart
                data={stats.dadosMensais}
                title="Distribuição Mensal (Reservado vs Realizado)"
                icon={Activity}
              />
            </SlideIn>
            <SlideIn direction="up" delay={0.7}>
              <PremiumCard
                title="Top Clientes por Volume"
                icon={Target}
              >
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats.topClientes} layout="vertical" margin={{ left: 30, right: 30 }}>
                      <XAxis type="number" hide />
                      <YAxis dataKey="name" type="category" tick={{ fill: '#64748b', fontSize: 10, fontWeight: 'bold' }} width={100} axisLine={false} tickLine={false} />
                      <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: 'none', borderRadius: '12px', color: '#fff' }} />
                      <Bar dataKey="reservado" fill="#3b82f6" radius={[0, 4, 4, 0]} name="Volume Reservado" />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </PremiumCard>
            </SlideIn>
          </div>


          {/* Top Clientes e Sequências */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <SlideIn direction="up" delay={0.9}>
              <PremiumCard
                title="Sequências Ativas"
                icon={BarChart3}
                noPadding
                badge={<Badge className="bg-slate-950 dark:bg-white text-white dark:text-slate-900 font-black text-[9px] px-2 py-0.5 rounded-md italic">ANUAL_LOG</Badge>}
              >
                <div className="divide-y divide-slate-100 dark:divide-slate-800/10">
                  {sequencias.filter(s => s.ano === filtroAno).map(seq => (
                    <div key={seq.id} className="flex items-center justify-between p-6 hover:bg-slate-50 dark:hover:bg-white/5 transition-all group relative">
                      <div className="absolute top-0 left-0 w-1 h-0 group-hover:h-full transition-all duration-300 bg-blue-600" />
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-slate-950 dark:bg-white text-white dark:text-slate-900 rounded-2xl flex items-center justify-center font-black text-xl shadow-xl transition-transform group-hover:rotate-6">
                          {seq.letra_produto}
                        </div>
                        <div className="space-y-1">
                          <p className="font-black text-slate-900 dark:text-white text-lg tracking-tighter uppercase italic">{seq.letra_produto} — SERIE 20{seq.ano}</p>
                          <Badge
                            className={cn(
                              "text-[9px] font-black uppercase tracking-[0.2em] px-2 py-0.5 border-0 shadow-sm",
                              seq.encerrado
                                ? "bg-rose-500 text-white"
                                : "bg-emerald-500 text-white"
                            )}
                          >
                            {seq.encerrado ? 'ENCERRADO' : 'EM OPERAÇÃO'}
                          </Badge>
                        </div>
                      </div>
                      <div className="text-right space-y-1">
                        <p className="text-3xl font-black text-slate-900 dark:text-white leading-none italic tracking-tighter">#{seq.ultimo_numero?.toLocaleString()}</p>
